# CONFIGURATION AUTO-LOADER (v14.0)
# ============================================================================
class ConfigurationAutoLoader:
    """Dynamic configuration loader with profile templates and hot-reload"""
    
    PROFILES = {
        'conservative': {
            'min_score': 8.0,
            'max_positions': 1,
            'max_daily_dd': 0.15,
            'scalping_enabled': False,
            'risk_multiplier': 0.5,
            'use_phase_1_signals': True,
            'use_phase_2_arb_signals': False,
            'use_phase_3_microstructure_signals': False,
        },
        'balanced': {
            'min_score': 7.0,
            'max_positions': 3,
            'max_daily_dd': 0.40,
            'scalping_enabled': True,
            'risk_multiplier': 1.0,
            'use_phase_1_signals': True,
            'use_phase_2_arb_signals': True,
            'use_phase_3_microstructure_signals': True,
        },
        'aggressive': {
            'min_score': 6.0,
            'max_positions': 3,
            'max_daily_dd': 0.40,
            'scalping_enabled': True,
            'risk_multiplier': 1.5,
            'use_phase_1_signals': True,
            'use_phase_2_arb_signals': True,
            'use_phase_3_microstructure_signals': True,
        },
    }
    
    def __init__(self, config_file=None, profile='balanced'):
        self.config_file = config_file or 'config.json'
        self.profile = profile
        self.last_load_time = 0
        self.config = CONFIG.copy()
        self._load_config()
    
    def _load_config(self):
        """Load configuration from file with fallback to defaults"""
        try:
            if self.config_file.endswith('.json'):
                import json
                with open(self.config_file, 'r') as f:
                    file_config = json.load(f)
                    self.config.update(file_config)
                    self.last_load_time = time.time()
                    LOG.info(f"[CONFIG] Loaded from {self.config_file}")
            elif self.config_file.endswith('.yaml') or self.config_file.endswith('.yml'):
                import yaml
                with open(self.config_file, 'r') as f:
                    file_config = yaml.safe_load(f)
                    if file_config:
                        self.config.update(file_config)
                        self.last_load_time = time.time()
                        LOG.info(f"[CONFIG] Loaded from {self.config_file}")
        except FileNotFoundError:
            LOG.warning(f"[CONFIG] File not found: {self.config_file}, using defaults")
        except Exception as e:
            LOG.warning(f"[CONFIG] Load error: {e}, using defaults")
        
        # Apply profile if set
        if self.profile in self.PROFILES:
            self.config.update(self.PROFILES[self.profile])
            LOG.info(f"[CONFIG] Applied profile: {self.profile}")
    
    def reload(self):
        """Hot-reload configuration from file"""
        LOG.info("[CONFIG] Hot-reloading configuration...")
        self._load_config()
    
    def get(self, key, default=None):
        """Get config value"""
        return self.config.get(key, default)
    
    def set(self, key, value):
        """Set config value at runtime"""
        self.config[key] = value
        LOG.debug(f"[CONFIG] Set {key} = {value}")
    
    def get_profile(self):
        """Get current profile settings"""
        return self.PROFILES.get(self.profile, {})
    
    def switch_profile(self, profile):
        """Switch to different profile"""
        if profile in self.PROFILES:
            self.profile = profile
            self.config.update(self.PROFILES[profile])
            LOG.info(f"[CONFIG] Switched to profile: {profile}")
            return True
        return False
    
    def export_to_file(self, filename):
        """Export current config to file"""
        try:
            if filename.endswith('.json'):
                import json
                with open(filename, 'w') as f:
                    json.dump(self.config, f, indent=2)
            elif filename.endswith('.yaml') or filename.endswith('.yml'):
                import yaml
                with open(filename, 'w') as f:
                    yaml.dump(self.config, f)
            LOG.info(f"[CONFIG] Exported to {filename}")
        except Exception as e:
            LOG.error(f"[CONFIG] Export error: {e}")

