def safe_float(x, default=0.0):
    """Safely convert to float, handling NaN and exceptions"""
    if isinstance(x, Exception):
        return default
    if x is None:
        return default
    if isinstance(x, float) and np.isnan(x):
        return default
    try:
        return float(x)
    except (ValueError, TypeError):
        return default

