# PHASE 1: DEEP LEARNING SIGNAL GENERATOR
class TransformerEncoder:
    def __init__(self, input_dim=16, d_model=64, nhead=4, nlayers=2, dim_ff=256, seq_length=None, lookback=None):
        self.input_dim, self.d_model, self.nhead, self.nlayers = input_dim, d_model, nhead, nlayers
        self.seq_length = seq_length or 20  # Accept seq_length parameter
        self.lookback = lookback or 20  # Accept lookback parameter
        self.is_trained, self.attention_weights = False, None
    def attention(self, query, key, value, mask=None):
        d_k = query.shape[-1]
        scores = np.matmul(query, key.swapaxes(-2, -1)) / np.sqrt(d_k)
        if mask is not None: scores = np.where(mask, scores, -1e9)
        exp_scores = np.exp(scores - np.max(scores, axis=-1, keepdims=True))
        attn_weights = exp_scores / (np.sum(exp_scores, axis=-1, keepdims=True) + 1e-6)
        return np.matmul(attn_weights, value), attn_weights
    def fit(self, X): self.is_trained = True
    def transform(self, X): return X

class LSTMSequenceModel:
    def __init__(self, seq_length=20, num_features=16, lstm_units=64, lookback=None):
        self.seq_length = lookback or seq_length  # Accept both lookback and seq_length
        self.num_features, self.lstm_units = num_features, lstm_units
        self.hidden_state, self.cell_state, self.is_trained = np.zeros(lstm_units), np.zeros(lstm_units), False
    def fit(self, X_sequences):
        if X_sequences.shape[1] != self.seq_length or X_sequences.shape[2] != self.num_features: return False
        self.is_trained = True
        return True
    def predict_next(self, sequence):
        if not self.is_trained or sequence.shape != (self.seq_length, self.num_features): return None
        return self.hidden_state[:self.num_features]

class DeepLearningSignalGenerator:
    def __init__(self, symbol="XAUUSD", cfg=None):
        self.symbol, self.cfg = symbol, cfg or {}
        self.transformer = TransformerEncoder()
        self.lstm = LSTMSequenceModel(seq_length=20, num_features=16)
        self.price_buffer, self.volume_buffer, self.feature_buffer = deque(maxlen=100), deque(maxlen=100), deque(maxlen=100)
        self.is_trained, self.training_samples, self.signal_history = False, 0, deque(maxlen=100)
    def train_transformer_on_order_flow(self, order_flow_sequences):
        try:
            if order_flow_sequences.size == 0: return False
            self.transformer.fit(order_flow_sequences)
            self.lstm.fit(order_flow_sequences)
            self.training_samples, self.is_trained = len(order_flow_sequences), True
            return True
        except (ValueError, TypeError, AttributeError) as e:
            LOG.warning(f"LSTM training failed: {e}")
            return False
        except Exception as e:
            LOG.error(f"Unexpected error during LSTM training: {type(e).__name__}: {e}")
            return False
    def generate_neural_signals(self, market_data: Dict) -> Dict:
        """Generate neural signals using LSTM or fallback momentum analysis"""
        try:
            close = market_data.get('close', 0)
            volume = market_data.get('volume', 0)
            
            if close <= 0:
                return {'buy_confidence': 0.5, 'sell_confidence': 0.5, 'neural_score': 0.0, 'signal': 0}
            
            self.price_buffer.append(close)
            self.volume_buffer.append(volume)
            
            if len(self.price_buffer) < 5:
                return {'buy_confidence': 0.5, 'sell_confidence': 0.5, 'neural_score': 0.0, 'signal': 0}
            
            prices = np.array(list(self.price_buffer))
            volumes = np.array(list(self.volume_buffer))
            
            # Momentum analysis (price trend)
            momentum = (prices[-1] - prices[0]) / prices[0] if prices[0] != 0 else 0.0
            
            # RSI-like calculation (simplified)
            if len(prices) >= 14:
                deltas = np.diff(prices)
                gains = np.sum(np.maximum(deltas, 0)) / 14
                losses = np.sum(np.maximum(-deltas, 0)) / 14
                rs = gains / (losses + 1e-8)
                rsi = 100 - (100 / (1 + rs))
                rsi_signal = (rsi - 50) / 50  # Normalize to [-1, 1]
            else:
                rsi_signal = 0.0
            
            # Volume trend
            avg_volume = np.mean(volumes[-5:]) if len(volumes) >= 5 else 1.0
            volume_ratio = volumes[-1] / (avg_volume + 1e-8) if avg_volume > 0 else 1.0
            volume_signal = np.clip((volume_ratio - 1.0) / 2.0, -0.5, 0.5)  # Normalize
            
            # Combine signals: momentum (40%), RSI (40%), volume (20%)
            combined_signal = 0.4 * np.clip(momentum * 2, -1, 1) + 0.4 * rsi_signal + 0.2 * volume_signal
            
            # Convert to confidence
            buy_confidence = float(np.clip(0.5 + combined_signal * 0.3, 0.0, 1.0))
            sell_confidence = float(np.clip(0.5 - combined_signal * 0.3, 0.0, 1.0))
            neural_score = float(combined_signal)
            
            # Generate signal: 1=BUY, -1=SELL, 0=NEUTRAL
            signal = 1 if buy_confidence > 0.65 else (-1 if sell_confidence > 0.65 else 0)
            
            return {
                'buy_confidence': buy_confidence,
                'sell_confidence': sell_confidence,
                'neural_score': neural_score,
                'signal': signal,
                'momentum': float(momentum),
                'rsi': float(rsi_signal),
                'volume_signal': float(volume_signal)
            }
        except (ValueError, TypeError, ZeroDivisionError) as e:
            LOG.debug(f"Neural signal calculation failed, using neutral: {e}")
            return {'buy_confidence': 0.5, 'sell_confidence': 0.5, 'neural_score': 0.0, 'signal': 0}
        except Exception as e:
            LOG.error(f"Unexpected neural signal error: {type(e).__name__}: {e}")
            return {'buy_confidence': 0.5, 'sell_confidence': 0.5, 'neural_score': 0.0, 'signal': 0}
    
    def detect_market_manipulation_patterns(self, orderbook: Dict) -> Dict:
        """Detect potential market manipulation patterns in order book"""
        try:
            bids = orderbook.get('bids', [])
            asks = orderbook.get('asks', [])
            
            if len(bids) < 3 or len(asks) < 3:
                return {'spoofing_detected': False, 'spoofing_score': 0.0, 'layering_detected': False, 'layering_score': 0.0}
            
            # Spoofing detection: large orders that disappear quickly
            bid_sizes = np.array([b[1] for b in bids[:5]])
            ask_sizes = np.array([a[1] for a in asks[:5]])
            
            # High variance in sizes = potential spoofing
            bid_variance = np.var(bid_sizes)
            ask_variance = np.var(ask_sizes)
            spoofing_score = float(np.clip((bid_variance + ask_variance) / 1000000, 0, 1))
            spoofing_detected = spoofing_score > 0.6
            
            # Layering detection: many orders at same price
            bid_prices = [b[0] for b in bids[:10]]
            unique_bid_prices = len(set(bid_prices))
            layering_score = float(1.0 - (unique_bid_prices / (len(bid_prices) + 1)))
            layering_detected = layering_score > 0.7
            
            return {
                'spoofing_detected': spoofing_detected,
                'spoofing_score': spoofing_score,
                'layering_detected': layering_detected,
                'layering_score': layering_score
            }
        except Exception as e:
            LOG.warning(f"Market manipulation detection failed: {e}")
            return {'spoofing_detected': False, 'spoofing_score': 0.0, 'layering_detected': False, 'layering_score': 0.0}
    
    def calculate_attention_weights(self) -> Dict:
        """Calculate importance weights for different market signals"""
        try:
            weights = {}
            if len(self.signal_history) > 0:
                # Weight recent signals more heavily
                for i, signal in enumerate(self.signal_history):
                    age = len(self.signal_history) - i
                    weight = 1.0 / (1.0 + 0.1 * age)  # Exponential decay
                    weights[f"signal_{i}"] = weight
            return weights
        except Exception as e:
            LOG.debug(f"Attention weight calculation failed: {e}")
            return {}

class OrderBookAnalytics:
    def __init__(self, symbol="XAUUSD", max_depth=20):
        self.symbol, self.max_depth = symbol, max_depth
        self.metrics_history = deque(maxlen=100)
    def analyze_orderbook(self, bids: List, asks: List) -> Dict:
        try:
            bid_vols = np.array([b[1] for b in bids[:self.max_depth]]) if bids else np.array([])
            ask_vols = np.array([a[1] for a in asks[:self.max_depth]]) if asks else np.array([])
            total_vol = bid_vols.sum() + ask_vols.sum()
            imbalance = (bid_vols.sum() - ask_vols.sum()) / (total_vol + 1e-8)
            return {'imbalance': float(imbalance), 'depth_ratio': 0.5, 'micro_price': 0.0, 'price_impact': 0.0}
        except (ValueError, TypeError, IndexError) as e:
            LOG.warning(f"OrderBook analysis failed: {e}")
            return {'imbalance': 0.0, 'depth_ratio': 0.5, 'micro_price': 0.0, 'price_impact': 0.0}
        except Exception as e:
            LOG.error(f"Unexpected OrderBook error: {type(e).__name__}: {e}")
            return {'imbalance': 0.0, 'depth_ratio': 0.5, 'micro_price': 0.0, 'price_impact': 0.0}

class StatisticalArbitrageEngine:
    def __init__(self):
        self.pairs, self.spread_history, self.active_positions = {}, {}, {}
        self.performance = {'total_trades': 0, 'winning_trades': 0, 'total_pnl': 0.0}
        self.pair_data = {}  # Store historical data for pair analysis
        self.last_update = None
    
    def update_with_market_data(self, symbol: str, prices: List[float], volumes: List[float] = None):
        """Update engine with new market data for pair analysis"""
        try:
            if symbol not in self.pair_data:
                self.pair_data[symbol] = {'prices': deque(maxlen=1000), 'volumes': deque(maxlen=1000)}
            
            self.pair_data[symbol]['prices'].extend(prices[-10:])  # Keep last 10
            if volumes:
                self.pair_data[symbol]['volumes'].extend(volumes[-10:])
            self.last_update = utc_now()
        except Exception as e:
            LOG.debug(f"Failed to update market data: {e}")
    
    def identify_cointegrated_pairs(self, price_data: Dict, window=252) -> List:
        """Identify cointegrated pairs using correlation + divergence"""
        pairs = []
        try:
            symbols = list(price_data.keys())
            if len(symbols) < 2:
                return pairs
            
            # Simple cointegration check using correlation + divergence
            price_arrays = {}
            for s in symbols:
                prices = price_data.get(s, [])
                if isinstance(prices, (list, tuple)):
                    price_arrays[s] = np.array(prices[-window:]) if len(prices) >= window else np.array(prices)
                else:
                    price_arrays[s] = np.array([prices])
            
            for i, sym1 in enumerate(symbols):
                for sym2 in symbols[i+1:]:
                    if sym1 not in price_arrays or sym2 not in price_arrays:
                        continue
                    
                    prices1 = price_arrays[sym1]
                    prices2 = price_arrays[sym2]
                    
                    if len(prices1) < 20 or len(prices2) < 20:
                        continue
                    
                    # Calculate correlation of returns
                    try:
                        returns1 = np.diff(np.log(prices1 + 1e-8))
                        returns2 = np.diff(np.log(prices2 + 1e-8))
                        correlation = safe_correlation(returns1, returns2)
                        
                        # Look for highly correlated pairs (potential cointegration)
                        if not np.isnan(correlation) and correlation > 0.65:
                            pairs.append({
                                'asset1': sym1,
                                'asset2': sym2,
                                'correlation': float(correlation),
                                'timestamp': utc_now().isoformat()
                            })
                    except Exception as e:
                        LOG.debug(f"Correlation calculation failed for {sym1}-{sym2}: {e}")
                        continue
            
            return pairs
        except Exception as e:
            LOG.warning(f"Cointegration identification error: {e}")
            return pairs
    
    def calculate_optimal_hedge_ratio(self, asset1_prices, asset2_prices, lookback=252) -> float:
        """Calculate optimal hedge ratio using OLS regression"""
        try:
            prices1 = np.array(asset1_prices[-lookback:]) if len(asset1_prices) >= lookback else np.array(asset1_prices)
            prices2 = np.array(asset2_prices[-lookback:]) if len(asset2_prices) >= lookback else np.array(asset2_prices)
            
            if len(prices1) < 20 or len(prices2) < 20:
                return 1.0
            
            # OLS: asset1 = alpha + beta*asset2
            X = np.column_stack([np.ones(len(prices2)), prices2])
            y = prices1
            beta = np.linalg.lstsq(X, y, rcond=None)[0][1]
            
            return float(max(0.1, min(10.0, beta)))
        except (ValueError, TypeError, np.linalg.LinAlgError) as e:
            LOG.warning(f"Hedge ratio calculation failed, using default: {e}")
            return 1.0
        except Exception as e:
            LOG.error(f"Unexpected error in hedge calculation: {type(e).__name__}: {e}")
            return 1.0
    
    def calculate_spread_metrics(self, asset1_prices, asset2_prices, hedge_ratio) -> Dict:
        """Calculate spread z-score and half-life for mean reversion"""
        try:
            prices1 = np.array(asset1_prices[-252:]) if len(asset1_prices) >= 252 else np.array(asset1_prices)
            prices2 = np.array(asset2_prices[-252:]) if len(asset2_prices) >= 252 else np.array(asset2_prices)
            
            if len(prices1) < 20 or len(prices2) < 20:
                return {'zscore': 0.0, 'half_life': 0.0, 'spread_current': 0.0}
            
            # Spread = price1 - hedge_ratio * price2
            spread = prices1 - hedge_ratio * prices2
            mean_spread = np.mean(spread)
            std_spread = np.std(spread)
            current_spread = spread[-1]
            zscore = (current_spread - mean_spread) / (std_spread + 1e-8)
            
            # Half-life calculation (exponential decay)
            if len(spread) > 1:
                diffs = np.diff(spread)
                autocorr = safe_correlation(spread[:-1], spread[1:])
                half_life = -np.log(2) / np.log(max(-0.99, min(0.99, autocorr))) if abs(autocorr) > 0.01 else 1.0
            else:
                half_life = 1.0
            
            return {
                'zscore': float(zscore),
                'half_life': float(half_life),
                'spread_current': float(current_spread)
            }
        except Exception as e:
            LOG.error(f"Spread metrics error: {e}")
            return {'zscore': 0.0, 'half_life': 0.0, 'spread_current': 0.0}
    
    def generate_pair_signals(self, pair_config, metrics: Dict) -> Dict:
        """Generate trading signals based on spread metrics"""
        try:
            zscore = metrics.get('zscore', 0.0)
            
            # Entry signals when spread is extreme (> 2 std dev)
            if zscore > 2.0:
                return {
                    'action': 'SELL_SPREAD',  # Sell overvalued asset, buy undervalued
                    'confidence': min(0.95, (abs(zscore) - 2.0) / 3.0),
                    'position_size': 0.5
                }
            elif zscore < -2.0:
                return {
                    'action': 'BUY_SPREAD',
                    'confidence': min(0.95, (abs(zscore) - 2.0) / 3.0),
                    'position_size': 0.5
                }
            else:
                return {'action': 'HOLD', 'confidence': 0.0, 'position_size': 0.0}
        except Exception as e:
            LOG.error(f"Pair signal generation error: {e}")
            return {'action': 'HOLD', 'confidence': 0.0, 'position_size': 0.0}

# PHASE 2.1: EXECUTION OPTIMIZER
class ExecutionSlice:
    def __init__(self, slice_id, quantity, target_time, target_price=None, scheduled_time=None, executed_qty=0.0, executed_price=0.0, status="PENDING"):
        self.slice_id, self.quantity, self.target_time, self.target_price = slice_id, quantity, target_time, target_price
        self.scheduled_time, self.executed_qty, self.executed_price, self.status = scheduled_time, executed_qty, executed_price, status

class TWAPExecutor:
    def __init__(self, symbol: str, total_qty: float, duration_minutes: int = 30, slices: int = 10):
        self.symbol, self.total_qty, self.num_slices = symbol, total_qty, slices
        self.slice_qty = total_qty / slices
        self.slice_interval = timedelta(minutes=duration_minutes / slices)
        self.execution_plan, self.filled_slices, self.market_prices, self.start_time = [], [], [], None
        self._generate_plan()
    def _generate_plan(self):
        self.start_time = datetime.now()
        for i in range(self.num_slices):
            scheduled_time = self.start_time + (i * self.slice_interval)
            self.execution_plan.append(ExecutionSlice(i, self.slice_qty, scheduled_time, scheduled_time=scheduled_time, status="PENDING"))
    def get_next_slice(self) -> Optional[ExecutionSlice]:
        now = datetime.now()
        for slice_obj in self.execution_plan:
            if slice_obj.status == "PENDING" and now >= slice_obj.target_time: return slice_obj
        return None
    def record_execution(self, slice_id: int, executed_qty: float, executed_price: float):
        if 0 <= slice_id < len(self.execution_plan):
            slice_obj = self.execution_plan[slice_id]
            slice_obj.executed_qty, slice_obj.executed_price = executed_qty, executed_price
            slice_obj.status = "FILLED" if executed_qty >= slice_obj.quantity else "PARTIAL"
            self.market_prices.append(executed_price)
            self.filled_slices.append(slice_obj)

class VWAPExecutor:
    def __init__(self, symbol: str, total_qty: float, volume_data=None, time_horizon: int = 60):
        self.symbol, self.total_qty, self.time_horizon = symbol, total_qty, time_horizon
        self.time_slices, self.execution_plan, self.filled_slices, self.market_prices = [], [], [], []
        self._calculate_volume_profile()
        self._generate_plan()
    def _calculate_volume_profile(self):
        self.time_slices = [(i, 1.0 / 60) for i in range(self.time_horizon)]
    def _generate_plan(self):
        for i, (minute, vol_pct) in enumerate(self.time_slices):
            slice_qty = self.total_qty * vol_pct
            scheduled_time = datetime.now() + timedelta(minutes=minute)
            self.execution_plan.append(ExecutionSlice(i, slice_qty, scheduled_time, scheduled_time=scheduled_time))
    def get_next_slice(self) -> Optional[ExecutionSlice]:
        now = datetime.now()
        for slice_obj in self.execution_plan:
            if slice_obj.status == "PENDING" and now >= slice_obj.target_time: return slice_obj
        return None
    def record_execution(self, slice_id: int, executed_qty: float, executed_price: float):
        if 0 <= slice_id < len(self.execution_plan):
            self.execution_plan[slice_id].executed_qty, self.execution_plan[slice_id].executed_price = executed_qty, executed_price
            self.market_prices.append(executed_price)

class IcebergOrderExecutor:
    def __init__(self, symbol: str, total_qty: float, visible_qty: float):
        self.symbol, self.total_qty, self.visible_qty = symbol, total_qty, visible_qty
        self.current_visible_qty, self.current_hidden_qty = visible_qty, total_qty - visible_qty
        self.filled_qty = 0.0
    def record_partial_fill(self, filled_qty: float, fill_price: float):
        self.filled_qty += filled_qty
        self.current_visible_qty -= filled_qty
        self.current_hidden_qty -= filled_qty
    def get_completion_percentage(self) -> float:
        return (self.filled_qty / self.total_qty) * 100 if self.total_qty > 0 else 100.0
    def get_metrics(self) -> Dict:
        return {'total_qty': self.total_qty, 'filled_qty': self.filled_qty, 'completion_pct': self.get_completion_percentage()}

class ExecutionOptimizer:
    def __init__(self, symbol: str):
        self.symbol = symbol
        self.active_executions = {}
        self.execution_counter = 0
        self.execution_history = deque(maxlen=100)
        self.performance = {'total_executed': 0.0, 'avg_slippage': 0.0, 'total_fees': 0.0}
    
    def create_twap_execution(self, qty: float, duration_minutes: int = 30, slices: int = 10):
        """Create a TWAP (Time-Weighted Average Price) execution"""
        try:
            executor = TWAPExecutor(self.symbol, qty, duration_minutes, slices)
            exec_id = self.execution_counter
            self.active_executions[exec_id] = executor
            self.execution_counter += 1
            LOG.info(f"[EXEC] Created TWAP execution: {exec_id}, qty={qty:.4f}, duration={duration_minutes}min")
            return executor
        except Exception as e:
            LOG.error(f"Failed to create TWAP execution: {e}")
            return None
    
    def create_vwap_execution(self, qty: float, volume_data=None, time_horizon: int = 60):
        """Create a VWAP (Volume-Weighted Average Price) execution"""
        try:
            executor = VWAPExecutor(self.symbol, qty, volume_data, time_horizon)
            exec_id = self.execution_counter
            self.active_executions[exec_id] = executor
            self.execution_counter += 1
            LOG.info(f"[EXEC] Created VWAP execution: {exec_id}, qty={qty:.4f}, horizon={time_horizon}min")
            return executor
        except Exception as e:
            LOG.error(f"Failed to create VWAP execution: {e}")
            return None
    
    def create_iceberg_execution(self, qty: float, visible_qty: float):
        """Create an Iceberg execution strategy"""
        try:
            executor = IcebergOrderExecutor(self.symbol, qty, visible_qty)
            exec_id = self.execution_counter
            self.active_executions[exec_id] = executor
            self.execution_counter += 1
            LOG.info(f"[EXEC] Created Iceberg execution: {exec_id}, total={qty:.4f}, visible={visible_qty:.4f}")
            return executor
        except Exception as e:
            LOG.error(f"Failed to create Iceberg execution: {e}")
            return None
    
    def get_optimal_algorithm(self, qty: float, volatility: float, market_depth: float, time_available: int) -> str:
        """Select optimal execution algorithm based on market conditions"""
        try:
            # Algorithm selection logic
            if volatility > 0.30 and time_available < 30:
                # High volatility, limited time → TWAP to minimize market impact
                return "TWAP"
            elif volatility < 0.15 and time_available > 60:
                # Low volatility, plenty of time → VWAP to track volume
                return "VWAP"
            elif market_depth < 0.3 and qty > 10000:
                # Illiquid market, large order → Iceberg to hide intention
                return "ICEBERG"
            else:
                # Standard conditions
                return "MARKET"
        except Exception as e:
            LOG.debug(f"Algorithm selection error: {e}")
            return "MARKET"
    
    def process_active_executions(self, current_price: float, current_time: int) -> Dict:
        """Process all active executions and return status updates"""
        try:
            results = {'completed': [], 'active': [], 'failed': []}
            completed_ids = []
            
            for exec_id, executor in list(self.active_executions.items()):
                try:
                    # Get execution status (would check actual executor state)
                    executed_qty = getattr(executor, 'total_executed', 0.0)
                    total_qty = getattr(executor, 'total_qty', 0.0)
                    
                    if executed_qty >= total_qty * 0.99:  # Consider >99% as completed
                        results['completed'].append({
                            'id': exec_id,
                            'qty': executed_qty,
                            'algorithm': executor.__class__.__name__
                        })
                        completed_ids.append(exec_id)
                        self.performance['total_executed'] += executed_qty
                    else:
                        results['active'].append({
                            'id': exec_id,
                            'progress': executed_qty / total_qty if total_qty > 0 else 0.0,
                            'algorithm': executor.__class__.__name__
                        })
                except Exception as e:
                    LOG.warning(f"Error processing execution {exec_id}: {e}")
                    results['failed'].append({'id': exec_id, 'error': str(e)})
            
            # Remove completed executions
            for exec_id in completed_ids:
                del self.active_executions[exec_id]
            
            return results
        except Exception as e:
            LOG.error(f"Failed to process active executions: {e}")
            return {'completed': [], 'active': [], 'failed': []}

# ============================================================================
# v15.0 EXECUTION OPTIMIZATION - MARKET IMPACT MINIMIZATION
# ============================================================================
class MarketImpactOptimizer:
    """Advanced execution optimization to minimize market impact and slippage
    
    Strategies:
    - TWAP: Time-Weighted Average Price (minimize time-based impact)
    - VWAP: Volume-Weighted Average Price (follow market volume)
    - Iceberg: Hide order size to reduce front-running risk
    - Adaptive: Automatically switch based on market conditions
    """
    
    def __init__(self, symbol: str, cfg=None):
        self.symbol = symbol
        self.cfg = cfg or CFG
        self.execution_history = deque(maxlen=500)
        self.slippage_stats = {'total': 0, 'count': 0, 'avg': 0.0}
        self.impact_metrics = {
            'twap_impact': [],
            'vwap_impact': [],
            'iceberg_impact': [],
            'market_impact': []
        }
    
    def calculate_market_impact(self, quantity: float, bid_ask_depth: float, volatility: float) -> float:
        """Estimate market impact of order
        
        Market impact = f(quantity, liquidity, volatility)
        Lower is better (less price movement)
        """
        try:
            # Impact function: I = (Q / D) * (1 + V)
            # Q = quantity, D = market depth, V = volatility
            if bid_ask_depth <= 0:
                bid_ask_depth = 0.1
            
            impact_pips = (quantity / (bid_ask_depth + 1e-8)) * (1 + volatility)
            return float(np.clip(impact_pips, 0, 100))
        except:
            return 1.0
    
    def calculate_slippage(self, planned_price: float, execution_price: float, direction: int) -> float:
        """Calculate execution slippage
        
        Negative slippage = favorable (better than planned)
        Positive slippage = unfavorable (worse than planned)
        """
        try:
            if direction == 1:  # BUY
                slippage = (execution_price - planned_price) / planned_price * 10000  # in pips
            else:  # SELL
                slippage = (planned_price - execution_price) / planned_price * 10000
            
            return float(slippage)
        except:
            return 0.0
    
    def estimate_execution_time(self, quantity: float, algorithm: str, market_conditions: str) -> float:
        """Estimate execution time in seconds based on algorithm and conditions"""
        try:
            base_times = {
                'MARKET': 1.0,           # Immediate
                'TWAP': 30 * 60,         # 30 minutes spread
                'VWAP': 60 * 60,         # 60 minutes
                'ICEBERG': 45 * 60       # 45 minutes
            }
            
            time_est = base_times.get(algorithm, 30 * 60)
            
            # Adjust for market conditions
            volatility_mult = {
                'quiet': 0.8,
                'normal': 1.0,
                'volatile': 1.5,
                'extreme': 2.0
            }
            
            mult = volatility_mult.get(market_conditions, 1.0)
            return float(time_est * mult)
        except:
            return 1800.0  # 30 minutes default
    
    def select_optimal_execution(self, quantity: float, bid_ask_depth: float, 
                                volatility: float, time_available: int) -> Dict:
        """Select optimal execution algorithm
        
        Returns:
        - algorithm: Recommended algorithm (TWAP/VWAP/ICEBERG/MARKET)
        - reason: Why this was chosen
        - expected_impact: Estimated market impact in pips
        - slippage_risk: Risk level (LOW/MEDIUM/HIGH)
        """
        try:
            impact_twap = self.calculate_market_impact(quantity * 0.1, bid_ask_depth, volatility)
            impact_vwap = self.calculate_market_impact(quantity * 0.15, bid_ask_depth, volatility)
            impact_iceberg = self.calculate_market_impact(quantity * 0.05, bid_ask_depth, volatility)
            impact_market = self.calculate_market_impact(quantity, bid_ask_depth, volatility)
            
            # Algorithm selection logic
            reason = ""
            algorithm = "MARKET"
            
            if time_available < 60 and volatility > 0.02:
                # Limited time, high vol → quick execution
                algorithm = "MARKET"
                reason = "Quick execution required"
            elif time_available > 1800 and volatility < 0.01:
                # Plenty of time, low vol → VWAP to track volume
                algorithm = "VWAP"
                reason = "Follow market volume"
            elif quantity > 100 and bid_ask_depth < 50:
                # Large order, illiquid market → Iceberg to hide
                algorithm = "ICEBERG"
                reason = "Hide order size"
            elif 300 < time_available < 1800:
                # Medium time → TWAP for steady execution
                algorithm = "TWAP"
                reason = "Steady execution"
            
            impacts = {
                'TWAP': impact_twap,
                'VWAP': impact_vwap,
                'ICEBERG': impact_iceberg,
                'MARKET': impact_market
            }
            
            expected_impact = impacts.get(algorithm, impact_market)
            
            # Risk classification
            if expected_impact > 2.0:
                slippage_risk = "HIGH"
            elif expected_impact > 0.5:
                slippage_risk = "MEDIUM"
            else:
                slippage_risk = "LOW"
            
            return {
                'algorithm': algorithm,
                'reason': reason,
                'expected_impact': expected_impact,
                'slippage_risk': slippage_risk,
                'impacts': impacts
            }
        except Exception as e:
            LOG.warning(f"[IMPACT] Algorithm selection error: {e}")
            return {
                'algorithm': 'MARKET',
                'reason': 'Error in selection, using market execution',
                'expected_impact': 1.0,
                'slippage_risk': 'MEDIUM',
                'impacts': {}
            }
    
    def log_execution(self, execution_data: Dict):
        """Log execution for analysis"""
        try:
            self.execution_history.append({
                'timestamp': datetime.now(),
                'algorithm': execution_data.get('algorithm'),
                'quantity': execution_data.get('quantity'),
                'planned_price': execution_data.get('planned_price'),
                'execution_price': execution_data.get('execution_price'),
                'slippage': execution_data.get('slippage'),
                'impact': execution_data.get('impact')
            })
            
            # Update statistics
            slippage = execution_data.get('slippage', 0)
            self.slippage_stats['total'] += slippage
            self.slippage_stats['count'] += 1
            if self.slippage_stats['count'] > 0:
                self.slippage_stats['avg'] = self.slippage_stats['total'] / self.slippage_stats['count']
        except Exception as e:
            LOG.debug(f"[IMPACT] Execution logging error: {e}")
    
    def get_statistics(self) -> Dict:
        """Get execution statistics"""
        return {
            'total_executions': self.slippage_stats['count'],
            'avg_slippage': round(self.slippage_stats['avg'], 4),
            'total_slippage': round(self.slippage_stats['total'], 2),
            'history_size': len(self.execution_history)
        }

# ============================================================================
# v15.0 LIVE MARKET DATA - REAL-TIME TICK FEED INTEGRATION
# ============================================================================
class LiveMarketDataFeed:
    """Real-time market data feed with tick-level granularity
    
    Features:
    - Bid/ask tick stream
    - Order book snapshots
    - Trade tick processing
    - Event-driven updates (no polling)
    """
    
    def __init__(self, symbol: str, buffer_size: int = 10000):
        self.symbol = symbol
        self.buffer_size = buffer_size
        
        # Tick data buffers
        self.bid_ticks = deque(maxlen=buffer_size)
        self.ask_ticks = deque(maxlen=buffer_size)
        self.trade_ticks = deque(maxlen=buffer_size)
        self.tick_events = deque(maxlen=1000)
        
        # Market microstructure
        self.bid_ask_spread = 0.0
        self.mid_price = 0.0
        self.last_update_time = 0.0
        self.tick_count = 0
        
        # Statistics
        self.tick_stats = {
            'bid_updates': 0,
            'ask_updates': 0,
            'trade_updates': 0,
            'spread_min': float('inf'),
            'spread_max': 0,
            'spread_avg': 0
        }
    
    def process_bid_tick(self, price: float, quantity: float, timestamp: float = None):
        """Process incoming bid tick
        
        Args:
            price: Bid price
            quantity: Bid quantity at this price
            timestamp: Event timestamp
        """
        try:
            if timestamp is None:
                timestamp = time.time()
            
            bid_tick = {
                'price': float(price),
                'quantity': float(quantity),
                'timestamp': timestamp
            }
            
            self.bid_ticks.append(bid_tick)
            self.mid_price = (price + self.ask_ticks[-1]['price']) / 2 if self.ask_ticks else price
            self._update_spread()
            self.tick_stats['bid_updates'] += 1
            self.last_update_time = timestamp
            self._record_tick_event('BID', price, quantity)
            
        except Exception as e:
            LOG.debug(f"[LIVE_DATA] Bid tick error: {e}")
    
    def process_ask_tick(self, price: float, quantity: float, timestamp: float = None):
        """Process incoming ask tick"""
        try:
            if timestamp is None:
                timestamp = time.time()
            
            ask_tick = {
                'price': float(price),
                'quantity': float(quantity),
                'timestamp': timestamp
            }
            
            self.ask_ticks.append(ask_tick)
            self.mid_price = (self.bid_ticks[-1]['price'] + price) / 2 if self.bid_ticks else price
            self._update_spread()
            self.tick_stats['ask_updates'] += 1
            self.last_update_time = timestamp
            self._record_tick_event('ASK', price, quantity)
            
        except Exception as e:
            LOG.debug(f"[LIVE_DATA] Ask tick error: {e}")
    
    def process_trade_tick(self, price: float, quantity: float, side: str, timestamp: float = None):
        """Process trade execution tick
        
        Args:
            price: Trade execution price
            quantity: Trade quantity
            side: 'BUY' or 'SELL'
            timestamp: Trade time
        """
        try:
            if timestamp is None:
                timestamp = time.time()
            
            trade_tick = {
                'price': float(price),
                'quantity': float(quantity),
                'side': side,
                'timestamp': timestamp
            }
            
            self.trade_ticks.append(trade_tick)
            self.tick_stats['trade_updates'] += 1
            self.last_update_time = timestamp
            self._record_tick_event('TRADE', price, quantity)
            
        except Exception as e:
            LOG.debug(f"[LIVE_DATA] Trade tick error: {e}")
    
    def _update_spread(self):
        """Update bid-ask spread statistics"""
        try:
            if self.bid_ticks and self.ask_ticks:
                latest_bid = self.bid_ticks[-1]['price']
                latest_ask = self.ask_ticks[-1]['price']
                spread = latest_ask - latest_bid
                
                self.bid_ask_spread = spread
                self.tick_stats['spread_min'] = min(self.tick_stats['spread_min'], spread)
                self.tick_stats['spread_max'] = max(self.tick_stats['spread_max'], spread)
                
                # Update average
                all_spreads = [
                    self.ask_ticks[-i]['price'] - self.bid_ticks[-i]['price']
                    for i in range(1, min(len(self.bid_ticks), len(self.ask_ticks), 100) + 1)
                ]
                if all_spreads:
                    self.tick_stats['spread_avg'] = float(np.mean(all_spreads))
        except Exception as e:
            LOG.debug(f"[LIVE_DATA] Spread update error: {e}")
    
    def _record_tick_event(self, event_type: str, price: float, quantity: float):
        """Record tick event for analysis"""
        try:
            self.tick_events.append({
                'type': event_type,
                'price': price,
                'quantity': quantity,
                'timestamp': time.time(),
                'mid_price': self.mid_price,
                'spread': self.bid_ask_spread
            })
            self.tick_count += 1
        except Exception as e:
            LOG.debug(f"[LIVE_DATA] Event recording error: {e}")
    
    def get_current_market(self) -> Dict:
        """Get current market snapshot
        
        Returns:
            - bid_price: Latest bid price
            - ask_price: Latest ask price
            - mid_price: Midpoint (bid + ask) / 2
            - spread: Bid-ask spread in pips
            - bid_quantity: Quantity at bid
            - ask_quantity: Quantity at ask
        """
        try:
            bid_price = self.bid_ticks[-1]['price'] if self.bid_ticks else 0
            ask_price = self.ask_ticks[-1]['price'] if self.ask_ticks else 0
            bid_qty = self.bid_ticks[-1]['quantity'] if self.bid_ticks else 0
            ask_qty = self.ask_ticks[-1]['quantity'] if self.ask_ticks else 0
            
            spread_pips = (ask_price - bid_price) * 100 if (ask_price - bid_price) > 0 else 0
            
            return {
                'bid_price': bid_price,
                'ask_price': ask_price,
                'mid_price': self.mid_price,
                'bid_quantity': bid_qty,
                'ask_quantity': ask_qty,
                'spread': self.bid_ask_spread,
                'spread_pips': spread_pips,
                'timestamp': self.last_update_time
            }
        except Exception as e:
            LOG.debug(f"[LIVE_DATA] Snapshot error: {e}")
            return {}
    
    def get_tick_statistics(self) -> Dict:
        """Get tick stream statistics"""
        return self.tick_stats.copy()
    
    def get_recent_ticks(self, count: int = 10) -> Dict:
        """Get recent ticks for analysis
        
        Returns: {'bids': [...], 'asks': [...], 'trades': [...]}
        """
        try:
            return {
                'bids': list(self.bid_ticks)[-count:],
                'asks': list(self.ask_ticks)[-count:],
                'trades': list(self.trade_ticks)[-count:]
            }
        except Exception as e:
            LOG.debug(f"[LIVE_DATA] Recent ticks error: {e}")
            return {'bids': [], 'asks': [], 'trades': []}
    
    def detect_flash_crash(self, threshold_pct: float = 5.0) -> Dict:
        """Detect potential flash crash (rapid large price move)
        
        Args:
            threshold_pct: Price change threshold (%)
        
        Returns: {'detected': bool, 'severity': 0-1, 'change_pct': float}
        """
        try:
            if len(self.trade_ticks) < 10:
                return {'detected': False, 'severity': 0.0, 'change_pct': 0.0}
            
            prices = [t['price'] for t in list(self.trade_ticks)[-10:]]
            price_change_pct = abs((prices[-1] - prices[0]) / prices[0]) * 100 if prices[0] > 0 else 0
            
            detected = price_change_pct > threshold_pct
            severity = min(price_change_pct / threshold_pct, 1.0)
            
            return {
                'detected': detected,
                'severity': severity,
                'change_pct': price_change_pct
            }
        except Exception as e:
            LOG.debug(f"[LIVE_DATA] Flash crash detection error: {e}")
            return {'detected': False, 'severity': 0.0, 'change_pct': 0.0}

# ============================================================================
# PANIC CANDLE PROTECTOR - EMERGENCY TRADE CLOSURE ON EXTREME MOVES
# ============================================================================
class PanicCandleProtector:
    """Emergency protection against panic candles (extreme move candles)
    
    Monitors open trades and closes them if candles move >3x ATR against position.
    Prevents catastrophic losses from flash crashes or extreme volatility.
    """
    
    def __init__(self, cfg=None):
        self.cfg = cfg or CFG
        self.atr_period = cfg.get('atr_period', 14) if cfg else 14
        self.panic_threshold_multiplier = 3.0  # 3x ATR
        self.protection_active = True
        self.emergency_closures = deque(maxlen=100)
        self.monitoring_history = deque(maxlen=500)
        self.stats = {
            'trades_monitored': 0,
            'emergency_closes': 0,
            'trades_saved': 0,
            'avg_loss_prevented': 0.0
        }
    
    def check_panic_condition(self, trade: Dict, current_candle: Dict, atr: float) -> Dict:
        """Check if current candle represents panic (extreme move)
        
        Args:
            trade: Open trade dict with 'entry', 'dir', 'sl'
            current_candle: OHLC dict with 'open', 'high', 'low', 'close'
            atr: Current ATR value
        
        Returns: {'is_panic': bool, 'severity': float, 'action': str}
        """
        try:
            if atr <= 0:
                return {'is_panic': False, 'severity': 0.0, 'action': 'NONE'}
            
            entry_price = float(trade.get('entry', 0))
            direction = int(trade.get('dir', 0))
            high = float(current_candle.get('high', 0))
            low = float(current_candle.get('low', 0))
            close = float(current_candle.get('close', 0))
            
            panic_threshold = self.panic_threshold_multiplier * atr
            
            # Calculate move against position
            if direction == 1:  # LONG position
                move_against = entry_price - low  # How far below entry
            else:  # SHORT position
                move_against = high - entry_price  # How far above entry
            
            severity = move_against / (panic_threshold + 1e-8)
            is_panic = severity > 1.0  # Move > 3x ATR
            
            action = 'NONE'
            if is_panic and severity > 2.0:
                action = 'CLOSE_IMMEDIATELY'
            elif is_panic and severity > 1.0:
                action = 'CLOSE_ON_NEXT_CANDLE'
            
            return {
                'is_panic': is_panic,
                'severity': float(severity),
                'action': action,
                'move_against': float(move_against),
                'threshold': float(panic_threshold)
            }
        except Exception as e:
            LOG.debug(f"[PANIC] Condition check error: {e}")
            return {'is_panic': False, 'severity': 0.0, 'action': 'NONE'}
    
    def should_emergency_close(self, trade: Dict, current_candle: Dict, atr: float) -> bool:
        """Determine if trade should be emergency closed"""
        try:
            check = self.check_panic_condition(trade, current_candle, atr)
            return check.get('is_panic', False) and check.get('severity', 0) > 1.5
        except Exception as e:
            LOG.debug(f"[PANIC] Emergency close check error: {e}")
            return False
    
    def execute_emergency_close(self, trade: Dict, close_price: float, reason: str = "PANIC") -> Dict:
        """Execute emergency market close at current price
        
        Returns: {'success': bool, 'ticket': int, 'close_price': float, 'loss': float}
        """
        try:
            entry = float(trade.get('entry', 0))
            size = float(trade.get('size', 0))
            direction = int(trade.get('dir', 0))
            ticket = trade.get('ticket', 0)
            
            # Calculate loss
            if direction == 1:  # LONG
                loss = (entry - close_price) * size * 100  # Loss in USD (approx)
            else:  # SHORT
                loss = (close_price - entry) * size * 100
            
            # Log emergency closure
            self.emergency_closures.append({
                'ticket': ticket,
                'entry': entry,
                'close_price': close_price,
                'size': size,
                'direction': direction,
                'loss': loss,
                'reason': reason,
                'timestamp': datetime.now().isoformat()
            })
            
            self.stats['emergency_closes'] += 1
            self.stats['trades_saved'] += 1
            if self.stats['emergency_closes'] > 0:
                self.stats['avg_loss_prevented'] = sum(
                    c['loss'] for c in list(self.emergency_closures)[-20:]
                ) / min(20, len(self.emergency_closures))
            
            LOG.warning(f"[PANIC] Emergency close! Ticket={ticket}, Loss={loss:.2f}, Reason={reason}")
            
            return {
                'success': True,
                'ticket': ticket,
                'close_price': close_price,
                'loss': loss,
                'reason': reason
            }
        except Exception as e:
            LOG.error(f"[PANIC] Emergency close execution failed: {e}")
            return {
                'success': False,
                'ticket': trade.get('ticket', 0),
                'close_price': close_price,
                'loss': 0.0,
                'reason': f"Error: {e}"
            }
    
    def monitor_trades(self, trades: List[Dict], current_candle: Dict, atr: float) -> List[Dict]:
        """Monitor multiple trades for panic conditions
        
        Returns list of recommended emergency closes
        """
        try:
            self.stats['trades_monitored'] = len(trades)
            emergency_recommendations = []
            
            for trade in trades:
                check = self.check_panic_condition(trade, current_candle, atr)
                self.monitoring_history.append({
                    'timestamp': datetime.now().isoformat(),
                    'ticket': trade.get('ticket'),
                    'check': check
                })
                
                if check.get('is_panic', False) and check.get('severity', 0) > 1.5:
                    emergency_recommendations.append({
                        'ticket': trade.get('ticket'),
                        'action': check.get('action'),
                        'severity': check.get('severity'),
                        'recommended_close_price': current_candle.get('close')
                    })
            
            return emergency_recommendations
        except Exception as e:
            LOG.error(f"[PANIC] Trade monitoring error: {e}")
            return []
    
    def get_stats(self) -> Dict:
        """Get panic protection statistics"""
        return self.stats.copy()

# PHASE 2.2: MICROSTRUCTURE ALPHA
class OrderFlowAnalyzer:
    """Phase 3: Market Microstructure Analysis
    
    Analyzes order flow patterns to detect informed trading activity
    and market manipulation indicators.
    """
    def __init__(self, symbol: str, lookback_bars: int = 100):
        self.symbol = symbol
        self.lookback_bars = lookback_bars
        self.order_flow_history = deque(maxlen=lookback_bars)
        self.tick_data = deque(maxlen=1000)
        self.price_levels = {}
        self.order_book_snapshot = {'bids': deque(maxlen=10), 'asks': deque(maxlen=10)}
        self.bid_ask_spreads = deque(maxlen=100)
        self.trade_intensity = deque(maxlen=50)
        self.momentum_orders = deque(maxlen=50)
    
    def process_tick(self, price: float, volume: float, ask_price: float = None, bid_price: float = None):
        """Process incoming market tick to classify buy/sell pressure"""
        try:
            if ask_price is None or bid_price is None:
                ask_price, bid_price = price + 0.001, price - 0.001
            
            mid = (ask_price + bid_price) / 2
            buyer_initiated = price >= mid
            delta = volume if buyer_initiated else -volume
            
            tick_info = {
                'price': price,
                'volume': volume,
                'side': 'BUY' if buyer_initiated else 'SELL',
                'delta': delta,
                'spread': ask_price - bid_price,
                'timestamp': time.time()
            }
            
            self.order_flow_history.append(tick_info)
            self.tick_data.append(tick_info)
            self.bid_ask_spreads.append(ask_price - bid_price)
            
        except (ValueError, TypeError) as e:
            LOG.debug(f"[OFA] Tick processing error: {e}")
        except Exception as e:
            LOG.error(f"[OFA] Unexpected tick error: {type(e).__name__}: {e}")
    
    def get_order_flow_imbalance(self) -> float:
        """Calculate buy/sell volume imbalance"""
        try:
            if not self.order_flow_history:
                return 0.0
            
            buy_vol = sum(t['volume'] for t in self.order_flow_history if t['side'] == 'BUY')
            sell_vol = sum(t['volume'] for t in self.order_flow_history if t['side'] == 'SELL')
            total_vol = buy_vol + sell_vol
            
            if total_vol > 0:
                imbalance = (buy_vol - sell_vol) / total_vol
                return float(np.clip(imbalance, -1.0, 1.0))
            return 0.0
            
        except (ValueError, TypeError, ZeroDivisionError) as e:
            LOG.debug(f"[OFA] Imbalance calc error: {e}")
            return 0.0
    
    def get_vpin(self) -> float:
        """Calculate Volume-Synchronized Probability of Informed Trading (0-1 scale)
        
        High VPIN indicates likely informed trading (front-running, insider knowledge)
        """
        try:
            if len(self.order_flow_history) < 50:
                return 0.5
            
            # VPIN = E[|Order Flow Imbalance|] / E[Volume]
            deltas = [abs(t['delta']) for t in self.order_flow_history]
            volumes = [t['volume'] for t in self.order_flow_history]
            
            if not deltas or not volumes:
                return 0.5
            
            avg_abs_delta = np.mean(deltas)
            avg_volume = np.mean(volumes)
            
            vpin = avg_abs_delta / (avg_volume + 1e-8)
            # Normalize: typical VPIN 0.5-1.5, so divide by 2 and clip
            return float(np.clip(vpin / 2.0, 0.0, 1.0))
            
        except (ValueError, TypeError, ZeroDivisionError) as e:
            LOG.debug(f"[OFA] VPIN calculation error: {e}")
            return 0.5
        except Exception as e:
            LOG.error(f"[OFA] Unexpected VPIN error: {type(e).__name__}: {e}")
            return 0.5
    
    def detect_spoofing(self) -> Dict:
        """Detect potential spoofing: placing large orders then canceling before execution
        
        Indicators:
        - Large orders that disappear quickly
        - Orders placed at extremes then canceled
        - Bid/ask clustering patterns
        """
        try:
            if len(self.order_flow_history) < 20:
                return {'spoofing_score': 0.0, 'confidence': 0.0}
            
            # Check for sudden volume spikes followed by reversals
            volumes = [t['volume'] for t in self.order_flow_history[-20:]]
            
            if len(volumes) > 1:
                avg_vol = np.mean(volumes[:-1])
                spike_vol = volumes[-1]
                spike_ratio = spike_vol / (avg_vol + 1e-8)
                
                # Spike > 5x average suggests potential spoof
                spoofing_score = float(np.clip((spike_ratio - 1) / 4.0, 0.0, 1.0))
                
                return {
                    'spoofing_score': spoofing_score,
                    'confidence': 0.6 if spoofing_score > 0.5 else 0.3,
                    'spike_ratio': spike_ratio
                }
            return {'spoofing_score': 0.0, 'confidence': 0.0}
            
        except (ValueError, TypeError) as e:
            LOG.debug(f"[OFA] Spoofing detection error: {e}")
            return {'spoofing_score': 0.0, 'confidence': 0.0}
    
    def detect_layering(self) -> Dict:
        """Detect potential layering: multiple orders at same price to create false demand
        
        Indicators:
        - Multiple orders at same price level
        - Orders appear then cancel in sequence
        - Clustered price levels with high volume
        """
        try:
            if len(self.order_flow_history) < 10:
                return {'layering_score': 0.0, 'levels': 0}
            
            # Count price level clustering
            prices = [t['price'] for t in self.order_flow_history[-20:]]
            price_counts = {}
            
            for price in prices:
                # Group prices into buckets (0.01 wide)
                level = round(price, 2)
                price_counts[level] = price_counts.get(level, 0) + 1
            
            # Layering = high concentration at few levels
            if price_counts:
                max_count = max(price_counts.values())
                layering_ratio = max_count / len(prices)
                layering_score = float(np.clip((layering_ratio - 0.3) / 0.5, 0.0, 1.0))
                
                return {
                    'layering_score': layering_score,
                    'levels': len(price_counts),
                    'max_concentration': layering_ratio
                }
            return {'layering_score': 0.0, 'levels': 0}
            
        except (ValueError, TypeError) as e:
            LOG.debug(f"[OFA] Layering detection error: {e}")
            return {'layering_score': 0.0, 'levels': 0}
    
    def detect_pump_and_dump(self) -> Dict:
        """Detect pump and dump pattern: rapid price rise followed by crash
        
        Indicators:
        - Volume spike with positive direction
        - Price acceleration
        - Early reversal signs
        """
        try:
            if len(self.order_flow_history) < 30:
                return {'pump_dump_score': 0.0}
            
            recent = list(self.order_flow_history[-30:])
            buy_pressure = sum(1 for t in recent if t['side'] == 'BUY') / len(recent)
            
            # Recent momentum
            first_half = list(self.order_flow_history)[-15:]
            second_half = list(self.order_flow_history)[-15:]
            
            if first_half and second_half:
                first_vol = np.mean([t['volume'] for t in first_half])
                second_vol = np.mean([t['volume'] for t in second_half])
                vol_accel = second_vol / (first_vol + 1e-8)
                
                # High buy pressure + volume acceleration = potential pump
                pump_dump_score = (buy_pressure - 0.5) * 2 * np.clip(vol_accel - 1.0, 0.0, 1.0)
                
                return {
                    'pump_dump_score': float(np.clip(pump_dump_score, 0.0, 1.0)),
                    'buy_pressure': float(buy_pressure),
                    'volume_acceleration': float(vol_accel)
                }
            return {'pump_dump_score': 0.0}
            
        except (ValueError, TypeError, ZeroDivisionError) as e:
            LOG.debug(f"[OFA] Pump/dump detection error: {e}")
            return {'pump_dump_score': 0.0}
    
    def get_microstructure_metrics(self) -> Dict:
        """Get comprehensive market microstructure metrics"""
        try:
            imbalance = self.get_order_flow_imbalance()
            vpin = self.get_vpin()
            spoofing = self.detect_spoofing()
            layering = self.detect_layering()
            pump_dump = self.detect_pump_and_dump()
            
            # Average spread
            avg_spread = float(np.mean(self.bid_ask_spreads)) if self.bid_ask_spreads else 0.0
            
            return {
                'order_flow_imbalance': imbalance,
                'vpin': vpin,
                'spoofing_score': spoofing['spoofing_score'],
                'layering_score': layering['layering_score'],
                'pump_dump_score': pump_dump['pump_dump_score'],
                'avg_spread': avg_spread,
                'tick_count': len(self.order_flow_history)
            }
        except Exception as e:
            LOG.error(f"[OFA] Metrics collection error: {type(e).__name__}: {e}")
            return {
                'order_flow_imbalance': 0.0,
                'vpin': 0.5,
                'spoofing_score': 0.0,
                'layering_score': 0.0,
                'pump_dump_score': 0.0,
                'avg_spread': 0.0,
                'tick_count': 0
            }
    
    def generate_microstructure_signal(self) -> Dict:
        """Generate trading signal based on microstructure analysis
        
        Returns:
        - signal: BUY | SELL | NEUTRAL
        - confidence: 0-1 scale
        - reason: string explaining signal
        """
        try:
            metrics = self.get_microstructure_metrics()
            
            imbalance = metrics['order_flow_imbalance']
            vpin = metrics['vpin']
            spoofing = metrics['spoofing_score']
            
            # High VPIN + positive imbalance = likely informed buying
            if vpin > 0.65 and imbalance > 0.3:
                signal = 'BUY'
                confidence = (vpin + abs(imbalance)) / 2
                reason = f"Informed buying detected (VPIN={vpin:.2f}, imbalance={imbalance:.2f})"
            
            # High VPIN + negative imbalance = likely informed selling
            elif vpin > 0.65 and imbalance < -0.3:
                signal = 'SELL'
                confidence = (vpin + abs(imbalance)) / 2
                reason = f"Informed selling detected (VPIN={vpin:.2f}, imbalance={imbalance:.2f})"
            
            # Spoofing detected - signal unreliable, SKIP
            elif spoofing > 0.7:
                signal = 'NEUTRAL'
                confidence = 0.2
                reason = f"Spoofing detected (score={spoofing:.2f}), skipping signal"
            
            # Strong buy pressure but no informed activity
            elif imbalance > 0.5 and vpin < 0.4:
                signal = 'BUY'
                confidence = 0.4
                reason = f"Retail buying pressure (imbalance={imbalance:.2f})"
            
            # Strong sell pressure but no informed activity
            elif imbalance < -0.5 and vpin < 0.4:
                signal = 'SELL'
                confidence = 0.4
                reason = f"Retail selling pressure (imbalance={imbalance:.2f})"
            
            else:
                signal = 'NEUTRAL'
                confidence = 0.3
                reason = "No clear microstructure signal"
            
            return {
                'signal': signal,
                'confidence': min(1.0, float(confidence)),
                'reason': reason,
                'metrics': metrics
            }
            
        except Exception as e:
            LOG.error(f"[OFA] Signal generation error: {type(e).__name__}: {e}")
            return {
                'signal': 'NEUTRAL',
                'confidence': 0.0,
                'reason': f"Error in microstructure analysis: {e}",
                'metrics': {}
            }

class MicrostructureAlpha:
    def __init__(self, symbol: str):
        self.symbol = symbol
        self.flow_analyzer = OrderFlowAnalyzer(symbol)
        self.alpha_history: List = []
    def update_with_tick(self, price: float, volume: float, ask: float, bid: float):
        self.flow_analyzer.process_tick(price, volume, ask, bid)
    def generate_alpha_signal(self, current_price: float, recent_prices: List = None) -> Tuple[int, float]:
        metrics = self.flow_analyzer.get_microstructure_metrics()
        alpha = metrics['order_flow_imbalance']
        signal = 1 if alpha > 0.3 else (-1 if alpha < -0.3 else 0)
        confidence = min(1.0, abs(alpha))
        return signal, confidence

# PHASE 3.1: PORTFOLIO OPTIMIZER
class CorrelationMatrix:
    def __init__(self, assets: List, lookback_days: int = 252):
        self.assets, self.lookback_days = assets, lookback_days
        self.correlation_matrix, self.covariance_matrix = np.identity(len(assets)), np.identity(len(assets))
    def update_from_prices(self, price_data):
        try:
            if hasattr(price_data, 'pct_change'): returns = price_data.pct_change().dropna()
            else: returns = price_data
            if hasattr(returns, 'values'): ret_vals = returns.values
            else: ret_vals = returns
            self.covariance_matrix = np.cov(ret_vals.T) if ret_vals.ndim > 1 else np.var(ret_vals)
            if self.covariance_matrix.ndim > 1:
                std_devs = np.diag(self.covariance_matrix) ** 0.5
                self.correlation_matrix = self.covariance_matrix / np.outer(std_devs, std_devs)
        except (ValueError, TypeError, AttributeError) as e:
            LOG.warning(f"Correlation matrix update failed: {e}")
        except Exception as e:
            LOG.error(f"Unexpected correlation error: {type(e).__name__}: {e}")
    def get_correlation(self, asset1: str, asset2: str) -> float:
        if asset1 not in self.assets or asset2 not in self.assets: return 0.0
        idx1, idx2 = self.assets.index(asset1), self.assets.index(asset2)
        return self.correlation_matrix[idx1, idx2] if self.correlation_matrix.ndim > 1 else 0.0

class RiskParityEngine:
    def __init__(self, correlation_matrix):
        self.correlation_matrix, self.weights = correlation_matrix, {}
    def calculate_risk_parity_weights(self, clusters=None) -> Dict:
        try:
            assets, weights = self.correlation_matrix.assets, np.ones(len(self.correlation_matrix.assets)) / len(self.correlation_matrix.assets)
            self.weights = {asset: weight for asset, weight in zip(assets, weights)}
            return self.weights
        except (ValueError, ZeroDivisionError, AttributeError) as e:
            LOG.warning(f"Risk parity calculation failed, using equal weights: {e}")
            return {asset: 1.0 / len(self.correlation_matrix.assets) for asset in self.correlation_matrix.assets}
        except Exception as e:
            LOG.error(f"Unexpected risk parity error: {type(e).__name__}: {e}")
            return {asset: 1.0 / len(self.correlation_matrix.assets) for asset in self.correlation_matrix.assets}

# PHASE 3.2: STRESS TESTING
class MonteCarloSimulator:
    def __init__(self, returns, correlation_matrix, num_simulations: int = 10000):
        self.returns, self.correlation_matrix, self.num_simulations = returns, correlation_matrix, num_simulations
    def run_simulation(self, time_steps: int = 252, weights: Dict = None) -> Dict:
        try:
            paths = np.zeros((self.num_simulations, time_steps + 1))
            paths[:, 0] = 100
            for step in range(1, time_steps + 1):
                Z = np.random.standard_normal(self.num_simulations)
                daily_returns = 0.001 + 0.01 * Z
                paths[:, step] = paths[:, step - 1] * (1 + daily_returns)
            final_returns = (paths[:, -1] - 100) / 100
            return {'mean_return': np.mean(final_returns), 'var_95': np.percentile(final_returns, 5), 'std_return': np.std(final_returns)}
        except (ValueError, TypeError) as e:
            LOG.warning(f"Monte Carlo simulation failed: {e}")
            return {'mean_return': 0, 'var_95': 0, 'std_return': 0}
        except Exception as e:
            LOG.error(f"Unexpected Monte Carlo error: {type(e).__name__}: {e}")
            return {'mean_return': 0, 'var_95': 0, 'std_return': 0}

