class NeuralMarketMaker:
    def __init__(self, symbol: str):
        self.symbol = symbol
        self.pnl = 0.0
        self.trades_executed = 0
        self.bid_ask_history = deque(maxlen=100)
        self.spread_history = deque(maxlen=100)
        self.inventory = 0.0
        
    def update_market(self, market_price: float, volatility: float, market_depth: float) -> Dict:
        """Calculate optimal bid/ask quotes based on volatility and inventory"""
        try:
            # Spread based on volatility and market depth
            base_spread = max(0.01, volatility * 0.5)  # Spread increases with volatility
            inventory_adjustment = self.inventory * 0.001  # Adjust for current inventory
            
            bid = market_price - (base_spread / 2) - inventory_adjustment
            ask = market_price + (base_spread / 2) + inventory_adjustment
            
            # Size allocation based on depth and inventory
            max_size = 100 + (market_depth * 50)
            bid_size = max_size * 0.6 if self.inventory < 0 else max_size * 0.4
            ask_size = max_size * 0.6 if self.inventory > 0 else max_size * 0.4
            
            quote = {
                'bid': float(bid),
                'ask': float(ask),
                'bid_size': float(bid_size),
                'ask_size': float(ask_size),
                'spread': float(ask - bid)
            }
            
            self.bid_ask_history.append(quote)
            self.spread_history.append(quote['spread'])
            return quote
        except (KeyError, TypeError, ValueError) as e:
            LOG.warning(f"Quote generation failed, using fallback: {e}")
            return {'bid': market_price - 0.01, 'ask': market_price + 0.01, 'bid_size': 100, 'ask_size': 100, 'spread': 0.02}
        except Exception as e:
            LOG.error(f"Unexpected quote error: {type(e).__name__}: {e}")
            return {'bid': market_price - 0.01, 'ask': market_price + 0.01, 'bid_size': 100, 'ask_size': 100, 'spread': 0.02}
    
    def execute_trade(self, side: str, price: float, size: float) -> Dict:
        """Execute trade and update inventory"""
        try:
            self.trades_executed += 1
            
            # Update inventory
            if side == 'BUY':
                self.inventory += size
                # PnL: we bought, hoping to sell higher
                profit = -0.002 * size * price  # Negative PnL on entry (we pay more)
            else:  # SELL
                self.inventory -= size
                # PnL: we sold, hoping to buy back lower
                profit = 0.002 * size * price  # Positive expected PnL on entry
            
            self.pnl += profit
            
            return {
                'side': side,
                'size': float(size),
                'price': float(price),
                'profit': float(profit),
                'inventory': float(self.inventory)
            }
        except Exception as e:
            LOG.error(f"Trade execution error: {e}")
            return {'side': side, 'size': size, 'price': price, 'profit': 0.0}
    
    def get_performance_metrics(self) -> Dict:
        """Get market maker performance metrics"""
        try:
            if self.spread_history:
                avg_spread = np.mean(list(self.spread_history))
                min_spread = np.min(list(self.spread_history))
                max_spread = np.max(list(self.spread_history))
            else:
                avg_spread = min_spread = max_spread = 1.0
            
            return {
                'avg_spread_pips': float(avg_spread) * 100,
                'min_spread_pips': float(min_spread) * 100,
                'max_spread_pips': float(max_spread) * 100,
                'trades_executed': self.trades_executed,
                'pnl': float(self.pnl),
                'inventory': float(self.inventory),
                'efficiency': float(self.pnl / max(1, self.trades_executed)) if self.trades_executed > 0 else 0.0
            }
        except (ValueError, ZeroDivisionError, AttributeError) as e:
            LOG.warning(f"Market making metrics calculation failed: {e}")
            return {'avg_spread_pips': 1.0, 'trades_executed': self.trades_executed, 'pnl': self.pnl}
        except Exception as e:
            LOG.error(f"Unexpected metrics error: {type(e).__name__}: {e}")
            return {'avg_spread_pips': 1.0, 'trades_executed': self.trades_executed, 'pnl': self.pnl}

# PHASE 2.2 COMPLETE: TRADE RECONSTRUCTION ENGINE
class TradeReconstructionEngine:
    def __init__(self, symbol: str):
        self.symbol = symbol
        self.tick_buffer: List = []
        self.reconstructed_trades: List = []
    def add_tick(self, price: float, volume: float, timestamp, bid: float = None, ask: float = None):
        self.tick_buffer.append({'price': price, 'volume': volume, 'timestamp': timestamp, 'bid': bid or (price - 0.05), 'ask': ask or (price + 0.05)})
        if len(self.tick_buffer) > 1000: self.tick_buffer.pop(0)
    def reconstruct_trades(self) -> List:
        if len(self.tick_buffer) < 2: return []
        self.reconstructed_trades = []
        for i in range(len(self.tick_buffer) - 1):
            current = self.tick_buffer[i]
            next_tick = self.tick_buffer[i + 1]
            if next_tick['price'] > current['price']: side = 'BUY'
            elif next_tick['price'] < current['price']: side = 'SELL'
            else: side = 'MID'
            estimated_size = current['volume']
            self.reconstructed_trades.append({'timestamp': current['timestamp'], 'price': current['price'], 'volume': estimated_size, 'side': side, 'bid': current['bid'], 'ask': current['ask']})
        return self.reconstructed_trades
    def get_trade_intensity(self, window_size: int = 60) -> float:
        if len(self.tick_buffer) == 0: return 0.0
        recent_ticks = [t for t in self.tick_buffer if (datetime.now() - t['timestamp']).total_seconds() < window_size]
        return len(recent_ticks) / max(1.0, window_size / 60.0)
    def get_trade_pattern(self, lookback: int = 20) -> str:
        if len(self.reconstructed_trades) < lookback: return 'BALANCED'
        recent = self.reconstructed_trades[-lookback:]
        buy_trades = sum(1 for t in recent if t['side'] == 'BUY')
        sell_trades = sum(1 for t in recent if t['side'] == 'SELL')
        if buy_trades > sell_trades * 1.5: return 'AGGRESSIVE_BUY'
        elif sell_trades > buy_trades * 1.5: return 'AGGRESSIVE_SELL'
        else: return 'BALANCED'

# PHASE 2.3 COMPLETE: MULTI-BROKER EXECUTION
class LiquidityAggregator:
    def __init__(self, symbol: str):
        self.symbol = symbol
        self.venues = {'PRIMARY': {'liquidity': 100}, 'SECONDARY': {'liquidity': 50}, 'DARK': {'liquidity': 30}}
    def get_aggregated_liquidity(self, current_price: float) -> Dict:
        total_bid_size = sum(v['liquidity'] for v in self.venues.values())
        total_ask_size = total_bid_size
        weighted_bid = current_price - 0.01
        weighted_ask = current_price + 0.01
        return {'total_bid_size': total_bid_size, 'total_ask_size': total_ask_size, 'weighted_bid': weighted_bid, 'weighted_ask': weighted_ask, 'venue_count': len(self.venues), 'is_fresh': True}
    def get_best_bid_ask(self, current_price: float) -> Tuple[float, float]:
        best_bid = current_price - 0.01
        best_ask = current_price + 0.01
        return best_bid, best_ask

class CrossVenueRouter:
    def __init__(self, symbol: str):
        self.symbol = symbol
        self.liquidity_agg = LiquidityAggregator(symbol)
        self.routing_history: List = []
    def route_order(self, side: str, size: float, current_price: float, urgency: float = 0.5) -> Dict:
        liquidity = self.liquidity_agg.get_aggregated_liquidity(current_price)
        routing_plan = {'timestamp': datetime.now(), 'side': side, 'total_size': size, 'urgency': urgency, 'allocations': [], 'expected_price': current_price, 'expected_slippage': 0.0}
        if not liquidity['is_fresh']:
            routing_plan['allocations'].append({'venue': 'PRIMARY', 'size': size, 'allocation_pct': 100.0})
            return routing_plan
        remaining_size = size
        for venue_name in ['SECONDARY', 'PRIMARY', 'DARK']:
            if remaining_size <= 0: break
            available = liquidity['total_ask_size'] if side == 'BUY' else liquidity['total_bid_size']
            allocation = min(remaining_size, available * 0.8)
            if allocation > 0:
                routing_plan['allocations'].append({'venue': venue_name, 'size': allocation, 'allocation_pct': (allocation / size) * 100})
                remaining_size -= allocation
        best_bid, best_ask = self.liquidity_agg.get_best_bid_ask(current_price)
        if side == 'BUY': routing_plan['expected_price'], routing_plan['expected_slippage'] = best_ask, (best_ask - current_price) * 100
        else: routing_plan['expected_price'], routing_plan['expected_slippage'] = best_bid, (current_price - best_bid) * 100
        self.routing_history.append(routing_plan)
        return routing_plan
    def execute_routed_order(self, routing_plan: Dict) -> Dict:
        results = {'timestamp': datetime.now(), 'routing_plan': routing_plan, 'executions': [], 'total_filled': 0.0, 'avg_fill_price': 0.0, 'total_slippage': 0.0}
        total_cost = 0.0
        for allocation in routing_plan['allocations']:
            venue_name, size = allocation['venue'], allocation['size']
            success, fill_price, filled_size = True, routing_plan['expected_price'], size
            if success and filled_size > 0:
                results['executions'].append({'venue': venue_name, 'filled': filled_size, 'price': fill_price})
                results['total_filled'] += filled_size
                total_cost += filled_size * fill_price
        if results['total_filled'] > 0:
            results['avg_fill_price'] = total_cost / results['total_filled']
            results['total_slippage'] = abs(results['avg_fill_price'] - routing_plan['expected_price']) * 100
        return results

# PHASE 3.1 COMPLETE: PORTFOLIO OPTIMIZER

class AdaptiveStrategyOptimizer:
    """Adaptive strategy optimization with dynamic parameter tuning and fitness evaluation"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.optimization_history = deque(maxlen=500)
        self.current_regime = 'trending'
        self.iteration = 0
        self.lock = threading.Lock()
        self.best_params = {}
    
    def evaluate_parameters(self, params: Dict, backtest_result: Dict) -> float:
        """Evaluate strategy parameters and return score"""
        try:
            score = 0.0
            if backtest_result.get('total_return', 0) > 0:
                score += min(100, (backtest_result['total_return'] / 0.25) * 100)
            if backtest_result.get('win_rate', 0) > 0.5:
                score += min(100, (backtest_result['win_rate'] / 0.6) * 100) * 0.8
            if backtest_result.get('sharpe', 0) > 0:
                score += min(100, (backtest_result['sharpe'] / 1.0) * 100) * 0.6
            return max(0.0, min(100.0, score / 3.0))
        except Exception as e:
            LOG.warning(f"[ADAPTIVE] Parameter eval failed: {e}")
            return 50.0
    
    def get_next_parameters(self) -> Dict:
        """Get next parameters to test"""
        try:
            with self.lock:
                if len(self.optimization_history) == 0:
                    return {'rsi_threshold': 30, 'ma_period': 20, 'volatility_adj': 1.0}
                
                best = max(self.optimization_history, key=lambda x: x['score'])
                params = best.get('params', {}).copy()
                
                # Mutate parameters slightly
                if 'rsi_threshold' in params:
                    params['rsi_threshold'] += np.random.uniform(-5, 5)
                    params['rsi_threshold'] = max(20, min(50, params['rsi_threshold']))
                
                if 'ma_period' in params:
                    params['ma_period'] = int(params.get('ma_period', 20) + np.random.uniform(-3, 3))
                    params['ma_period'] = max(10, min(50, params['ma_period']))
                
                return params
        except Exception as e:
            LOG.warning(f"[ADAPTIVE] Get next params failed: {e}")
            return {'rsi_threshold': 30, 'ma_period': 20, 'volatility_adj': 1.0}
    
    def apply_best_parameters(self) -> bool:
        """Apply best parameters found"""
        try:
            with self.lock:
                if self.optimization_history:
                    best = max(self.optimization_history, key=lambda x: x['score'])
                    self.best_params = best.get('params', {})
                    LOG.info(f"[ADAPTIVE] Applied best params: {self.best_params}")
                    return True
            return False
        except Exception as e:
            LOG.warning(f"[ADAPTIVE] Apply best params failed: {e}")
            return False
    
    def get_optimization_status(self) -> Dict:
        if self.optimization_history:
            best = max(self.optimization_history, key=lambda x: x['score'])
            return {'iteration': self.iteration, 'best_score': best['score'], 'best_params': best['params'], 'current_regime': self.current_regime}
        return {'iteration': 0, 'best_score': 0, 'best_params': {}, 'current_regime': self.current_regime}
    
    def evaluate_fitness(self, backtest_result: Dict, performance_metrics: Dict = None) -> float:
        """Evaluate fitness score of strategy (0-100 scale). Weighted: Sharpe 40%, Win Rate 25%, Return 20%, Drawdown 15%."""
        try:
            metrics = performance_metrics or backtest_result.get('metrics', {})
            sharpe = float(metrics.get('sharpe', 0.5))
            win_rate = float(metrics.get('win_rate', 0.4))
            total_return = float(metrics.get('total_return', 0.0))
            max_dd = abs(float(metrics.get('max_drawdown', -0.2)))
            
            fitness = 0.0
            
            sharpe_score = min(100, (sharpe / 1.0) * 100) * 0.40
            fitness += sharpe_score
            
            win_score = min(100, (win_rate / 0.6) * 100) * 0.25
            fitness += win_score
            
            return_score = min(100, (max(0, total_return) / 0.25) * 100) * 0.20
            fitness += return_score
            
            dd_score = max(0, 100 * (1.0 - max_dd / 0.5)) * 0.15
            fitness += dd_score
            
            fitness = max(0.0, min(100.0, fitness))
            LOG.info(f"[FITNESS] Score={fitness:.1f} (sharpe={sharpe:.2f}, wr={win_rate:.1%}, dd={max_dd:.1%})")
            return fitness
        except Exception as e:
            LOG.warning(f"[FITNESS] Calculation failed: {e}")
            return 50.0

class PortfolioOptimizer:
    def __init__(self, assets: List):
        self.assets = assets
        self.correlation_matrix = CorrelationMatrix(assets)
        self.risk_parity = RiskParityEngine(self.correlation_matrix)
        self.optimal_weights: Dict = {}
    def optimize_portfolio(self, price_data, num_clusters: int = 5, strategy: str = 'risk_parity') -> Dict:
        self.correlation_matrix.update_from_prices(price_data)
        if strategy == 'risk_parity': weights = self.risk_parity.calculate_risk_parity_weights()
        else: weights = {asset: 1.0 / len(self.assets) for asset in self.assets}
        self.optimal_weights = weights
        return weights
    
    def optimize_positions(self, account_balance: float, open_positions: List[Dict], risk_per_trade: float = 0.02, max_positions: int = 3) -> Dict:
        """Optimize position sizing based on portfolio correlation and risk. Returns recommended size with correlation adjustment."""
        try:
            if not open_positions:
                base_size = (account_balance * risk_per_trade) / 50
                return {'new_size': max(0.01, base_size), 'correlation_adjustment': 1.0, 'diversification_benefit': 0.0, 'recommendation': 'INCREASE', 'success': True}
            
            correlation_sum = 0.0
            position_count = len(open_positions)
            for i, pos1 in enumerate(open_positions):
                for pos2 in open_positions[i+1:]:
                    direction_match = 1.0 if pos1.get('dir') == pos2.get('dir') else -1.0
                    correlation_sum += direction_match * 0.7
            
            pair_count = max(1, (position_count * (position_count - 1)) / 2)
            avg_correlation = correlation_sum / pair_count if pair_count > 0 else 0.0
            diversification_benefit = max(0.0, 1.0 - abs(avg_correlation))
            correlation_adjustment = 1.0 - (abs(avg_correlation) * 0.3)
            correlation_adjustment = max(0.5, min(1.0, correlation_adjustment))
            
            position_penalty = max(0.6, 1.0 - (position_count / max_positions) * 0.4)
            base_size = (account_balance * risk_per_trade) / 50
            new_size = base_size * correlation_adjustment * position_penalty
            new_size = max(0.01, min(new_size, account_balance * 0.1))
            
            if position_count >= max_positions:
                recommendation = 'REDUCE'
            elif avg_correlation > 0.5:
                recommendation = 'REDUCE'
            elif position_count <= 1:
                recommendation = 'INCREASE'
            else:
                recommendation = 'HOLD'
            
            LOG.info(f"[PORTFOLIO] Size: {new_size:.4f}, corr_adj={correlation_adjustment:.2f}, rec={recommendation}")
            return {'new_size': new_size, 'correlation_adjustment': correlation_adjustment, 'diversification_benefit': diversification_benefit, 'recommendation': recommendation, 'position_count': position_count, 'avg_correlation': avg_correlation, 'success': True}
        except Exception as e:
            LOG.warning(f"[PORTFOLIO] Optimization failed: {e}")
            return {'new_size': (account_balance * risk_per_trade) / 50, 'correlation_adjustment': 1.0, 'diversification_benefit': 0.0, 'recommendation': 'HOLD', 'success': False}
    
    def calculate_portfolio_metrics(self, weights: Dict = None, returns=None) -> Dict:
        if weights is None: weights = self.optimal_weights
        try:
            asset_rets = [0.001 for _ in self.assets]
            portfolio_return = sum(weights.get(asset, 0) * ret for asset, ret in zip(self.assets, asset_rets))
            weight_array = np.array([weights.get(asset, 0) for asset in self.assets])
            cov_matrix = self.correlation_matrix.covariance_matrix
            if cov_matrix.ndim > 1: portfolio_vol = np.sqrt(max(0, weight_array @ cov_matrix @ weight_array * 252))
            else: portfolio_vol = 0.02
            sharpe = (portfolio_return - 0.04) / (portfolio_vol + 1e-6)
            individual_vols = np.array([self.correlation_matrix.get_volatility(a) for a in self.assets])
            diversification = (weight_array @ individual_vols) / (portfolio_vol + 1e-6)
            herfindahl = np.sum(weight_array ** 2)
            return {'total_return': portfolio_return, 'volatility': portfolio_vol, 'sharpe_ratio': sharpe, 'max_drawdown': -0.20, 'diversification_ratio': diversification, 'herfindahl_index': herfindahl, 'concentration': 1.0 - herfindahl}
        except (ValueError, TypeError, AttributeError) as e:
            LOG.warning(f"Portfolio metrics calculation failed: {e}")
            return {'total_return': 0, 'volatility': 0, 'sharpe_ratio': 0, 'max_drawdown': 0, 'diversification_ratio': 0, 'herfindahl_index': 0, 'concentration': 0}
        except Exception as e:
            LOG.error(f"Unexpected portfolio metrics error: {type(e).__name__}: {e}")
            return {'total_return': 0, 'volatility': 0, 'sharpe_ratio': 0, 'max_drawdown': 0, 'diversification_ratio': 0, 'herfindahl_index': 0, 'concentration': 0}
    def rebalance_schedule(self, current_weights: Dict, target_weights: Dict, threshold: float = 0.05) -> Dict:
        trades = {}
        max_drift = 0.0
        for asset in self.assets:
            current, target = current_weights.get(asset, 0), target_weights.get(asset, 0)
            drift = abs(current - target)
            max_drift = max(max_drift, drift)
            if drift > threshold / len(self.assets): trades[asset] = target - current
        if max_drift > threshold: return trades
        return {}

# PHASE 3.3 COMPLETE: ADAPTIVE PARAMETER SYSTEM
class AdaptiveParameterSystem:
    def __init__(self, initial_params: Dict):
        self.initial_params = initial_params.copy()
        self.current_params = initial_params.copy()
        self.optimization_history: List = []
        self.current_regime = "NORMAL"
        self.iteration = 0
    def evaluate_parameters(self, params: Dict, performance_metrics: Dict, regime: str = "NORMAL") -> float:
        weights = {'sharpe': 0.40, 'win_rate': 0.20, 'max_dd': 0.25, 'total_return': 0.15}
        score = 0.0
        sharpe = performance_metrics.get('sharpe', 0.5)
        sharpe_score = min(100, (sharpe / 1.0) * 100) * weights['sharpe']
        score += sharpe_score
        win_rate = performance_metrics.get('win_rate', 0.5)
        win_score = min(100, (win_rate / 0.55) * 100) * weights['win_rate']
        score += win_score
        max_dd = abs(performance_metrics.get('max_dd', -0.20))
        dd_score = max(0, 100 * (1.0 - max_dd / 0.30)) * weights['max_dd']
        score += dd_score
        ret = performance_metrics.get('total_return', 0.05)
        ret_score = min(100, (ret / 0.20) * 100) * weights['total_return']
        score += ret_score
        self.optimization_history.append({'params': params.copy(), 'score': score, 'regime': regime, 'iteration': self.iteration})
        self.iteration += 1
        return score
    def get_next_parameters(self, regime: str = "NORMAL") -> Dict:
        self.current_regime = regime
        params = self.current_params.copy()
        for key in params:
            params[key] = params[key] * (0.95 + np.random.uniform(0, 0.1))
        return params
    def apply_best_parameters(self):
        if self.optimization_history:
            best = max(self.optimization_history, key=lambda x: x['score'])
            self.current_params = best['params'].copy()
    def get_optimization_status(self) -> Dict:
        if self.optimization_history:
            best = max(self.optimization_history, key=lambda x: x['score'])
            return {'iteration': self.iteration, 'best_score': best['score'], 'best_params': best['params'], 'current_regime': self.current_regime}
        return {'iteration': 0, 'best_score': 0, 'best_params': {}, 'current_regime': self.current_regime}
    
    def evaluate_fitness(self, backtest_result: Dict, performance_metrics: Dict = None) -> float:
        """Evaluate fitness score of strategy (0-100 scale). Weighted: Sharpe 40%, Win Rate 25%, Return 20%, Drawdown 15%."""
        try:
            metrics = performance_metrics or backtest_result.get('metrics', {})
            sharpe = float(metrics.get('sharpe', 0.5))
            win_rate = float(metrics.get('win_rate', 0.4))
            total_return = float(metrics.get('total_return', 0.0))
            max_dd = abs(float(metrics.get('max_drawdown', -0.2)))
            
            fitness = 0.0
            
            sharpe_score = min(100, (sharpe / 1.0) * 100) * 0.40
            fitness += sharpe_score
            
            win_score = min(100, (win_rate / 0.6) * 100) * 0.25
            fitness += win_score
            
            return_score = min(100, (max(0, total_return) / 0.25) * 100) * 0.20
            fitness += return_score
            
            dd_score = max(0, 100 * (1.0 - max_dd / 0.5)) * 0.15
            fitness += dd_score
            
            fitness = max(0.0, min(100.0, fitness))
            LOG.info(f"[FITNESS] Score={fitness:.1f} (sharpe={sharpe:.2f}, wr={win_rate:.1%}, dd={max_dd:.1%})")
            return fitness
        except Exception as e:
            LOG.warning(f"[FITNESS] Calculation failed: {e}")
            return 50.0

# PHASE 4.2 COMPLETE: STRATEGY DISCOVERY
class EvolutionaryStrategyFinder:
    def __init__(self):
        self.discovered_strategies: List = []
        self.strategy_counter = 0
    def define_search_space(self) -> List:
        return [('fast_ma', 10, 50), ('slow_ma', 30, 200), ('momentum_period', 14, 50), ('momentum_threshold', 50, 80), ('volatility_period', 20, 60), ('volatility_multiplier', 2.0, 5.0), ('risk_per_trade', 1.0, 5.0), ('stop_loss_factor', 1.5, 3.0), ('entry_confirmation', 1, 3), ('exit_urgency', 0.5, 1.0)]
    def discover_strategies(self, backtest_func=None, generations: int = 20) -> List:
        genes = self.define_search_space()
        for gen in range(generations):
            params = {name: np.random.uniform(lower, upper) for name, lower, upper in genes}
            fitness = backtest_func(params) if backtest_func else 0.5
            strategy = {'id': f"EVOSTRAT_{self.strategy_counter}", 'name': f"Evolved_Gen{gen}", 'parameters': params, 'fitness': fitness}
            self.discovered_strategies.append(strategy)
            self.strategy_counter += 1
        return self.discovered_strategies
    def get_top_strategies(self, n: int = 5) -> List:
        sorted_strats = sorted(self.discovered_strategies, key=lambda s: s.get('fitness', 0), reverse=True)
        return sorted_strats[:n]

