class CircuitBreaker:
    """Circuit breaker pattern for fault tolerance"""
    def __init__(self, fail_thresh=5, timeout_sec=60):
        self.fail_thresh = fail_thresh
        self.timeout_sec = timeout_sec
        self.fail_count = 0
        self.last_fail = None
        self.state = "closed"
    
    def reset(self):
        """Force reset the circuit breaker to closed state (for critical operations)"""
        self.fail_count = 0
        self.last_fail = None
        self.state = "closed"
        LOG.info("[CIRCUIT] Reset to closed state")
    
    def call(self, func, *args, **kwargs):
        if self.state == "open":
            if self.last_fail and (utc_now() - self.last_fail).total_seconds() >= self.timeout_sec:
                self.state = "half_open"
                LOG.info("[CIRCUIT] Transitioning to half-open state")
            else:
                raise Exception(f"Circuit OPEN (failed {self.fail_count} times)")
        
        try:
            result = func(*args, **kwargs)
            self.fail_count = 0
            self.state = "closed"
            return result
        except Exception as e:
            self.fail_count += 1
            self.last_fail = utc_now()
            if self.fail_count >= self.fail_thresh:
                self.state = "open"
                LOG.error(f"[CIRCUIT] Transitioned to OPEN state after {self.fail_count} failures")
            raise

class TTLCache:
    """Time-to-live cache with LRU eviction"""
    def __init__(self, maxsize=128, ttl_sec=60):
        self.maxsize = maxsize
        self.ttl_sec = ttl_sec
        self._cache = {}
        self._order = deque()
    
    def get(self, key):
        if key not in self._cache:
            return None
        ts, val = self._cache[key]
        if time.time() - ts > self.ttl_sec:
            del self._cache[key]
            self._order.remove(key)
            return None
        return val
    
    def set(self, key, val):
        if len(self._cache) >= self.maxsize and key not in self._cache:
            old = self._order.popleft()
            self._cache.pop(old, None)
        
        self._cache[key] = (time.time(), val)
        
        if key in self._order:
            self._order.remove(key)
        self._order.append(key)
    
    def clear(self):
        self._cache.clear()
        self._order.clear()
    
    def stats(self):
        """Return cache statistics"""
        return {
            'size': len(self._cache),
            'maxsize': self.maxsize,
            'ttl_sec': self.ttl_sec
        }

