class IndicatorCache:
    """Cache for indicator calculations with TTL per timeframe"""
    def __init__(self):
        # TTL per timeframe (minutes converted to seconds)
        self.ttl_config = {
            'M5': 10,    # 10 seconds for 5-minute bars
            'M15': 20,   # 20 seconds for 15-minute bars
            'H1': 60,    # 60 seconds for hourly bars
            'H4': 120,   # 120 seconds for 4-hour bars
            'D1': 300,   # 300 seconds for daily bars
        }
        self.cache = {}
        for tf in self.ttl_config:
            self.cache[tf] = TTLCache(maxsize=5, ttl_sec=self.ttl_config[tf])
    
    def get_cache_key(self, df, tf):
        """Create deterministic cache key based on dataframe content"""
        if df is None or len(df) == 0:
            return None
        # Hash the last 3 rows + timeframe = unique key
        key_data = f"{tf}_{len(df)}_{df.iloc[-1]['close']:.6f}_{df.iloc[-1]['high']:.6f}"
        return hashlib.md5(key_data.encode()).hexdigest()
    
    def get(self, df, tf='M5'):
        """Get cached indicators or None if not cached"""
        if df is None or len(df) < 20:
            return None
        key = self.get_cache_key(df, tf)
        if key is None:
            return None
        cache = self.cache.get(tf, self.cache['M5'])
        return cache.get(key)
    
    def set(self, df, indicators, tf='M5'):
        """Cache calculated indicators"""
        if df is None:
            return
        key = self.get_cache_key(df, tf)
        if key is None:
            return
        cache = self.cache.get(tf, self.cache['M5'])
        cache.set(key, indicators)
    
    def clear_all(self):
        """Clear all caches"""
        for cache in self.cache.values():
            cache.clear()
    
    def stats(self):
        """Return cache statistics by timeframe"""
        return {tf: cache.stats() for tf, cache in self.cache.items()}

class DataFrameCache:
    """Cache for fetched dataframes to avoid redundant API calls"""
    def __init__(self):
        self.df_cache = {}
        self.fetch_times = {}
        # STAGE-5: HTF cache leverage - fetch once, cache, invalidate only on
        # a new HTF bar. D1 was 60s (refetched every cycle!) and W1/MN1 were
        # missing (default 30s) - now daily/weekly/monthly data is fetched once
        # per bar boundary, not per cycle.
        self.fetch_interval = {
            'M5': 5,      # Min 5 seconds between fetches
            'M15': 15,
            'H1': 30,
            'H4': 60,
            'D1': 3600,   # 1h  - new daily bar ~ once per day
            'W1': 21600,  # 6h  - new weekly bar ~ once per week
            'MN1': 86400, # 24h - new monthly bar ~ once per month
        }
    
    def get(self, tf, symbol):
        """Get cached dataframe if fresh enough"""
        key = f"{symbol}_{tf}"
        if key not in self.df_cache:
            return None
        
        cached_df, fetch_time = self.df_cache[key]
        elapsed = time.time() - fetch_time
        min_interval = self.fetch_interval.get(tf, 30)
        
        if elapsed < min_interval:
            return cached_df.copy() if cached_df is not None else None
        return None
    
    def set(self, df, tf, symbol):
        """Cache fetched dataframe - CRITICAL: Never cache None or empty dataframes"""
        key = f"{symbol}_{tf}"
        # Only cache non-empty, non-None dataframes
        if df is not None and not (hasattr(df, 'empty') and df.empty):
            self.df_cache[key] = (df.copy(), time.time())
        # If df is None or empty, do NOT cache it
    
    def clear_old(self, max_age_sec=600):
        """Clear cached dataframes older than their per-timeframe interval.
        
        STAGE-5: was a flat 600s for everything, which wiped the D1/W1/MN1
        caches (now 1h/6h/24h intervals) after 10 minutes and forced HTF
        refetches. Now each entry is only cleared once it exceeds its own
        timeframe's fetch_interval (the caller's max_age_sec still applies as
        a floor for the low-timeframes that don't have an interval set).
        """
        current_time = time.time()
        to_delete = []
        for key, (df, fetch_time) in self.df_cache.items():
            try:
                tf = key.split('_')[-1]
            except Exception:
                tf = ''
            allowed = self.fetch_interval.get(tf, max_age_sec)
            if current_time - fetch_time > allowed:
                to_delete.append(key)
        for key in to_delete:
            del self.df_cache[key]
        return len(to_delete)
    
    def stats(self):
        """Return cache statistics"""
        return {
            'cached_frames': len(self.df_cache),
            'keys': list(self.df_cache.keys())
        }

class PerformanceMonitor:
    """Track performance metrics: calculation time, cache hits, memory usage"""
    def __init__(self, enable_logging=True):
        self.enable_logging = enable_logging
        self.reset()
    
    def reset(self):
        """Reset all counters"""
        self.cycle_count = 0
        self.indicator_calculations = 0
        self.indicator_cache_hits = 0
        self.indicator_cache_misses = 0
        self.dataframe_fetches = 0
        self.dataframe_cache_hits = 0
        self.dataframe_cache_misses = 0
        self.calculation_times = deque(maxlen=100)
        self.total_calc_time = 0.0
    
    def log_indicator_calc(self, tf, duration_ms):
        """Log indicator calculation"""
        self.indicator_calculations += 1
        self.calculation_times.append(duration_ms)
        self.total_calc_time += duration_ms
    
    def log_indicator_hit(self):
        """Log cache hit for indicators"""
        self.indicator_cache_hits += 1
    
    def log_indicator_miss(self):
        """Log cache miss for indicators"""
        self.indicator_cache_misses += 1
    
    def log_dataframe_hit(self):
        """Log cache hit for dataframe"""
        self.dataframe_cache_hits += 1
    
    def log_dataframe_miss(self):
        """Log cache miss for dataframe"""
        self.dataframe_cache_misses += 1
        self.dataframe_fetches += 1
    
    def get_stats(self):
        """Get current statistics"""
        total_ind = self.indicator_cache_hits + self.indicator_cache_misses
        ind_hit_rate = (self.indicator_cache_hits / total_ind * 100) if total_ind > 0 else 0
        
        total_df = self.dataframe_cache_hits + self.dataframe_cache_misses
        df_hit_rate = (self.dataframe_cache_hits / total_df * 100) if total_df > 0 else 0
        
        avg_calc_time = (sum(self.calculation_times) / len(self.calculation_times)) if self.calculation_times else 0
        
        return {
            'indicator_calcs': self.indicator_calculations,
            'indicator_hits': self.indicator_cache_hits,
            'indicator_misses': self.indicator_cache_misses,
            'indicator_hit_rate': ind_hit_rate,
            'dataframe_hits': self.dataframe_cache_hits,
            'dataframe_misses': self.dataframe_cache_misses,
            'dataframe_hit_rate': df_hit_rate,
            'dataframe_fetches': self.dataframe_fetches,
            'avg_calc_time_ms': avg_calc_time,
            'total_calc_time_ms': self.total_calc_time,
        }
    
    def report(self):
        """Print performance report"""
        stats = self.get_stats()
        if not self.enable_logging:
            return
        
        LOG.info(
            f"[PERF] Indicator: {stats['indicator_calcs']} calcs, "
            f"{stats['indicator_hit_rate']:.1f}% cache hit ({stats['indicator_hits']}/{stats['indicator_hits']+stats['indicator_misses']}), "
            f"{stats['avg_calc_time_ms']:.2f}ms avg | "
            f"DataFrame: {stats['dataframe_fetches']} fetches, "
            f"{stats['dataframe_hit_rate']:.1f}% cache hit ({stats['dataframe_hits']}/{stats['dataframe_hits']+stats['dataframe_misses']})"
        )

class Store:
    """Database storage - V12.1 UPDATED with complete signal tracking"""
    def __init__(self):
        os.makedirs("state", exist_ok=True)
