class StatePersistence:
    def __init__(self):
        os.makedirs("state", exist_ok=True)
        self.path = CFG["state_file"]
        self.last_save = 0.0
        
        if not os.path.exists(self.path):
            with open(self.path, 'w') as f:
                json.dump({
                    'ts': utc_now().isoformat(),
                    'first_run': True,
                    'version': '12.1',
                    'balance': CFG["account_balance"],
                    'paused_losses': False,
                    'loss_pause_until': None,
                    'consecutive_loss_count': 0,
                    'last_close_ts': None,
                    'last_pause_day': utc_now().date().isoformat()
                }, f, indent=2)
    
    def save(self, data):
        if time.time() - self.last_save < 30:
            return
        
        try:
            temp = self.path + ".tmp"
            with open(temp, 'w') as f:
                json.dump({**data, 'ts': utc_now().isoformat(), 'version': '12.1'}, f, indent=2)
            os.replace(temp, self.path)
            self.last_save = time.time()
        except Exception as e:
            LOG.error(f"[STATE] Save failed: {e}")
    
    def load(self):
        if os.path.exists(self.path):
            try:
                with open(self.path, 'r') as f:
                    data = json.load(f)
                    if isinstance(data, dict):
                        data.setdefault('paused_losses', False)
                        data.setdefault('loss_pause_until', None)
                        data.setdefault('consecutive_loss_count', 0)
                        data.setdefault('last_close_ts', None)
                        data.setdefault('last_pause_day', utc_now().date().isoformat())
                    return data
            except Exception as e:
                LOG.error(f"[STATE] Load failed: {e}")
        return None

STATE = StatePersistence()

class EmailNotifier:
    def __init__(self):
        self.enabled = bool(
            CFG["email_from"] and 
            CFG["email_to"] and 
            CFG["email_password"]
        )
    
    def send(self, subj, body, image_data=None):
        if not self.enabled:
            return
        
        try:
            if image_data:
                msg = MIMEMultipart()
                msg.attach(MIMEText(body))
                img = MIMEImage(image_data)
                img.add_header('Content-Disposition', 'attachment', filename='chart.png')
                msg.attach(img)
            else:
                msg = MIMEText(body)
            
            msg['Subject'] = subj
            msg['From'] = CFG["email_from"]
            msg['To'] = CFG["email_to"]
            
            smtp = smtplib.SMTP('smtp.gmail.com', 587)
            smtp.starttls()
            smtp.login(CFG["email_from"], CFG["email_password"])
            smtp.send_message(msg)
            smtp.quit()
        except Exception as e:
            LOG.error(f"[EMAIL] Failed: {e}")

EMAIL = EmailNotifier()

class TelegramNotifier:
    def __init__(self):
        self.enabled = False
        self.token = CFG["tg_token"]
        self.chat_id = CFG["tg_chat_id"]
        self.signal_chat_id = str(CFG.get("tg_signal_only_chat_id", "")).strip()
        self.base_url = f"https://api.telegram.org/bot{self.token}"
        self.circuit = CircuitBreaker(fail_thresh=3, timeout_sec=300)
        self.pending_swing_confirmations = {}  # v17.0: Store pending Golden Swing confirmations
        self._chart_gen = None  # v18.1: Lazy-load EducationalChartGenerator
        
        if not self.token or self.token == "YOUR_BOT_TOKEN_HERE":
            LOG.warning("[TG] Token not configured. Set CFG['tg_token'] from @BotFather")
            return
        
        if not self.chat_id or self.chat_id == "YOUR_CHAT_ID_HERE":
            LOG.warning("[TG] Chat ID not configured. Get it from /getUpdates API call")
            return
        
        if not REQUESTS_OK:
            LOG.warning("[TG] Requests library not available")
            return
        
        self.enabled = True
        
        # Test connection (don't block startup on failure)
        try:
            test_msg = f"🚀 Sentinel v12.1 Started\nMode: {CFG['mode']}\nTime: {utc_now().strftime('%Y-%m-%d %H:%M:%S')}"
            self._send_message_safe(test_msg)
            LOG.info("[TG] Connected via HTTP API")
        except Exception as e:
            LOG.warning(f"[TG] Connection test failed (continuing anyway): {str(e)[:100]}")
            # Keep enabled=True to attempt notifications during runtime
    
    def _send_message_safe(self, message, parse_mode='HTML', disable_notification=False):
        """Send message via Telegram Bot API HTTP request"""
        if not self.enabled:
            LOG.warning("[TG] Not enabled, message not sent")
            return False
        
        try:
            url = f"{self.base_url}/sendMessage"
            payload = {
                'chat_id': self.chat_id,
                'text': message,
                'parse_mode': parse_mode,
                'disable_notification': disable_notification
            }
            
            # Very short timeout (2 seconds) to avoid blocking bot startup
            response = requests.post(url, json=payload, timeout=2)
            if response.status_code == 200:
                return True
            else:
                LOG.debug(f"[TG] Send failed: {response.status_code}")
                return False
                
        except requests.exceptions.Timeout:
            LOG.debug("[TG] Timeout - continuing without notification")
            return False
        except requests.exceptions.ConnectionError:
            LOG.warning("[TG] Connection error")
            return False
        except Exception as e:
            LOG.error(f"[TG] Send failed: {e}")
            return False

    def _send_message_to_chat(self, chat_id, message, parse_mode='HTML', disable_notification=False):
        """Send a message to a specific Telegram chat ID."""
        if not self.enabled or not chat_id:
            return False

        try:
            url = f"{self.base_url}/sendMessage"
            payload = {
                'chat_id': chat_id,
                'text': message,
                'parse_mode': parse_mode,
                'disable_notification': disable_notification
            }
            response = requests.post(url, json=payload, timeout=2)
            return response.status_code == 200
        except Exception as e:
            LOG.debug(f"[TG] Signal-only send failed for {chat_id}: {e}")
            return False
    
    def _send_photo_safe(self, caption, image_bytes, disable_notification=False, chat_id=None):
        """Send photo via Telegram Bot API HTTP request"""
        if not self.enabled:
            return False
        
        try:
            url = f"{self.base_url}/sendPhoto"
            
            # Create multipart form data
            files = {
                'photo': ('chart.png', image_bytes, 'image/png')
            }
            data = {
                'chat_id': chat_id or self.chat_id,
                'caption': caption,
                'parse_mode': 'HTML'
            }
            
            response = requests.post(url, files=files, data=data, timeout=15)
            if response.status_code == 200:
                return True
            else:
                LOG.error(f"[TG] Photo send failed: {response.status_code}")
                return self._send_message_safe(caption)
                
        except Exception as e:
            LOG.error(f"[TG] Photo send failed: {e}")
            return self._send_message_safe(caption)
    
    def _send_media_group(self, caption, chart_bytes_list, disable_notification=False):
        """Send multiple charts as media group (Telegram Professional)
        
        Distributes charts into groups (4-5 images per group) to avoid congestion
        """
        if not self.enabled or not REQUESTS_OK:
            return False
        
        try:
            # Group charts (limit 10 per media group, send in groups of 4)
            group_size = 4
            groups = [chart_bytes_list[i:i + group_size] for i in range(0, len(chart_bytes_list), group_size)]
            
            url = f"{self.base_url}/sendMediaGroup"
            
            for idx, group in enumerate(groups):
                media_list = []
                
                for chart_idx, chart_bytes in enumerate(group):
                    # Determine caption placement (only for first image in first group)
                    is_first = (idx == 0 and chart_idx == 0)
                    chart_caption = caption if is_first else f"Chart {idx * group_size + chart_idx + 1}"
                    
                    media_item = {
                        "type": "photo",
                        "media": f"attach://photo{chart_idx}",
                        "caption": chart_caption if is_first else "",
                        "parse_mode": "HTML"
                    }
                    media_list.append(media_item)
                
                # Prepare files for this group
                files_dict = {}
                for chart_idx, chart_bytes in enumerate(group):
                    files_dict[f"photo{chart_idx}"] = ('chart.png', chart_bytes, 'image/png')
                
                # Send media group
                data = {
                    'chat_id': self.chat_id,
                    'media': json.dumps(media_list)
                }
                
                response = requests.post(url, files=files_dict, data=data, timeout=30)
                
                if response.status_code != 200:
                    LOG.warning(f"[TG] Media group {idx + 1} send failed: {response.status_code}")
                    # Fallback: send individual photos
                    for chart_idx, chart_bytes in enumerate(group):
                        self._send_photo_safe(
                            f"Chart {idx * group_size + chart_idx + 1}",
                            chart_bytes,
                            disable_notification=True
                        )
                else:
                    LOG.info(f"[TG] Media group {idx + 1}/{len(groups)} sent successfully ({len(group)} images)")
            
            return True
            
        except Exception as e:
            LOG.error(f"[TG] Media group send failed: {e}")
            # Fallback: send individual photos
            for chart_idx, chart_bytes in enumerate(chart_bytes_list[:4]):  # Limit to 4
                self._send_photo_safe(f"Chart {chart_idx + 1}", chart_bytes, disable_notification=True)
            return False
    
    def notify(self, msg, important=False):
        if not self.enabled:
            LOG.info(f"[TG-SIM] {msg}")
            return
        
        success = self._send_message_safe(msg, disable_notification=not important)
        if not success and important:
            time.sleep(1)
            self._send_message_safe(msg, disable_notification=False)
    
    def generate_dynamic_reasoning(self, signal_data: dict, macro_context: dict = None) -> str:
        """
        Generate natural language reasoning for why signal was generated
        
        v16.0 Examples:
        - "Entering at 61.8% Fib because DXY is Diverging and Candle Pressure is Stabilizing"
        - "Strong BUY: Price confirmed at key support with bullish momentum + positive ML ensemble"
        - "SELL triggered by break of 20-EMA with rising volatility and strong bearish pressure"
        """
        try:
            direction = signal_data.get('dir', 'UNKNOWN')
            score = signal_data.get('score', 0)
            features = signal_data.get('features', {})
            
            parts = []
            
            # Confidence assessment
            if score >= 12:
                parts.append(f"🎯 <b>STRONG {direction}</b>")
            elif score >= 10:
                parts.append(f"<b>Solid {direction}</b>")
            else:
                parts.append(f"{direction} Signal")
            
            # Key technical factors
            technical_factors = []
            
            if 'smc_range_break' in features:
                technical_factors.append("SMC Range Break confirmed")
            
            if 'fib_level' in features:
                fib = features.get('fib_level', '')
                if fib:
                    technical_factors.append(f"Price at {fib} Fib level")
            
            if 'confluence_mult' in signal_data and signal_data['confluence_mult'] > 1.2:
                technical_factors.append("High confluence (multiple indicators aligned)")
            
            if 'volatility_regime' in features:
                regime = features.get('volatility_regime', '')
                if regime:
                    technical_factors.append(f"Volatility: {regime}")
            
            # Macro factors
            macro_factors = []
            
            if macro_context:
                if macro_context.get('macro_bias'):
                    macro_factors.append(f"Macro bias: {macro_context['macro_bias']}")
                
                if macro_context.get('dxy_correlation'):
                    dxy_corr = macro_context['dxy_correlation']
                    if dxy_corr < -0.5:
                        macro_factors.append("DXY Diverging (bullish for XAU)")
                    elif dxy_corr > 0.5:
                        macro_factors.append("DXY Correlating (bearish for XAU)")
            
            # Pressure analysis
            if hasattr(self, 'pressure_stats'):
                pressure = self.pressure_stats.get('current', 0)
                if pressure > 0.3:
                    technical_factors.append("Candle Pressure Stabilizing (bullish)")
                elif pressure < -0.3:
                    technical_factors.append("Candle Pressure Stabilizing (bearish)")
            
            # Build reasoning string
            reasoning = ""
            
            if technical_factors:
                reasoning += " because " + " and ".join(technical_factors)
            
            if macro_factors:
                reasoning += (". " if reasoning else " with ") + ", ".join(macro_factors)
            
            if not reasoning:
                reasoning = "Multiple confluent signals aligned"
            
            return reasoning
        
        except Exception as e:
            LOG.debug(f"[v16.0] Dynamic reasoning generation failed: {e}")
            return "Signal generated based on multi-timeframe analysis"
    
    def _send_chart_payload(self, caption, chart_payload, disable_notification=False):
        """Send one or more chart images as separate Telegram photos."""
        if not self.enabled or not chart_payload:
            return False

        if isinstance(chart_payload, (list, tuple)):
            sent_any = False
            for idx, item in enumerate(chart_payload):
                if isinstance(item, tuple) and len(item) >= 2:
                    label, image_bytes = item[0], item[1]
                else:
                    label, image_bytes = None, item

                if not image_bytes:
                    continue

                sub_caption = caption
                if label:
                    sub_caption = f"{caption}\n\n📌 {label}" if caption else f"📌 {label}"
                elif len(chart_payload) > 1:
                    sub_caption = f"{caption}\n\n🖼️ Chart {idx + 1}/{len(chart_payload)}" if caption else f"🖼️ Chart {idx + 1}/{len(chart_payload)}"

                if self._send_photo_safe(sub_caption, image_bytes, disable_notification=disable_notification):
                    sent_any = True
            return sent_any

        return self._send_photo_safe(caption, chart_payload, disable_notification=disable_notification)

    def notify_signal(self, signal_data, chart_img=None, dynamic_reasoning=None, dfs=None):
        """
        Send signal notification with optional Plotly charts and dynamic reasoning
        
        v16.0 Enhancement: Includes dynamic reasoning captions
        v18.0 Enhancement: Supports media group distribution for multiple charts
        v18.1 Enhancement: Educational 3-chart package with zone analysis
        
        Args:
            signal_data: Signal details dict
            chart_img: Optional PNG bytes or list of PNG bytes from Plotly
            dynamic_reasoning: str explaining the signal rationale
            dfs: Optional dict of DataFrames by timeframe for chart generation
        """
        if not self.enabled:
            return
        
        direction = signal_data['dir']
        entry = signal_data['entry']
        sl = signal_data['sl']
        tp = signal_data['tp']
        score = signal_data['score']
        vol = signal_data.get('vol', 0.01)
        ml_conf = signal_data.get('ml_conf', 0.5)
        correlation = signal_data.get('correlation', 0.0)
        rejected_reason = signal_data.get('rejected_reason')
        
        if rejected_reason:
            if CFG.get("notify_rejected_signals", False):
                emoji = "⚠️"
                msg = (
                    f"{emoji} <b>REJECTED SIGNAL</b>\n"
                    f"[ Direction: {direction}\n"
                    f"| Score: {score:.1f}/15\n"
                    f"| Reason: {rejected_reason}\n"
                    f"| DXY Correlation: {correlation:.2f}\n"
                    f"[ ML Confidence: {ml_conf:.1%}"
                )
                self._send_message_safe(msg, disable_notification=True)
            return
        
        emoji = "🟢" if direction == 'BUY' else "🔴"
        signal_label = "SCALP SIGNAL" if signal_data.get('signal_type') == 'scalp' else "XAU/USD SIGNAL v16.0"
        tf = signal_data.get('tf', CFG["timeframes"][0])
        strategy = signal_data.get('strategy', 'unknown')
        signal_type = signal_data.get('signal_type', 'regular')
        
        msg = (
            f"{emoji} <b>{signal_label}</b>\n"
            f"[ Direction: <b>{direction}</b>\n"
            f"| TF: <code>{tf}</code>\n"
            f"| Strategy: <code>{strategy}</code>\n"
            f"| Signal Type: <code>{signal_type}</code>\n"
            f"| Entry: <code>{entry:.2f}</code>\n"
            f"| SL: <code>{sl:.2f}</code>\n"
            f"| TP: <code>{tp:.2f}</code>\n"
            f"| Score: <b>{score:.1f}/15</b>\n"
            f"| Volume: {vol:.2f} lots\n"
            f"| ML Confidence: {ml_conf:.1%}\n"
        )
        
        if correlation != 0.0:
            corr_icon = "✅" if correlation < CFG.get("correlation_threshold", 0.7) else "⚠️"
            msg += f"| DXY Correlation: {corr_icon} {correlation:.2f}\n"
        
        if dynamic_reasoning:
            msg += f"\n💡 <b>Dynamic Reasoning:</b>\n{dynamic_reasoning}\n"

        zone_reaction_data = {}
        if dfs and isinstance(dfs, dict):
            zone_reaction_data = ZONE_ANALYZER.summarize_multi_tf_zone_reactions(dfs)
            if zone_reaction_data:
                signal_data['zone_reaction_summary'] = zone_reaction_data
                msg += "\n📊 <b>Multi-Timeframe Zone Reactions:</b>\n"
                for tf, reaction_map in zone_reaction_data.items():
                    for direction, reaction in reaction_map.items():
                        if reaction is None:
                            continue
                        msg += (
                            f"{tf} {direction}: {reaction['reaction_type']} @ {reaction['zone_level']:.2f} "
                            f"({reaction['proximity_atr']:.2f} ATR)\n"
                        )
        
        entry_type = str(signal_data.get('order_type') or signal_data.get('entry_mode') or 'market').upper()
        entry_type_label = 'ZONE LIMIT' if entry_type == 'ZONE_LIMIT' else 'LIMIT' if entry_type == 'LIMIT' else 'MARKET'
        msg += f"| Entry Type: <code>{entry_type_label}</code>\n"
        if signal_data.get('zone') is not None:
            msg += f"| Zone: <code>{float(signal_data['zone']):.2f}</code>\n"
        if signal_data.get('support') is not None:
            msg += f"| Support: <code>{float(signal_data['support']):.2f}</code>\n"
        if signal_data.get('resistance') is not None:
            msg += f"| Resistance: <code>{float(signal_data['resistance']):.2f}</code>\n"
        msg += f"[ Time: {utc_now().strftime('%H:%M:%S')} UTC"

        # Send the same signal text to the signal-only recipient.
        if self.signal_chat_id and self.signal_chat_id != self.chat_id:
            self._send_message_to_chat(self.signal_chat_id, msg, disable_notification=True)
        
        # Send educational charts if available (v18.1)
        if CFG.get("send_chart_images", True) and CFG.get("use_educational_charts", True) and dfs:
            self.send_educational_charts_with_reasoning(signal_data, msg, dfs)
        # Send one or more clean chart images as separate photos for easier study.
        elif chart_img and CFG.get("send_chart_images", True):
            if isinstance(chart_img, list):
                if chart_img:
                    self._send_chart_payload(msg, chart_img)
                else:
                    self.notify(msg, important=True)
            else:
                self._send_photo_safe(msg, chart_img)
        else:
            self.notify(msg, important=True)
    
    def send_educational_charts_with_reasoning(self, signal_data, caption_text, df_dict=None):
        """
        v18.1: Send 3 educational charts as separate media group messages with delays
        
        Args:
            signal_data: Signal details (includes zone, support, resistance)
            caption_text: Main signal caption
            df_dict: Dict with DataFrames by timeframe {tf: df, ...}
        """
        if not self.enabled:
            return
        
        try:
            # Lazy-load EducationalChartGenerator on first use (v18.1)
            if self._chart_gen is None:
                try:
                    self._chart_gen = EducationalChartGenerator()
                except Exception as e:
                    LOG.error(f"[v18.1] Failed to initialize EducationalChartGenerator: {e}")
                    return
            
            # Get the most recent data (assume bot has access to MT5 data)
            # For now, we skip if df_dict not provided
            if df_dict is None:
                LOG.debug("[v18.1] Skipping educational charts (no dataframe provided)")
                return
            
            # Use preferred timeframe
            tf = signal_data.get('tf', 'M15')
            df = df_dict.get(tf)
            
            if df is None or df.empty:
                LOG.warning(f"[v18.1] No data for {tf} timeframe")
                return
            
            # Build comprehensive zone_data from the chart dataframe first
            zone_data = ZONE_ANALYZER.analyze_all(df)
            # Preserve any explicit signal-provided zones if available
            if signal_data.get('support') is not None:
                zone_data.setdefault('support_levels', [])
                if signal_data['support'] not in zone_data['support_levels']:
                    zone_data['support_levels'].append(signal_data['support'])
            if signal_data.get('resistance') is not None:
                zone_data.setdefault('resistance_levels', [])
                if signal_data['resistance'] not in zone_data['resistance_levels']:
                    zone_data['resistance_levels'].append(signal_data['resistance'])
            if signal_data.get('order_blocks'):
                zone_data.setdefault('order_blocks', [])
                zone_data['order_blocks'] = signal_data['order_blocks'] + zone_data.get('order_blocks', [])
            if signal_data.get('fvgs'):
                zone_data.setdefault('fvgs', [])
                zone_data['fvgs'] = signal_data['fvgs'] + zone_data.get('fvgs', [])
            if signal_data.get('zones'):
                zone_data.setdefault('zones', [])
                zone_data['zones'] = signal_data['zones'] + zone_data.get('zones', [])
            
            # Generate 3 charts using enriched zone data
            charts = self._chart_gen.create_3chart_education_package(df, signal_data, zone_data, dfs=df_dict)
            
            if not charts or len(charts) == 0:
                LOG.warning("[v18.1] No charts generated")
                return
            
            # Send signal text first
            self._send_message_safe(caption_text)
            
            # Send each chart with captions and delays
            import time
            chart_captions = [
                f"📊 <b>Chart 1: Price Action Setup</b>\n{signal_data.get('strategy', 'N/A')} | Score: {signal_data.get('score', 0):.1f}/15\nEntry: {signal_data.get('entry', 0):.2f} | SL: {signal_data.get('sl', 0):.2f} | TP: {signal_data.get('tp', 0):.2f}",
                f"🎯 <b>Chart 2: Smart Money Structure</b>\nOrder Blocks, FVGs, Support/Resistance levels\nTime: {utc_now().strftime('%H:%M:%S')} UTC",
                f"📈 <b>Chart 3: Momentum & Confluence</b>\nRSI Divergences, Zone Clustering, Volume Profile\nAnalysis Complete - Ready for Entry",
                f"🧭 <b>Chart 4: Zone Reaction Dashboard</b>\nMulti-Timeframe zone reaction status, support/resistance behavior, and trend context"
            ]
            
            for idx, (chart_img, caption) in enumerate(zip(charts, chart_captions)):
                try:
                    self._send_photo_safe(caption, chart_img, disable_notification=True)
                    if idx < len(charts) - 1:
                        time.sleep(2.5)  # 2.5 second delay between charts for mobile readability
                except Exception as e:
                    LOG.error(f"[v18.1] Chart {idx+1} send failed: {e}")
            
            LOG.info(f"[v18.1] Sent {len(charts)} educational charts")
            
        except Exception as e:
            LOG.error(f"[v18.1] Educational chart sending failed: {e}")
    
    def notify_trade_update(self, trade_data):
        if not self.enabled:
            return
        
        direction = trade_data['dir']
        action = trade_data.get('action', 'update')
        pnl = trade_data.get('pnl', 0)
        rr = trade_data.get('rr', 0)
        
        emoji = "🔔" if action == 'partial' else "🛡️" if action == 'profit_lock' else "⚡" if action == 'breakeven' else "📊"
        
        msg = f"{emoji} <b>TRADE UPDATE</b>\n{direction} "
        
        if action == 'partial':
            msg += f"Partial Close | RR: {rr:.1f}"
        elif action == 'profit_lock':
            msg += "SL moved to profit-lock level"
        elif action == 'breakeven':
            msg += "SL moved to Breakeven"
        elif action == 'close':
            pnl_emoji = "💰" if pnl > 0 else "💸"
            msg += f"Closed | PnL: {pnl_emoji} {pnl:.2f} | R:{rr:.1f}"
        
        self.notify(msg, important=(action == 'close' and pnl < 0))
    
    def notify_error(self, error_msg):
        if not self.enabled:
            LOG.error(f"[ERROR] {error_msg}")
            return
        
        # STAGE-10: dedupe repeated errors (600s window) so a stuck condition
        # cannot flood Telegram every cycle
        try:
            now = time.time()
            key = (error_msg or "")[:80]
            self._last_error_ts = getattr(self, "_last_error_ts", {})
            if self._last_error_ts.get(key) and now - self._last_error_ts.get(key) < 600:
                return
            self._last_error_ts[key] = now
        except Exception:
            pass
        msg = f"🚨 <b>BOT ERROR</b>\n{error_msg[:200]}"
        self._send_message_safe(msg, disable_notification=False)
    
    def notify_status(self, status_msg):
        if not self.enabled:
            LOG.info(f"[STATUS] {status_msg}")
            return
        
        msg = f"ℹ️ <b>STATUS</b>\n{status_msg}"
        self._send_message_safe(msg, disable_notification=True)
    
    def notify_balance(self, current_balance, change, change_pct, drawdown_pct):
        if not self.enabled:
            return
        
        emoji = "📈" if change >= 0 else "📉"
        msg = (
            f"{emoji} <b>BALANCE UPDATE</b>\n"
            f"[ Current: <b>${current_balance:.2f}</b>\n"
            f"| Change: {change:+.2f} ({change_pct:+.1f}%)\n"
            f"| Drawdown: {drawdown_pct:.1%}\n"
            f"[ Time: {utc_now().strftime('%H:%M:%S')}"
        )
        
        self._send_message_safe(msg, disable_notification=True)
    
    # v17.0: STUDY PACKAGE & CONFIRMATION METHODS
    def notify_signal_with_confirmation(self, signal_data, study_charts=None, keyboard=None, 
                                       dynamic_reasoning=None, alignment_multiplier=1.0):
        """
        v17.0: Send signal with Study Package (3 charts) and inline keyboard for manual confirmation.
        
        Args:
            signal_data: Signal details dict
            study_charts: List of chart PNG bytes [execution_chart, macro_chart, momentum_panel]
            keyboard: InlineKeyboardMarkup with [✅ CONFIRM] [❌ REJECT] buttons
            dynamic_reasoning: Reasoning caption
            alignment_multiplier: MTF alignment level for display
        """
        if not self.enabled:
            return
        
        direction = signal_data['dir']
        entry = signal_data['entry']
        sl = signal_data['sl']
        tp = signal_data['tp']
        score = signal_data['score']
        vol = signal_data.get('vol', 0.01)
        
        emoji = "🎯" if alignment_multiplier >= 1.5 else "🟢" if direction == 'BUY' else "🔴"
        
        msg = (
            f"{emoji} <b>XAU/USD GOLDEN SWING v17.0</b>\n"
            f"[ Direction: <b>{direction}</b>\n"
            f"| Entry: <code>{entry:.2f}</code>\n"
            f"| SL: <code>{sl:.2f}</code>\n"
            f"| TP: <code>{tp:.2f}</code>\n"
            f"| Score: <b>{score:.1f}/15</b>\n"
            f"| Volume: {vol:.2f} lots\n"
            f"| MTF Alignment: {alignment_multiplier:.2f}x ⭐\n"
        )
        
        if dynamic_reasoning:
            msg += f"\n💡 <b>Dynamic Reasoning:</b>\n{dynamic_reasoning}\n"
        
        msg += f"\n⏳ <b>Awaiting Manual Confirmation...</b>\n[ Time: {utc_now().strftime('%H:%M:%S')} UTC"
        
        try:
            # Send chart images if available (as media group)
            if study_charts and len(study_charts) > 0:
                try:
                    self._send_study_package(study_charts, msg, keyboard)
                    return
                except Exception as e:
                    LOG.warning(f"[v17.0] Study package send failed: {e} - falling back to text")
            
            # Fallback: send text with keyboard
            self._send_message_with_keyboard(msg, keyboard)
            
        except Exception as e:
            LOG.error(f"[v17.0] Confirmation notification failed: {e}")
            # Final fallback to standard notification
            self.notify(msg, important=True)
    
    def _send_study_package(self, chart_bytes_list, caption, keyboard):
        """Send 3-chart Study Package as media group with inline keyboard"""
        if not self.enabled or not REQUESTS_OK:
            return
        
        try:
            # For now, send first chart with keyboard (full media group API support pending)
            if chart_bytes_list and len(chart_bytes_list) > 0:
                self._send_photo_with_keyboard(caption, chart_bytes_list[0], keyboard)
                # Send other charts as follow-ups (text only for now)
                if len(chart_bytes_list) > 1:
                    LOG.debug(f"[v17.0] Sending {len(chart_bytes_list)-1} additional chart(s)")
        except Exception as e:
            LOG.error(f"[v17.0] Study package send failed: {e}")
    
    def _send_message_with_keyboard(self, message, keyboard):
        """Send message with inline keyboard buttons"""
        if not self.enabled or not REQUESTS_OK:
            return False
        
        try:
            url = f"{self.base_url}/sendMessage"
            payload = {
                'chat_id': self.chat_id,
                'text': message,
                'parse_mode': 'HTML',
                'reply_markup': keyboard.to_json() if hasattr(keyboard, 'to_json') else str(keyboard)
            }
            
            response = requests.post(url, json=payload, timeout=5)
            if response.status_code == 200:
                LOG.debug("[v17.0] Message with keyboard sent successfully")
                return True
            else:
                LOG.warning(f"[v17.0] Message send failed: {response.status_code}")
                return False
        except Exception as e:
            LOG.error(f"[v17.0] Keyboard message send failed: {e}")
            return False
    
    def _send_photo_with_keyboard(self, caption, image_bytes, keyboard):
        """Send photo with inline keyboard buttons"""
        if not self.enabled or not REQUESTS_OK:
            return False
        
        try:
            url = f"{self.base_url}/sendPhoto"
            
            files = {
                'photo': ('chart.png', image_bytes, 'image/png')
            }
            data = {
                'chat_id': self.chat_id,
                'caption': caption,
                'parse_mode': 'HTML',
                'reply_markup': keyboard.to_json() if hasattr(keyboard, 'to_json') else str(keyboard)
            }
            
            response = requests.post(url, files=files, data=data, timeout=10)
            if response.status_code == 200:
                LOG.debug("[v17.0] Photo with keyboard sent successfully")
                return True
            else:
                LOG.warning(f"[v17.0] Photo send failed: {response.status_code}")
                return False
        except Exception as e:
            LOG.error(f"[v17.0] Photo with keyboard send failed: {e}")
            return False
    
    def handle_swing_confirmation_callback(self, callback_data, user_id=None):
        """
        v17.0: Handle inline button callback for swing confirmation.
        Format: "confirm_swing:SIG123abc" or "reject_swing:SIG123abc"
        
        Args:
            callback_data: Callback query data
            user_id: Telegram user ID (for security check)
        
        Returns:
            {'action': 'confirm'/'reject', 'signal_id': '...', 'status': 'ok'/'error'}
        """
        try:
            action, signal_id = callback_data.split(':')
            
            if signal_id not in self.pending_swing_confirmations:
                LOG.warning(f"[v17.0] Callback received for expired signal: {signal_id}")
                return {'action': action, 'signal_id': signal_id, 'status': 'expired'}
            
            if action == 'confirm_swing':
                self.pending_swing_confirmations[signal_id]['status'] = 'confirmed'
                LOG.info(f"[v17.0] Golden Swing {signal_id} CONFIRMED by user")
                return {'action': 'confirm', 'signal_id': signal_id, 'status': 'ok'}
            
            elif action == 'reject_swing':
                del self.pending_swing_confirmations[signal_id]
                LOG.info(f"[v17.0] Golden Swing {signal_id} REJECTED by user")
                return {'action': 'reject', 'signal_id': signal_id, 'status': 'ok'}
            
            else:
                LOG.warning(f"[v17.0] Unknown callback action: {action}")
                return {'action': action, 'signal_id': signal_id, 'status': 'unknown'}
        
        except Exception as e:
            LOG.error(f"[v17.0] Callback handling failed: {e}")
            return {'status': 'error', 'error': str(e)}

TG = TelegramNotifier()

class ScalpingEngine:
    """Aggressive scalping for small balances (<$100) with safety limits."""
    
    def __init__(self, cfg=None):
        self.cfg = cfg or CFG
        self.enabled = self.cfg.get("scalping_enabled", False)
        self.balance_threshold = self.cfg.get("scalping_balance_threshold", 100.0)
        self.risk_mult = self.cfg.get("scalping_risk_multiplier", 2.0)
        self.profit_target = self.cfg.get("scalping_profit_target", 0.05)  # 5%
        self.max_holding_min = self.cfg.get("scalping_max_holding_minutes", 15)
        self.min_holding_min = self.cfg.get("scalping_min_holding_minutes", 5)
        self.atr_threshold = self.cfg.get("scalping_atr_threshold", 1.2)
        self.vol_cap = self.cfg.get("scalping_volatility_cap", 0.02)
        self.active_scalps = {}  # Track open scalp trades
        LOG.info("[SCALP] ScalpingEngine initialized")
    
    def should_scalp(self, balance):
        """Check if scalping should be active."""
        return self.enabled and balance <= self.balance_threshold
    
    def analyze_m1_m5(self, m1_df, m5_df):
        """Analyze M1/M5 charts for scalp signals.
        Returns: {'signal': 'BUY'/'SELL'/None, 'confidence': 0.0-1.0, 'entry': price}
        """
        if m1_df is None or m5_df is None or m1_df.empty or m5_df.empty:
            return {'signal': None, 'confidence': 0.0}
        
        try:
            # Get latest bars
            m1_last = m1_df.iloc[-1]
            m5_last = m5_df.iloc[-1]
            
            # Check volatility cap
            m1_atr = m1_last.get('atr', 0)
            m5_atr = m5_last.get('atr', 0)
            
            if m1_atr > self.atr_threshold or m5_atr > self.atr_threshold:
                return {'signal': None, 'confidence': 0.0, 'reason': 'volatility_too_high'}
            
            # M1 momentum (RSI)
            m1_rsi = m1_last.get('rsi', 50)
            m5_rsi = m5_last.get('rsi', 50)
            
            # M5 trend (EMA)
            m1_ema = m1_last.get('ema_9', m1_last['close'])
            m5_ema = m5_last.get('ema_9', m5_last['close'])
            
            m1_close = m1_last['close']
            m5_close = m5_last['close']
            
            # BUY signal: M1 above EMA, RSI < 70 (not overbought), M5 trend up
            if (m1_close > m1_ema and m1_rsi < 70 and m5_close > m5_ema and m5_rsi < 65):
                confidence = min(1.0, (70 - m1_rsi) / 50)  # Higher when RSI lower
                return {
                    'signal': 'BUY',
                    'confidence': confidence,
                    'entry': m1_close,
                    'reason': 'momentum_up'
                }
            
            # SELL signal: M1 below EMA, RSI > 30 (not oversold), M5 trend down
            if (m1_close < m1_ema and m1_rsi > 30 and m5_close < m5_ema and m5_rsi > 35):
                confidence = min(1.0, (m1_rsi - 30) / 50)  # Higher when RSI higher
                return {
                    'signal': 'SELL',
                    'confidence': confidence,
                    'entry': m1_close,
                    'reason': 'momentum_down'
                }
            
            return {'signal': None, 'confidence': 0.0, 'reason': 'no_momentum'}
        
        except Exception as e:
            LOG.error(f"[SCALP] M1/M5 analysis error: {e}")
            return {'signal': None, 'confidence': 0.0}
    
    def calculate_scalp_risk(self, entry_price, atr, balance, current_exposure=0):
        """Calculate safe position size for scalping.
        Risk = balance * risk_mult * (atr / entry_price) with volatility caps
        """
        try:
            # Base risk
            base_risk = balance * 0.01  # 1% of balance per scalp
            
            # Adjust by volatility (ATR)
            vol_pct = (atr / entry_price) if entry_price > 0 else 0.002
            vol_pct = min(vol_pct, self.vol_cap)  # Cap at 2%
            
            # Apply risk multiplier but cap total exposure
            risk_amount = base_risk * self.risk_mult * (1 + vol_pct * 5)
            risk_pct = (risk_amount / balance) if balance > 0 else 0.02
            
            # Never exceed 5% total account risk for scalps
            risk_pct = min(risk_pct, 0.05)
            
            # Stop loss distance
            sl_distance = atr * 1.5  # 1.5x ATR
            
            # Position size
            position_risk = balance * risk_pct
            if sl_distance > 0:
                position_size = position_risk / sl_distance
            else:
                position_size = balance * 0.01
            
            return {
                'position_size': position_size,
                'risk_amount': position_risk,
                'sl_distance': sl_distance,
                'risk_pct': risk_pct
            }
        
        except Exception as e:
            LOG.error(f"[SCALP] Risk calculation error: {e}")
            return None
    
    def generate_scalp_signal(self, m1_df, m5_df, current_price, atr, balance):
        """Generate complete scalp trade signal."""
        try:
            # Get momentum signal
            momentum = self.analyze_m1_m5(m1_df, m5_df)
            if momentum['signal'] is None:
                return None
            
            # Calculate risk
            risk_calc = self.calculate_scalp_risk(current_price, atr, balance)
            if not risk_calc:
                return None
            
            direction = momentum['signal']
            entry = current_price
            
            # Set targets based on direction
            if direction == 'BUY':
                tp = entry * (1 + self.profit_target)  # 5% profit
                sl = entry - risk_calc['sl_distance']   # 1.5x ATR below
            else:  # SELL
                tp = entry * (1 - self.profit_target)
                sl = entry + risk_calc['sl_distance']
            
            signal = {
                'dir': direction,
                'entry': entry,
                'sl': sl,
                'tp': tp,
                'confidence': momentum['confidence'],
                'volume': risk_calc['position_size'],
                'type': 'scalp',
                'signal_type': 'scalp',
                'strategy': 'scalping',
                'tf': 'M5',
                'reference_tf': 'M1',
                'atr': atr,
                'features': {
                    'scalp_confidence': momentum['confidence'],
                    'scalp_reason': momentum['reason'],
                    'atr': atr,
                },
                'raw_score': max(5.0, min(12.0, momentum['confidence'] * 10 + 1.0)),
                'score': max(5.0, min(12.0, momentum['confidence'] * 10 + 1.0)),
                'reasons': [momentum.get('reason', 'scalp_momentum')],
                'max_hold_min': self.max_holding_min,
                'reason': momentum['reason']
            }
            
            LOG.info(f"[SCALP] Signal: {direction} @{entry:.2f}, TP:{tp:.2f}, SL:{sl:.2f}, Vol:{risk_calc['position_size']:.3f}")
            return signal
        
        except Exception as e:
            LOG.error(f"[SCALP] Signal generation error: {e}")
            return None
    
    def check_scalp_exit(self, trade_id, entry_price, current_price, entry_time, direction):
        """Check if scalp trade should be closed (time-based or TP/SL).
        Returns: {'should_close': bool, 'reason': 'profit'/'time'/'stoploss'}
        """
        try:
            time_held = (utc_now() - entry_time).total_seconds() / 60  # minutes
            
            # Time-based exit (always close after max_holding_min)
            if time_held > self.max_holding_min:
                pnl_pct = ((current_price - entry_price) / entry_price) if direction == 'BUY' else (
                    (entry_price - current_price) / entry_price)
                return {
                    'should_close': True,
                    'reason': 'time_expired',
                    'time_held_min': time_held,
                    'pnl_pct': pnl_pct
                }
            
            # Don't close before min_holding_min
            if time_held < self.min_holding_min:
                return {'should_close': False}
            
            return {'should_close': False}
        
        except Exception as e:
            LOG.error(f"[SCALP] Exit check error: {e}")
            return {'should_close': False}
    
    def notify_scalp_entry(self, signal: Dict):
        """Send Telegram notification for scalp entry
        
        Includes M1/M5 timeframe details, entry/SL/TP, and profit target
        """
        try:
            if not CFG.get("tg_token"):
                return
            
            direction = signal.get('dir', '?')
            entry = signal.get('entry', 0)
            sl = signal.get('sl', 0)
            tp = signal.get('tp', 0)
            confidence = signal.get('confidence', 0)
            volume = signal.get('volume', 0)
            reason = signal.get('reason', 'signal')
            
            emoji = "🟢" if direction == 'BUY' else "🔴"
            
            msg = (
                f"{emoji} <b>SCALP ENTRY</b> (M1/M5)\n"
                f"| Direction: <b>{direction}</b>\n"
                f"| Entry: <code>{entry:.2f}</code>\n"
                f"| SL: <code>{sl:.2f}</code>\n"
                f"| TP: <code>{tp:.2f}</code>\n"
                f"| Confidence: {confidence:.0%}\n"
                f"| Size: {volume:.3f} lots\n"
                f"| Hold Time: {self.max_holding_min:.0f} min\n"
                f"| Reason: {reason}\n"
                f"[ Target Profit: {self.profit_target:.1%}"
            )
            
            self._send_telegram_safe(msg)
            LOG.info(f"[SCALP] Telegram notification sent for {direction} entry @{entry:.2f}")
        except Exception as e:
            LOG.debug(f"[SCALP] Notification error: {e}")
    
    def notify_scalp_exit(self, trade_id: str, entry_price: float, exit_price: float, 
                         direction: str, profit_loss: float, reason: str):
        """Send Telegram notification for scalp exit with profit/loss
        
        Includes duration, entry/exit prices, P&L, and reason
        """
        try:
            if not CFG.get("tg_token"):
                return
            
            pnl_pct = ((exit_price - entry_price) / entry_price * 100) if direction == 'BUY' else (
                (entry_price - exit_price) / entry_price * 100)
            
            emoji = "✅" if profit_loss > 0 else "❌"
            profit_emoji = "📈" if pnl_pct > 0 else "📉"
            
            msg = (
                f"{emoji} <b>SCALP EXIT</b>\n"
                f"| Direction: {direction}\n"
                f"| Entry: <code>{entry_price:.2f}</code>\n"
                f"| Exit: <code>{exit_price:.2f}</code>\n"
                f"| P&L: {profit_emoji} <b>${profit_loss:.2f}</b>\n"
                f"| Return: <b>{pnl_pct:.2f}%</b>\n"
                f"| Reason: {reason}\n"
                f"[ Ticket: {trade_id}"
            )
            
            self._send_telegram_safe(msg)
            LOG.info(f"[SCALP] Telegram notification sent for exit: {reason}, P&L={profit_loss:.2f}")
        except Exception as e:
            LOG.debug(f"[SCALP] Exit notification error: {e}")
    
    def _send_telegram_safe(self, message: str):
        """Safely send Telegram message without blocking
        
        Uses requests.get for HTTP API
        """
        try:
            if not TG_OK or not CFG.get("tg_token"):
                return
            
            token = CFG["tg_token"]
            chat_id = CFG.get("tg_chat_id", "")
            
            if not chat_id:
                return
            
            url = f"https://api.telegram.org/bot{token}/sendMessage"
            params = {
                "chat_id": chat_id,
                "text": message,
                "parse_mode": "HTML"
            }
            
            # Non-blocking send
            try:
                response = requests.get(url, params=params, timeout=5)
                if response.status_code != 200:
                    LOG.debug(f"[SCALP] Telegram send failed: {response.status_code}")
            except requests.exceptions.RequestException as e:
                LOG.debug(f"[SCALP] Telegram connection error: {e}")
        except Exception as e:
            LOG.debug(f"[SCALP] Safe telegram send error: {e}")

class NewsProtector:
    def __init__(self):
        self.cache_path = CFG["news_cache_path"]
        self.cache_ttl = 86400
    
    def get_events(self):
        cached = self._load_cache()
        if cached:
            return cached
        
        events = self._fetch_ff()
        if not events:
            events = self._generate_major()
        
        self._save_cache(events)
        return events
    
    def _fetch_ff(self):
        if not REQUESTS_OK:
            return []
        
        try:
            headlines = fetch_real_news()
            if headlines:
                CFG["macro_headlines"] = headlines[:10]
            url = "https://nfs.faireconomy.media/ff_calendar_thisweek.json"
            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                data = response.json()
                return [
                    {
                        'title': item.get('title', ''),
                        'time': item.get('date', ''),
                        'impact': 'high'
                    }
                    for item in data
                    if item.get('impact') in ['High', 'high']
                ]
        except Exception as e:
            LOG.warning(f"[NEWS] Fetch failed: {e}")
        return []
    
    def _generate_major(self):
        now = utc_now()
        events = []
        for i in range(7):
            date = now + timedelta(days=i)
            if date.weekday() == 4 and date.day <= 7:
                nfp_time = date.replace(hour=13, minute=30)
                events.append({
                    'title': 'NFP',
                    'time': nfp_time.isoformat(),
                    'impact': 'high'
                })
        return events
    
    def _load_cache(self):
        if os.path.exists(self.cache_path):
            try:
                with open(self.cache_path, 'r') as f:
                    data = json.load(f)
                    if time.time() - data['ts'] < self.cache_ttl:
                        return data['events']
            except Exception as e:
                LOG.warning(f"[NEWS] Cache load failed: {e}")
        return None
    
    def _save_cache(self, events):
        if events:
            try:
                with open(self.cache_path, 'w') as f:
                    json.dump({
                        'ts': time.time(),
                        'events': events
                    }, f, indent=2)
            except Exception as e:
                LOG.warning(f"[NEWS] Cache save failed: {e}")
    
    def is_news_time(self):
        now = utc_now()
        for ev in self.get_events():
            if 'time' not in ev:
                continue
            try:
                news_time = datetime.fromisoformat(ev['time'].replace('Z', '+00:00'))
                start = news_time - timedelta(minutes=15)
                end = news_time + timedelta(minutes=45)
                if start <= now <= end:
                    return True
            except Exception as e:
                LOG.warning(f"[NEWS] Time parsing error: {e}")
        return False
    
    def check_during(self, start, end):
        for ev in self.get_events():
            if 'time' not in ev:
                continue
            try:
                news_time = datetime.fromisoformat(ev['time'].replace('Z', '+00:00'))
                if start <= news_time <= end:
                    return True
            except Exception as e:
                LOG.warning(f"[NEWS] Time parsing error: {e}")
        return False

NEWS = NewsProtector()

class NewsAdaptiveExecution:
    def __init__(self, news_source):
        self.news_source = news_source
        self.last_regime = "NORMAL"
        self.last_event_end = None

    def _event_window(self, ev):
        news_time = datetime.fromisoformat(ev['time'].replace('Z', '+00:00'))
        start = news_time - timedelta(minutes=15)
        end = news_time + timedelta(minutes=45)
        return start, end

    def _is_extreme(self, title):
        if not title:
            return False
        title_upper = title.upper()
        for key in CFG.get("extreme_news_titles", []):
            if key.upper() in title_upper:
                return True
        return False

    def get_regime(self):
        now = utc_now()
        for ev in self.news_source.get_events():
            if 'time' not in ev:
                continue
            try:
                start, end = self._event_window(ev)
                if start <= now <= end:
                    self.last_event_end = end
                    if self._is_extreme(ev.get('title', '')):
                        self.last_regime = "EXTREME_NEWS"
                        return "EXTREME_NEWS"
                    self.last_regime = "HIGH_VOL_NEWS"
                    return "HIGH_VOL_NEWS"
            except Exception as e:
                LOG.warning(f"[NEWS] Regime parsing error: {e}")
        self.last_regime = "NORMAL"
        return "NORMAL"

    def _blend_params(self, base_params, target_params, alpha):
        blended = {}
        for key in base_params:
            if isinstance(base_params[key], (int, float)) and isinstance(target_params.get(key), (int, float)):
                blended[key] = base_params[key] * (1 - alpha) + target_params[key] * alpha
            else:
                blended[key] = target_params.get(key, base_params[key])
        return blended

    def get_params(self, regime):
        normal = CFG["news_regime_params"]["NORMAL"]
        params = CFG["news_regime_params"].get(regime, normal)

        if self.last_event_end and regime == "NORMAL":
            cooldown = CFG.get("news_cooldown_minutes", 90)
            mins = (utc_now() - self.last_event_end).total_seconds() / 60
            if 0 <= mins <= cooldown:
                alpha = max(0.0, min(1.0, 1.0 - (mins / cooldown)))
                params = self._blend_params(normal, CFG["news_regime_params"].get(self.last_regime, normal), alpha)

        return params

    def select_limit_price(self, df, direction):
        """Select limit price from pivot levels, validated against current market price"""
        if df is None or df.empty:
            return None
        
        # Get fresh market price to validate pivot levels
        tick = MT5.get_fresh_tick() if MT5 else None
        current_market = tick['mid'] if tick else None
        
        highs = df['high']
        lows = df['low']
        window = 5
        piv_high = highs[(highs.shift(window) < highs) & (highs.shift(-window) < highs)]
        piv_low = lows[(lows.shift(window) > lows) & (lows.shift(-window) > lows)]
        levels = pd.concat([piv_high, piv_low]).dropna().values
        if len(levels) == 0:
            return None
        
        df_close = df['close'].iloc[-1]
        
        # If current market price differs significantly from df close, use market price instead
        if current_market and abs(current_market - df_close) / df_close > 0.005:  # >0.5% diff = stale data
            current = current_market
        else:
            current = df_close
        
        if direction == 'BUY':
            # For BUY: find support below current price
            supports = [lvl for lvl in levels if lvl <= current]
            return max(supports) if supports else None
        else:
            # For SELL: find resistance above current price
            resist = [lvl for lvl in levels if lvl >= current]
            return min(resist) if resist else None

class NewsAwareRiskManager:
    def adjust_volume(self, vol, params):
        size_mult = params.get("size_mult", 1.0)
        adjusted = vol * size_mult
        adjusted = max(EXNESS['min_lot'], round(adjusted / EXNESS['step']) * EXNESS['step'])
        return adjusted

