class UrgencyScoreCalculator:
    """Calculates urgency (0-100) for order execution decisions based on multiple factors"""
    def __init__(self, session_detector=None, cfg=None):
        self.session_detector = session_detector
        self.cfg = cfg or CFG
    
    def calculate(self, bars_dict: Dict, current_price: float, rsi: float, atr: float, 
                  fib_zones: List[float], smc_obos: Dict) -> float:
        """
        Calculate urgency score (0-100).
        
        Factors:
        - Session (London/NY = +30 points, Asian = 0)
        - RSI/ATR Velocity (fast moves = +20 to +40)
        - Distance to Fib/SMC zones (near 61.8% or OB = +20 to +40)
        
        Returns:
            float: Urgency score 0-100
        """
        try:
            urgency = 50.0  # Base score
            
            # Factor 1: Session Urgency (London/NY = higher)
            if self.session_detector:
                session = self.session_detector.detect_current_session()
                if session == 'EUROPEAN':
                    urgency += 20  # London = +20
                elif session == 'US':
                    urgency += 30  # NY = +30
                # ASIAN = 0 bonus
            
            # Factor 2: RSI/ATR Velocity (fast moves indicate strong momentum)
            if atr > 0:
                # ATR velocity: compare current ATR to rolling avg
                h1_bars = bars_dict.get('H1', [])
                if len(h1_bars) >= 14:
                    atr_values = [h1_bars[i].get('atr', atr) for i in range(-14, 0)]
                    atr_avg = np.mean(atr_values) if atr_values else atr
                    atr_velocity = (atr / atr_avg - 1.0) if atr_avg > 0 else 0  # % above average
                    
                    if atr_velocity > 0.3:  # ATR > 130% of average = very fast
                        urgency += 40
                    elif atr_velocity > 0.15:  # ATR > 115% = moderately fast
                        urgency += 20
                    elif atr_velocity > 0.05:  # ATR > 105% = slightly fast
                        urgency += 10
            
            # RSI momentum (RSI velocity)
            if 40 < rsi < 60:  # RSI neutral zone = lower urgency
                urgency -= 10
            elif rsi > 70 or rsi < 30:  # Extreme RSI = higher urgency
                urgency += 15
            
            # Factor 3: Distance to Fibonacci/SMC Zones
            if fib_zones:
                # Find nearest Fib level
                distances = [abs(current_price - zone) for zone in fib_zones]
                min_dist = min(distances)
                max_dist = max(distances)
                
                # Normalize distance to 0-1 scale
                if max_dist > min_dist:
                    normalized_dist = min_dist / (max_dist - min_dist) if (max_dist - min_dist) > 0 else 0
                else:
                    normalized_dist = 0
                
                # Near a zone (normalized_dist < 0.2 = within 20%) = higher urgency
                if normalized_dist < 0.15:  # Very close to zone
                    urgency += 40
                elif normalized_dist < 0.3:  # Approaching zone
                    urgency += 20
            
            # SMC Order Block / Supply/Demand urgency
            if smc_obos:
                ob_dist = smc_obos.get('ob_distance', float('inf'))
                os_dist = smc_obos.get('os_distance', float('inf'))
                
                # Very close to OB/OS = higher urgency
                if min(ob_dist, os_dist) < atr * 0.5:  # Within 0.5 ATR of OB/OS
                    urgency += 20
                elif min(ob_dist, os_dist) < atr * 1.0:  # Within 1 ATR
                    urgency += 10
            
            # Clamp to 0-100 range
            urgency = max(0.0, min(100.0, urgency))
            
            LOG.debug(f"[URGENCY] Score: {urgency:.1f} (Session: {session if self.session_detector else 'N/A'}, ATR vel: {atr_velocity*100 if atr > 0 else 0:.1f}%, RSI: {rsi:.1f})")
            return urgency
            
        except Exception as e:
            LOG.error(f"[URGENCY] Calculation error: {e}")
            return 50.0  # Default to neutral


class PendingOrderTracker:
    """Tracks pending orders and their associated signals for cancellation logic"""
    def __init__(self):
        self.pending_orders: Dict[int, Dict] = {}  # ticket -> {signal_id, signal_score, entry_time, ...}
        self.signal_scores: Dict[str, float] = {}  # signal_id -> current_score
        self.last_check = {}  # signal_id -> last_check_time
        self.check_interval_sec = 15  # Re-evaluate every 15 seconds
    
    def link_order_to_signal(self, ticket: int, signal_id: str, initial_score: float):
        """Link a pending order to its signal"""
        self.pending_orders[ticket] = {
            'signal_id': signal_id,
            'signal_score': initial_score,
            'entry_time': time.time(),
            'status': 'pending'
        }
        self.signal_scores[signal_id] = initial_score
        LOG.info(f"[ORDER-TRACKER] Order {ticket} linked to signal {signal_id} (score: {initial_score:.2f})")
    
    def update_signal_score(self, signal_id: str, new_score: float):
        """Update signal score, may trigger order cancellation"""
        self.signal_scores[signal_id] = new_score
        
        # Find all orders linked to this signal
        for ticket, order_data in list(self.pending_orders.items()):
            if order_data['signal_id'] == signal_id:
                order_data['signal_score'] = new_score
                
                # Check if score dropped below threshold
                if new_score < 5.0:
                    LOG.warning(f"[ORDER-TRACKER] Signal {signal_id} score dropped to {new_score:.2f}, cancelling order {ticket}")
                    return ticket  # Return ticket to be cancelled
        
        return None
    
    def check_pending_orders(self, current_time: float) -> List[int]:
        """Check all pending orders for cancellation. Returns list of tickets to cancel."""
        tickets_to_cancel = []
        
        for ticket, order_data in list(self.pending_orders.items()):
            signal_id = order_data['signal_id']
            
            # Check if we should re-evaluate this signal
            if signal_id not in self.last_check:
                self.last_check[signal_id] = current_time
            
            if current_time - self.last_check[signal_id] >= self.check_interval_sec:
                signal_score = self.signal_scores.get(signal_id, order_data['signal_score'])
                
                # Cancel if score dropped below 5.0
                if signal_score < 5.0:
                    LOG.warning(f"[ORDER-TRACKER] Order {ticket} (signal {signal_id}) score dropped to {signal_score:.2f}, marking for cancellation")
                    tickets_to_cancel.append(ticket)
                    order_data['status'] = 'cancelled'
                
                self.last_check[signal_id] = current_time
        
        return tickets_to_cancel
    
    def remove_order(self, ticket: int):
        """Remove order from tracking (filled or cancelled)"""
        if ticket in self.pending_orders:
            order_data = self.pending_orders.pop(ticket)
            LOG.debug(f"[ORDER-TRACKER] Order {ticket} removed from tracking (status: {order_data['status']})")
    
    def get_pending_count(self) -> int:
        """Get count of pending tracked orders"""
        return len(self.pending_orders)


class LLMGovernor:
    """Rate limit governor for Gemini LLM API calls with intelligent caching"""
    def __init__(self, max_rpm: int = 15, cache_ttl_sec: int = 300):
        self.max_rpm = max_rpm
        self.cache_ttl_sec = cache_ttl_sec
        self.call_timestamps = deque(maxlen=max_rpm)  # Track last N calls
        self.sentiment_cache: Dict[str, Dict] = {}  # news_headline -> {sentiment, bias, timestamp}
        self.last_cache_cleanup = time.time()
        self.api_key = CFG.get("macro_llm_api_key", "")
    
    def is_rate_limited(self) -> bool:
        """Check if we've hit rate limit in the last 60 seconds"""
        current_time = time.time()
        
        # Clean old timestamps outside the 60-second window
        while self.call_timestamps and (current_time - self.call_timestamps[0]) > 60:
            self.call_timestamps.popleft()
        
        return len(self.call_timestamps) >= self.max_rpm
    
    def can_call_llm(self, trigger_reason: str = "manual") -> bool:
        """Determine if we should call LLM based on rate limits and trigger conditions"""
        # Check rate limit
        if self.is_rate_limited():
            LOG.debug(f"[LLM-GOVERNOR] Rate limited (15 RPM), skipping call")
            return False
        
        # Only call if:
        # (a) Valid technical setup (RSI extreme, strong ATR, near Fib zones)
        # (b) News API detected High Impact headline
        # (c) Manual override
        
        if trigger_reason == "technical_setup":
            return True
        elif trigger_reason == "high_impact_news":
            return True
        elif trigger_reason == "manual":
            return True
        
        return False
    
    def record_llm_call(self):
        """Record timestamp of LLM call for rate limiting"""
        self.call_timestamps.append(time.time())
        LOG.debug(f"[LLM-GOVERNOR] LLM call recorded ({len(self.call_timestamps)}/{self.max_rpm} in last 60s)")
    
    def get_cached_sentiment(self, headline: str) -> Optional[Dict]:
        """Get cached sentiment if available and not expired"""
        current_time = time.time()
        
        # Cleanup expired cache entries periodically
        if current_time - self.last_cache_cleanup > 60:
            expired_keys = [
                k for k, v in self.sentiment_cache.items()
                if current_time - v['timestamp'] > self.cache_ttl_sec
            ]
            for k in expired_keys:
                del self.sentiment_cache[k]
            self.last_cache_cleanup = current_time
            if expired_keys:
                LOG.debug(f"[LLM-GOVERNOR] Cleaned {len(expired_keys)} expired cache entries")
        
        # Check if headline is in cache and not expired
        if headline in self.sentiment_cache:
            entry = self.sentiment_cache[headline]
            if current_time - entry['timestamp'] <= self.cache_ttl_sec:
                LOG.debug(f"[LLM-GOVERNOR] Cache HIT for headline (TTL: {self.cache_ttl_sec}s)")
                return entry
        
        return None
    
    def cache_sentiment(self, headline: str, sentiment: str, bias: float):
        """Cache sentiment analysis result"""
        self.sentiment_cache[headline] = {
            'sentiment': sentiment,
            'bias': bias,
            'timestamp': time.time()
        }
        LOG.debug(f"[LLM-GOVERNOR] Cached sentiment for headline: {sentiment} (bias: {bias:.2f})")


class TierExecutionManager:
    """50/25/25 Tier logic for partial closes on trades >= 0.03 lots"""
    def __init__(self):
        self.tier_thresholds = [0.5, 0.75, 1.0]  # Close 50% at 0.5x target, 25% at 0.75x, 25% at target
        self.tier_levels = ['tier_1', 'tier_2', 'tier_3']
        self.tier_percentages = [0.50, 0.25, 0.25]  # 50%, 25%, 25%
    
    def should_apply_tier_logic(self, init_vol: float) -> bool:
        """Check if volume qualifies for tier logic (>= 0.03 lots)"""
        return init_vol >= 0.03
    
    def calculate_tier_volumes(self, init_vol: float) -> Dict[str, float]:
        """Calculate volume for each tier based on init_vol"""
        try:
            if not self.should_apply_tier_logic(init_vol):
                return {'tier_1': init_vol, 'tier_2': 0.0, 'tier_3': 0.0, 'total': init_vol}
            
            tier_1_vol = round(init_vol * self.tier_percentages[0], 2)  # 50%
            tier_2_vol = round(init_vol * self.tier_percentages[1], 2)  # 25%
            tier_3_vol = round(init_vol * self.tier_percentages[2], 2)  # 25%
            
            # Handle rounding issues
            total = tier_1_vol + tier_2_vol + tier_3_vol
            if total != init_vol:
                tier_3_vol += init_vol - total
                tier_3_vol = round(tier_3_vol, 2)
            
            return {
                'tier_1': tier_1_vol,
                'tier_2': tier_2_vol,
                'tier_3': tier_3_vol,
                'total': round(tier_1_vol + tier_2_vol + tier_3_vol, 2)
            }
        except Exception as e:
            LOG.error(f"[TIER] Calculation error: {e}")
            return {'tier_1': init_vol, 'tier_2': 0.0, 'tier_3': 0.0, 'total': init_vol}
    
    def calculate_tier_targets(self, entry: float, tp: float, direction: str) -> Dict[str, float]:
        """Calculate take-profit levels for each tier"""
        try:
            if direction == 'BUY':
                distance = tp - entry
                tier_1_tp = entry + distance * 0.50  # Close 50% at 50% of distance
                tier_2_tp = entry + distance * 0.75  # Close 25% at 75% of distance
                tier_3_tp = tp                        # Close 25% at full target
            else:
                distance = entry - tp
                tier_1_tp = entry - distance * 0.50
                tier_2_tp = entry - distance * 0.75
                tier_3_tp = tp
            
            return {
                'tier_1_tp': round(tier_1_tp, 4),
                'tier_2_tp': round(tier_2_tp, 4),
                'tier_3_tp': tier_3_tp
            }
        except Exception as e:
            LOG.error(f"[TIER] Target calculation error: {e}")
            return {'tier_1_tp': tp, 'tier_2_tp': tp, 'tier_3_tp': tp}
    
    def get_tier_info(self, init_vol: float) -> str:
        """Get readable tier information"""
        tiers = self.calculate_tier_volumes(init_vol)
        return f"Tier1(50%): {tiers['tier_1']}, Tier2(25%): {tiers['tier_2']}, Tier3(25%): {tiers['tier_3']}"


class AdaptiveDispatcher:
    """Decision engine for order placement based on urgency score and market conditions"""
    def __init__(self, mt5_conn=None, session_detector=None, cfg=None):
        self.mt5_conn = mt5_conn
        self.session_detector = session_detector
        self.cfg = cfg or CFG
        self.urgency_calc = UrgencyScoreCalculator(session_detector, cfg)
        self.order_tracker = PendingOrderTracker()
        self.llm_governor = LLMGovernor(max_rpm=15, cache_ttl_sec=300)
        self.tier_manager = TierExecutionManager()
    
    def dispatch_order(self, direction: str, entry: float, sl: float, tp: float, vol: float,
                      signal_id: str, signal_score: float, bars_dict: Dict, 
                      rsi: float, atr: float, fib_zones: List[float], smc_obos: Dict,
                      current_price: float = None, poc: float = None, high_vol_nodes: List[float] = None,
                      low_vol_nodes: List[float] = None) -> int:
        """
        Main dispatch logic: Calculate urgency and decide order type.
        
        v15.0 ENHANCEMENT: Liquidity-aware order type selection using volume profile
        
        Args:
            direction: 'BUY' or 'SELL'
            entry, sl, tp, vol: Order parameters
            signal_id: Unique signal identifier
            signal_score: Current signal score
            bars_dict: Dict with bars by timeframe
            rsi, atr: Technical indicators
            fib_zones: List of Fibonacci retracement levels
            smc_obos: Dict with SMC Order Block/Supply distances
            current_price: Current market price (optional)
            poc: Point of Control from volume profile (optional)
            high_vol_nodes: List of high volume nodes (optional)
            low_vol_nodes: List of low volume nodes (optional)
        
        Returns:
            int: Order ticket (0 if failed)
        """
        try:
            # Normalize volume
            vol = round(vol, 2)
            
            # Get current price if not provided
            if current_price is None:
                current_price = entry
                if self.mt5_conn:
                    tick = self.mt5_conn.get_fresh_tick()
                    if tick:
                        current_price = tick['mid']
            
            # Calculate urgency score
            urgency = self.urgency_calc.calculate(bars_dict, current_price, rsi, atr, fib_zones, smc_obos)
            
            # --- v15.0 Liquidity Layer: Volume Profile Decision ---
            # Check if we're in high or low volume nodes
            in_high_vol = False
            in_low_vol = False
            near_poc = False
            
            if high_vol_nodes and isinstance(high_vol_nodes, list) and len(high_vol_nodes) > 0:
                tolerance = self.cfg.get('volume_node_tolerance_pips', 0.5) * 0.0001
                for hvn in high_vol_nodes:
                    if abs(current_price - hvn) < tolerance:
                        in_high_vol = True
                        break
            
            if low_vol_nodes and isinstance(low_vol_nodes, list) and len(low_vol_nodes) > 0:
                tolerance = self.cfg.get('volume_node_tolerance_pips', 0.5) * 0.0001
                for lvn in low_vol_nodes:
                    if abs(current_price - lvn) < tolerance:
                        in_low_vol = True
                        break
            
            if poc is not None:
                poc_tolerance = self.cfg.get('poc_tolerance_pips', 1.0) * 0.0001
                near_poc = abs(current_price - poc) < poc_tolerance
            
            # Decide order type based on urgency + liquidity profile
            ticket = 0
            order_rationale = ""
            
            # PRIORITY: Low volume nodes get MARKET orders (liquidity seeking)
            if in_low_vol and urgency > 50:
                order_type = "MARKET"
                order_rationale = f"Low volume node + urgency {urgency:.1f}"
                LOG.info(f"[DISPATCHER] {order_rationale}: MARKET ORDER {direction} {vol} @ {current_price}")
                ticket = self.mt5_conn.place_market(direction, sl, tp, vol) if self.mt5_conn else 0
            
            # HIGH VOLUME NODES or NEAR POC: Use LIMIT orders (price sensitive)
            elif (in_high_vol or near_poc) and urgency < 70:
                order_type = "LIMIT"
                offset = self.cfg.get("limit_offset_pips", 0.5) * 0.0001
                if direction == 'BUY':
                    limit_price = current_price - offset
                else:
                    limit_price = current_price + offset
                order_rationale = f"High volume {'node' if in_high_vol else 'near POC'} + moderate urgency {urgency:.1f}"
                LOG.info(f"[DISPATCHER] {order_rationale}: LIMIT ORDER {direction} {vol} @ {limit_price:.4f}")
                ticket = self.mt5_conn.place_limit(direction, limit_price, sl, tp, vol) if self.mt5_conn else 0
            
            # STANDARD: Urgency-based decision for other zones
            elif urgency > 80:
                order_type = "MARKET"
                order_rationale = f"High urgency {urgency:.1f}"
                LOG.info(f"[DISPATCHER] {order_rationale}: MARKET ORDER {direction} {vol} @ {current_price}")
                ticket = self.mt5_conn.place_market(direction, sl, tp, vol) if self.mt5_conn else 0
            
            elif urgency < 40 and fib_zones:
                order_type = "LIMIT"
                offset = self.cfg.get("limit_offset_pips", 0.5) * 0.0001
                if direction == 'BUY':
                    limit_price = current_price - offset
                else:
                    limit_price = current_price + offset
                order_rationale = f"Low urgency {urgency:.1f} near structure"
                LOG.info(f"[DISPATCHER] {order_rationale}: LIMIT ORDER {direction} {vol} @ {limit_price:.4f}")
                ticket = self.mt5_conn.place_limit(direction, limit_price, sl, tp, vol) if self.mt5_conn else 0
            
            else:
                order_type = "STOP-LIMIT"
                order_rationale = f"Moderate urgency {urgency:.1f}"
                LOG.info(f"[DISPATCHER] {order_rationale}: STOP-LIMIT ORDER {direction} {vol}")
                ticket = self.mt5_conn.place_stop(direction, current_price, sl, tp, vol) if self.mt5_conn else 0
            
            # Link ticket to signal for tracking
            if ticket > 0:
                self.order_tracker.link_order_to_signal(ticket, signal_id, signal_score)
                LOG.info(f"[DISPATCHER] Order {ticket} ({order_type}) dispatched: {order_rationale}")
            
            return ticket
            
        except Exception as e:
            LOG.error(f"[DISPATCHER] Order dispatch error: {e}")
            return 0
    
    def reevaluate_signal(self, signal_id: str, new_score: float) -> List[int]:
        """
        Re-evaluate signal and cancel orders if score drops below 5.0.
        
        Returns:
            List of tickets to cancel
        """
        return self.order_tracker.check_pending_orders(time.time())
    
    def cancel_tracked_orders(self, tickets: List[int]):
        """Cancel orders and remove from tracking"""
        for ticket in tickets:
            if self.mt5_conn:
                self.mt5_conn.cancel(ticket)
            self.order_tracker.remove_order(ticket)
            LOG.info(f"[DISPATCHER] Cancelled order {ticket}")


