GLOBAL_SLIPPAGE_PROTECTION = False  # Flag for high-latency mode
BOT_SHUTDOWN_UNTIL = None  # Timestamp for 24h shutdown

class RiskGovernor:
    """Equity & Drawdown protection with ATR-dynamic sizing"""
    def __init__(self, starting_balance: float = None):
        self.starting_balance = starting_balance or CFG.get("account_balance", 100)
        self.daily_start_balance = self.starting_balance
        self.daily_start_time = datetime.now(timezone.utc)
        self.daily_start_date = self.daily_start_time.date()  # Track trading date
        self.daily_loss_threshold = 0.03  # 3% max daily loss
        self.shutdown_until = None

    def reset_daily_tracking(self, current_equity: float = None):
        """Reset the daily drawdown window for a new UTC day or stale restart state."""
        now = datetime.now(timezone.utc)
        equity = current_equity if current_equity is not None else self.daily_start_balance
        self.daily_start_balance = equity
        self.daily_start_time = now
        self.daily_start_date = now.date()
        self.shutdown_until = None
        LOG.info(f"[RISK] Daily reset: starting balance ${self.daily_start_balance:.2f}")
        return self.daily_start_balance
    
    def update_daily_stats(self, current_equity: float):
        """Update daily drawdown tracking - reset at UTC midnight"""
        now = datetime.now(timezone.utc)
        today = now.date()
        
        # Reset if new trading day (midnight UTC passed)
        if today > self.daily_start_date:
            self.reset_daily_tracking(current_equity)
            LOG.info(f"[RISK] Daily reset: new trading day, starting balance ${self.daily_start_balance:.2f}")
    
    def check_max_daily_drawdown(self, current_equity: float) -> bool:
        """Check if daily loss exceeds 3% threshold. Returns True if exceeded."""
        daily_loss = self.daily_start_balance - current_equity
        loss_pct = daily_loss / self.daily_start_balance if self.daily_start_balance > 0 else 0
        
        exceeded = loss_pct > self.daily_loss_threshold
        
        if exceeded:
            LOG.error(f"[RISK] MAX DAILY DRAWDOWN EXCEEDED: {loss_pct*100:.2f}% (>{self.daily_loss_threshold*100:.1f}%)")
            LOG.error(f"[RISK] Starting: ${self.daily_start_balance:.2f}, Current: ${current_equity:.2f}, Loss: ${daily_loss:.2f}")
            self.shutdown_until = datetime.now(timezone.utc) + timedelta(hours=24)
        
        return exceeded
    
    def should_shutdown(self) -> bool:
        """Check if bot should be shut down"""
        if self.shutdown_until is None:
            return False
        
        if datetime.now(timezone.utc) < self.shutdown_until:
            hours_remaining = (self.shutdown_until - datetime.now(timezone.utc)).total_seconds() / 3600
            LOG.warning(f"[RISK] BOT SHUTDOWN - {hours_remaining:.1f} hours remaining")
            return True
        
        # Shutdown period expired, reset
        self.shutdown_until = None
        return False
    
    def calculate_dynamic_lot_size(self, account_balance: float, atr: float, 
                                   risk_percent: float = 1.0, pip_value: float = 1.0,
                                   mtf_bias: dict = None, mtf_signal_type: str = None) -> float:
        """
        v17.0 Enhanced: Calculate dynamic lot size with MTF risk scaling.
        Base formula: LotSize = (Account_Balance * Risk_Percent) / (ATR * Pip_Value)
        
        MTF Risk Scaling:
        - 1.5x (Golden Swing): H1 + D1 + W1 + MN1 all aligned
        - 1.0x (Default): H1 matches D1
        - 0.5x (Conflicted): H1 conflicts with D1/W1
        
        Args:
            account_balance: Current account balance
            atr: Current ATR value
            risk_percent: Risk percentage (default 1%)
            pip_value: Pip value for the instrument
            mtf_bias: MTF alignment data from MacroTrendSentinel
            mtf_signal_type: 'INTRADAY' or 'SWING'
        
        Returns:
            Lot size (rounded to 0.01)
        """
        if atr <= 0 or account_balance <= 0:
            return CFG.get("min_lot", 0.01)
        
        # v17.0: Calculate base lot size
        risk_amount = account_balance * (risk_percent / 100.0)
        lot_size = risk_amount / (atr * pip_value)
        
        # v17.0: Apply MTF risk multiplier
        mtf_multiplier = 1.0
        if mtf_bias:
            alignment_level = mtf_bias.get('alignment_level', 1.0)
            golden_swing = mtf_bias.get('golden_swing', False)
            
            if golden_swing and alignment_level >= 1.5:
                mtf_multiplier = 1.5  # Golden Swing: max confidence
            elif alignment_level >= 1.25:
                mtf_multiplier = 1.0  # Good alignment
            elif alignment_level <= 1.0:
                # Check if conflicted
                d1_bias = mtf_bias.get('d1_bias', 'NEUTRAL')
                w1_bias = mtf_bias.get('w1_bias', 'NEUTRAL')
                if (d1_bias == 'BULLISH' and w1_bias == 'BEARISH') or \
                   (d1_bias == 'BEARISH' and w1_bias == 'BULLISH'):
                    mtf_multiplier = 0.5  # Conflicted: reduce risk
        
        lot_size *= mtf_multiplier
        
        # Clamp to valid range
        min_lot = CFG.get("min_lot", 0.01)
        max_lot = CFG.get("max_lot", 0.5)  # FIXED: was looking for "max_position"
        
        lot_size = round(max(min_lot, min(lot_size, max_lot)), 2)
        
        LOG.debug(f"[v17.0 RISK] Balance=${account_balance:.2f}, ATR={atr:.2f}, MTF={mtf_multiplier}x → Lot={lot_size:.2f}")
        
        return lot_size


class VolumeProfileAnalyzer:
    """Analyze volume profile for POC, VAH, VAL identification"""
    def __init__(self, bins: int = 24, va_percentile: float = 0.70):
        self.bins = bins
        self.va_percentile = va_percentile
    
    def calculate_volume_profile(self, df: pd.DataFrame, price_col: str = 'close', 
                                 vol_col: str = 'volume') -> Dict:
        """
        Calculate volume profile from OHLCV data.
        
        Returns:
            Dict with POC (Point of Control), VAH (Value Area High), VAL (Value Area Low)
        """
        if df is None or df.empty or len(df) < 10:
            return {'poc': None, 'vah': None, 'val': None, 'profile': {}}
        
        try:
            high = df['high'].values
            low = df['low'].values
            volume = df.get(vol_col, pd.Series([1]*len(df))).values
            
            # Create price bins
            price_min = low.min()
            price_max = high.max()
            bins_edges = np.linspace(price_min, price_max, self.bins + 1)
            bin_centers = (bins_edges[:-1] + bins_edges[1:]) / 2
            bin_volumes = np.zeros(self.bins)
            
            # Distribute volume into bins based on high-low range
            for i in range(len(df)):
                candle_high = high[i]
                candle_low = low[i]
                candle_vol = volume[i]
                
                # Find bins this candle touches
                touched_bins = np.where((bin_centers >= candle_low) & (bin_centers <= candle_high))[0]
                if len(touched_bins) > 0:
                    bin_volumes[touched_bins] += candle_vol / len(touched_bins)
            
            # Find POC (Point of Control) - highest volume
            poc_idx = np.argmax(bin_volumes)
            poc = bin_centers[poc_idx]
            
            # Find Value Area (70% of volume)
            sorted_idx = np.argsort(bin_volumes)[::-1]  # Sort descending
            cumsum_vol = 0
            total_vol = np.sum(bin_volumes)
            va_threshold = total_vol * self.va_percentile
            va_bins = []
            
            for idx in sorted_idx:
                if cumsum_vol >= va_threshold:
                    break
                va_bins.append(idx)
                cumsum_vol += bin_volumes[idx]
            
            va_prices = bin_centers[va_bins]
            vah = np.max(va_prices) if len(va_prices) > 0 else poc
            val = np.min(va_prices) if len(va_prices) > 0 else poc
            
            # Identify volume nodes
            profile = {
                'bins': dict(zip([f"{p:.2f}" for p in bin_centers], bin_volumes.tolist())),
                'poc': float(poc),
                'vah': float(vah),
                'val': float(val),
                'high_vol_nodes': [float(bin_centers[i]) for i in sorted_idx[:3]],  # Top 3 volume nodes
                'low_vol_nodes': [float(bin_centers[i]) for i in sorted_idx[-3:]]   # Bottom 3 volume nodes
            }
            
            return profile
            
        except Exception as e:
            LOG.debug(f"[VOL-PROFILE] Calculation error: {e}")
            return {'poc': None, 'vah': None, 'val': None, 'profile': {}}
    
    def is_low_volume_node(self, current_price: float, profile: Dict, tolerance_pct: float = 0.5) -> bool:
        """Check if current price is in a low volume area"""
        if not profile or 'low_vol_nodes' not in profile:
            return False
        
        for node_price in profile.get('low_vol_nodes', []):
            if node_price is None:
                continue
            pct_diff = abs(current_price - node_price) / node_price * 100
            if pct_diff < tolerance_pct:
                return True
        
        return False
    
    def is_high_volume_node(self, current_price: float, profile: Dict, tolerance_pct: float = 0.5) -> bool:
        """Check if current price is at POC or other high volume area"""
        if not profile or profile.get('poc') is None:
            return False
        
        poc = profile.get('poc')
        pct_diff = abs(current_price - poc) / poc * 100
        
        return pct_diff < tolerance_pct


class HealthMonitor:
    """Async health monitoring for latency and infrastructure health"""
    def __init__(self, mt5_conn=None):
        self.mt5_conn = mt5_conn
        self.last_ping_time = time.time()
        self.latencies = deque(maxlen=60)  # Last 60 pings
        self.latency_threshold = 150  # ms
        self.ping_interval = 60  # seconds
    
    async def monitor_health(self):
        """Async loop to monitor MT5 connection health every 60 seconds"""
        global GLOBAL_SLIPPAGE_PROTECTION
        
        while True:
            try:
                await asyncio.sleep(self.ping_interval)
                
                if not self.mt5_conn or not self.mt5_conn.ensure_connection():
                    LOG.warning("[HEALTH] MT5 connection check failed")
                    continue
                
                # Ping MT5 and measure latency
                start = time.time()
                try:
                    tick = self.mt5_conn.get_fresh_tick()
                    latency_ms = (time.time() - start) * 1000
                    self.latencies.append(latency_ms)
                    
                    avg_latency = np.mean(list(self.latencies)) if self.latencies else 0
                    
                    if latency_ms > self.latency_threshold:
                        LOG.warning(f"[HEALTH] High latency detected: {latency_ms:.1f}ms (avg: {avg_latency:.1f}ms)")
                        GLOBAL_SLIPPAGE_PROTECTION = True
                    else:
                        GLOBAL_SLIPPAGE_PROTECTION = False
                    
                    if avg_latency > 100:
                        LOG.debug(f"[HEALTH] Elevated latency: {avg_latency:.1f}ms, Slippage protection: {GLOBAL_SLIPPAGE_PROTECTION}")
                
                except Exception as e:
                    LOG.warning(f"[HEALTH] Latency check failed: {e}")
                    GLOBAL_SLIPPAGE_PROTECTION = True
            
            except asyncio.CancelledError:
                break
            except Exception as e:
                LOG.error(f"[HEALTH] Monitor error: {e}")
                await asyncio.sleep(10)  # Brief pause before retry


