class PressureTracker:
    """
    CPI-2: Dynamic Candle Pressure Analysis
    Measures intrabar momentum and adapts to volatility
    
    Formula: Pressure = ((Close - Low) - (High - Close)) / (High - Low)
    - Range: [-1, +1], where +1 = extremely bullish, -1 = extremely bearish
    - Uses 20-period rolling statistics for dynamic thresholds
    - Adapts filter sensitivity to ATR (current volatility)
    """
    def __init__(self, period=20):
        self.period = period
        self.pressures = deque(maxlen=period)
        self.high_prices = deque(maxlen=period)
        self.low_prices = deque(maxlen=period)
        self.close_prices = deque(maxlen=period)
        self.atr_values = deque(maxlen=period)
        self.last_pressure = 0.0
        self.mean_pressure = 0.0
        self.std_pressure = 0.0
        LOG.info("[v16.0] PressureTracker initialized (CPI-2 candle pressure analysis)")
    
    def update(self, high: float, low: float, close: float, atr: float):
        """
        Update pressure tracker with latest OHLC and ATR data
        
        Args:
            high: Bar high
            low: Bar low  
            close: Bar close
            atr: Average True Range (volatility measure)
        """
        if high <= low or high == low:
            # Avoid division by zero / invalid data
            pressure = 0.0
        else:
            # Calculate pressure = ((Close - Low) - (High - Close)) / (High - Low)
            # Simplified: (2*Close - High - Low) / (High - Low)
            numerator = (2 * close - high - low)
            denominator = (high - low)
            pressure = numerator / denominator if denominator != 0 else 0.0
        
        self.pressures.append(pressure)
        self.high_prices.append(high)
        self.low_prices.append(low)
        self.close_prices.append(close)
        self.atr_values.append(atr)
        self.last_pressure = pressure
        
        # Update rolling statistics
        if len(self.pressures) > 0:
            self.mean_pressure = np.mean(list(self.pressures))
            self.std_pressure = np.std(list(self.pressures)) if len(self.pressures) > 1 else 0.05
            self.std_pressure = max(self.std_pressure, 0.05)
    
    def get_dynamic_threshold(self, atr: float, base_price: float = 5000.0) -> tuple:
        """
        Calculate dynamic pressure thresholds adapted to current volatility (ATR)
        
        Returns:
            (upper_threshold, lower_threshold)
            - Upper: threshold for rejecting SELL signals (too much upward pressure)
            - Lower: threshold for rejecting BUY signals (too much downward pressure)
        """
        # Base thresholds (2 standard deviations)
        upper = self.mean_pressure + 2.0 * self.std_pressure
        lower = self.mean_pressure - 2.0 * self.std_pressure
        
        # Adapt thresholds to ATR volatility
        # Higher ATR = wider thresholds = less restrictive
        volatility_factor = (atr / base_price) * 100  # Convert to percentage
        adjustment = volatility_factor * 0.5  # Moderate sensitivity
        
        upper += adjustment
        lower -= adjustment
        
        # Clamp to reasonable ranges, but keep enough headroom for early pressure signals.
        upper = min(upper, 0.99)
        lower = max(lower, -0.99)
        
        return upper, lower
    
    def is_buy_valid(self, atr: float, base_price: float = 5000.0) -> bool:
        """
        Check if current pressure supports BUY signal
        
        Rejects BUY if: Pressure < (Mean - 2*StdDev) [too much downward momentum]
        """
        if len(self.pressures) < 3:
            LOG.debug(f"[PRESSURE] BUY bypassed: insufficient sample size ({len(self.pressures)})")
            return True
        _, lower = self.get_dynamic_threshold(atr, base_price)
        
        is_valid = self.last_pressure >= lower
        
        if not is_valid:
            LOG.debug(f"[PRESSURE] BUY REJECTED: Pressure={self.last_pressure:.3f} < Lower={lower:.3f} (bearish momentum)")
        
        return is_valid
    
    def is_sell_valid(self, atr: float, base_price: float = 5000.0) -> bool:
        """
        Check if current pressure supports SELL signal
        
        Rejects SELL if: Pressure > (Mean + 2*StdDev) [too much upward momentum]
        """
        if len(self.pressures) < 3:
            LOG.debug(f"[PRESSURE] SELL bypassed: insufficient sample size ({len(self.pressures)})")
            return True
        upper, _ = self.get_dynamic_threshold(atr, base_price)
        
        is_valid = self.last_pressure <= upper
        
        if not is_valid:
            LOG.debug(f"[PRESSURE] SELL REJECTED: Pressure={self.last_pressure:.3f} > Upper={upper:.3f} (bullish momentum)")
        
        return is_valid
    
    def get_pressure_stats(self) -> dict:
        """Return current pressure analysis snapshot"""
        return {
            'current': self.last_pressure,
            'mean': self.mean_pressure,
            'std': self.std_pressure,
            'samples': len(self.pressures)
        }

