# v18.1 LAYER 1: Z-SCORE MEAN REVERSION (SYMMETRICAL)
# ============================================================
class ZScoreMeanReversionV18:
    # STAGE-9: was shadowed by the later ZScoreMeanReversion definition (name bound to the last def).
    # Kept verbatim as the ZScoreMeanReversionV18 base class; NOT deleted.
    """
    Symmetrical Z-score based mean reversion detection.
    Formula: Z = (Close - VWAP) / RollingStdDev(Close, 20)
    CASE SELL: Z > +2.5 AND Pressure Bearish -> High-Prob Reversion SELL
    CASE BUY:  Z < -2.5 AND Pressure Bullish -> High-Prob Reversion BUY
    """
    def __init__(self):
        self.z_history = deque(maxlen=100)
        self.vwap_history = deque(maxlen=100)
        
    def calculate_zscore(self, close_prices, volumes, std_dev_window=20):
        """Calculate Z-score: (Price - VWAP) / StdDev"""
        if len(close_prices) < std_dev_window:
            return 0.0
        
        closes = np.array(close_prices[-std_dev_window:])
        vols = np.array(volumes[-std_dev_window:])
        
        # Calculate VWAP
        vwap = np.sum(closes * vols) / np.sum(vols) if np.sum(vols) > 0 else closes[-1]
        
        # Calculate rolling std dev
        std_dev = np.std(closes)
        if std_dev == 0:
            return 0.0
        
        # Z-score
        z_score = (closes[-1] - vwap) / std_dev
        self.z_history.append(z_score)
        self.vwap_history.append(vwap)
        
        return z_score
    
    def detect_reversion_signal(self, z_score, pressure_score, threshold=2.5):
        """
        SYMMETRICAL LOGIC:
        - BUY: Z < -threshold AND pressure >= 0 (Bullish pressure)
        - SELL: Z > +threshold AND pressure < 0 (Bearish pressure)
        """
        if abs(z_score) < threshold:
            return None, 0.0
        
        if z_score > threshold and pressure_score < 0:
            return "SELL", 5.0  # High-prob reversion SELL reward
        elif z_score < -threshold and pressure_score >= 0:
            return "BUY", 5.0  # High-prob reversion BUY reward
        
        return None, 0.0

