# v18.1 LAYER 6: EQUITY CURVE MANAGER (RISK PRESERVATION)
# ============================================================
class EquityCurveManager:
    """
    Reduce risk if Equity < 20-period Moving Average.
    Preserve capital during drawdowns.
    """
    def __init__(self, lookback=20):
        self.lookback = lookback
        self.equity_history = deque(maxlen=lookback)
        
    def update_equity(self, equity):
        """Track equity over time"""
        self.equity_history.append(equity)
    
    def calculate_equity_ma(self):
        """Calculate 20-period equity MA"""
        if len(self.equity_history) < self.lookback:
            return None
        
        return np.mean(list(self.equity_history))
    
    def get_risk_adjustment(self, current_equity):
        """
        Return risk multiplier based on equity vs MA.
        < MA: Reduce risk (0.5x)
        >= MA: Normal risk (1.0x)
        """
        equity_ma = self.calculate_equity_ma()
        
        if equity_ma is None:
            return 1.0  # No adjustment yet
        
        if current_equity < equity_ma:
            LOG.warning(f"[v18.1] Equity ({current_equity:.2f}) < MA ({equity_ma:.2f}). Reducing risk to 0.5x")
            return 0.5
        
        return 1.0

