class ZScoreMeanReversion(ZScoreMeanReversionV18):
    # STAGE-9: inherits V18 calculate_zscore()/detect_reversion_signal() (kept, not deleted)
    """
    v19.0: Z-Score Mean Reversion with Symmetric Logic
    
    Buy Trigger: Z < -2.5 (Price below VWAP by >2.5 std dev) + Candle Rejection
    Sell Trigger: Z > +2.5 (Price above VWAP by >2.5 std dev) + Candle Rejection
    
    Symmetry ensures equal treatment of both sides.
    """
    def __init__(self, vwap_period=20, z_threshold=2.5):
        self.vwap_period = vwap_period
        self.z_threshold = z_threshold
        self.name = "ZScoreMeanReversion"
        
    def calculate_z_score(self, df: pd.DataFrame) -> Tuple[float, float, float]:
        """
        Calculate Z-Score: (Price - VWAP) / StdDev(Price, 20)
        Returns: (z_score, vwap, rolling_std)
        """
        if df is None or len(df) < self.vwap_period + 5:
            return 0.0, 0.0, 0.0
        
        try:
            close = df['close'].values
            volume = df['volume'].values if 'volume' in df.columns else np.ones_like(close)
            
            # Calculate VWAP
            vwap = np.cumsum(close * volume) / np.cumsum(volume)
            vwap_value = vwap[-1]
            
            # Calculate rolling std dev
            returns = pd.Series(close).pct_change()
            rolling_std = returns.rolling(window=self.vwap_period).std().iloc[-1]
            
            if rolling_std == 0 or np.isnan(rolling_std):
                rolling_std = 0.01
            
            # Calculate Z-score
            z_score = (close[-1] - vwap_value) / (rolling_std * close[-1]) if rolling_std > 0 else 0
            
            return float(z_score), float(vwap_value), float(rolling_std)
        
        except Exception as e:
            LOG.debug(f"[ZScore] Calculation failed: {e}")
            return 0.0, 0.0, 0.0
    
    def is_candle_rejection(self, df: pd.DataFrame, direction: str) -> bool:
        """
        Detect candle rejection:
        - BUY: Long lower wick, close above 50% of candle
        - SELL: Long upper wick, close below 50% of candle
        """
        if df is None or len(df) < 2:
            return False
        
        try:
            candle = df.iloc[-1]
            body = abs(candle['close'] - candle['open'])
            wick_lower = candle['open'] if candle['close'] > candle['open'] else candle['close']
            wick_lower = wick_lower - candle['low']
            wick_upper = candle['high'] - (candle['close'] if candle['close'] > candle['open'] else candle['open'])
            
            if direction == 'BUY':
                # Long lower wick for rejection
                return wick_lower > body * 1.5 if body > 0 else False
            elif direction == 'SELL':
                # Long upper wick for rejection
                return wick_upper > body * 1.5 if body > 0 else False
        
        except Exception:
            pass
        
        return False
    
    def analyze(self, df: pd.DataFrame) -> Optional[dict]:
        """
        Analyze and return signal if conditions met.
        Returns: {'direction': 'BUY'/'SELL', 'z_score': float, 'confidence': float} or None
        """
        z_score, vwap, std_dev = self.calculate_z_score(df)
        
        # Buy signal: Z < -2.5 AND candle rejection
        if z_score < -self.z_threshold and self.is_candle_rejection(df, 'BUY'):
            confidence = min(1.0, abs(z_score) / (self.z_threshold * 2))
            return {
                'direction': 'BUY',
                'z_score': z_score,
                'confidence': confidence,
                'vwap': vwap,
                'signal_type': 'ZScore_MeanReversion'
            }
        
        # Sell signal: Z > +2.5 AND candle rejection
        elif z_score > self.z_threshold and self.is_candle_rejection(df, 'SELL'):
            confidence = min(1.0, abs(z_score) / (self.z_threshold * 2))
            return {
                'direction': 'SELL',
                'z_score': z_score,
                'confidence': confidence,
                'vwap': vwap,
                'signal_type': 'ZScore_MeanReversion'
            }
        
        return None

class LiquiditySentinel(LiquiditySentinelV18):
    # STAGE-9: inherits V18 tap_fvg_reward() and detect_fvgs(high,low,close,atr) (kept, not deleted)
    """
    v19.0: Fair Value Gap (FVG) Detection & Liquidity Scoring
    
    FVG Definition: 3-candle imbalance where:
    - Bullish FVG: Low[n] > High[n+2] (gap below price)
    - Bearish FVG: High[n] < Low[n+2] (gap above price)
    
    Scoring: +4.0 multiplier if signal aligns with unfilled FVG
    """
    def __init__(self, lookback=50):
        self.lookback = lookback
        self.name = "LiquiditySentinel"
        
    def detect_fvgs_df(self, df: pd.DataFrame) -> List[dict]:
        """
        Detect Fair Value Gaps in the last 50 candles.
        Returns: [{'type': 'BULLISH'/'BEARISH', 'level': float, 'candle_idx': int}, ...]
        """
        if df is None or len(df) < 3:
            return []
        
        fvgs = []
        df_recent = df.tail(self.lookback)
        
        try:
            for i in range(len(df_recent) - 2):
                high_i = df_recent['high'].iloc[i]
                low_i = df_recent['low'].iloc[i]
                high_i2 = df_recent['high'].iloc[i+2]
                low_i2 = df_recent['low'].iloc[i+2]
                
                # Bullish FVG: Low[n] > High[n+2]
                if low_i > high_i2:
                    fvgs.append({
                        'type': 'BULLISH',
                        'level': (low_i + high_i2) / 2,
                        'top': low_i,
                        'bottom': high_i2,
                        'filled': False
                    })
                
                # Bearish FVG: High[n] < Low[n+2]
                elif high_i < low_i2:
                    fvgs.append({
                        'type': 'BEARISH',
                        'level': (high_i + low_i2) / 2,
                        'top': low_i2,
                        'bottom': high_i,
                        'filled': False
                    })
        
        except Exception as e:
            LOG.debug(f"[FVG] Detection failed: {e}")
        
        return fvgs
    
    def score_signal(self, df: pd.DataFrame, signal_direction: str, signal_price: float) -> float:
        """
        Calculate FVG alignment multiplier.
        Returns: 1.0 (no alignment) or 4.0 (strong FVG alignment)
        """
        fvgs = self.detect_fvgs_df(df)
        
        for fvg in fvgs:
            # Buy signal aligns with bullish FVG (unfilled gap below)
            if signal_direction == 'BUY' and fvg['type'] == 'BULLISH':
                if fvg['bottom'] < signal_price < fvg['top']:
                    return 4.0
            
            # Sell signal aligns with bearish FVG (unfilled gap above)
            elif signal_direction == 'SELL' and fvg['type'] == 'BEARISH':
                if fvg['bottom'] < signal_price < fvg['top']:
                    return 4.0
        
        return 1.0

class RiskEngine:
    """
    v19.0: Dynamic Risk & Lot Sizing Engine
    
    Features:
    - ATR-based stop loss (2x ATR)
    - Tiered lot sizing based on account balance
    - 0.01 minimum lot constraint
    - Dynamic risk percentage (0.1% recovery mode, 1% normal)
    """
    def __init__(self):
        self.name = "RiskEngine"
        self.min_lot = CFG.get("min_lot", 0.01)
        self.max_lot = CFG.get("max_lot", 0.5)
        self.leverage = CFG.get("leverage", 200)
        
    def calculate_sl_from_atr(self, price: float, atr: float, direction: str, multiplier: float = 2.0) -> float:
        """
        Calculate stop loss based on ATR.
        - BUY: SL = Entry - (ATR * multiplier)
        - SELL: SL = Entry + (ATR * multiplier)
        """
        if direction == 'BUY':
            return price - (atr * multiplier)
        else:  # SELL
            return price + (atr * multiplier)
    
    def calculate_lots(self, balance: float, entry: float, sl: float, 
                      risk_pct: float = 1.0, atr: float = 0.0) -> float:
        """
        Calculate lot size with tiered scaling and constraints.
        
        Args:
            balance: Current account balance
            entry: Entry price
            sl: Stop loss price
            risk_pct: Risk percentage (0.1 in recovery, 1.0 normal)
            atr: Average True Range for context
        
        Returns:
            Lot size (0.01 - 0.5)
        """
        try:
            # Minimum balance check
            if balance < 1.0:
                return self.min_lot
            
            # Calculate SL distance in dollars
            sl_distance = abs(entry - sl)
            if sl_distance <= 0:
                return self.min_lot
            
            # For XAUUSD: 1 lot = 100 oz
            # Position value = lots * 100 oz * entry price
            # Margin = Position Value / Leverage
            # Risk = lots * 100 * entry * (entry - sl) / entry
            
            # Risk amount in dollars
            risk_amount = balance * (risk_pct / 100.0)
            
            # Calculate raw lots: risk_amount / (sl_distance_pips * pip_value)
            # For XAUUSD: pip_value ≈ 0.01 * 100 (contract size)
            raw_lots = risk_amount / (sl_distance * EXNESS['contract_size'] / 100.0)
            
            # Apply tiered scaling
            if balance < 100:
                lots = min(raw_lots, self.min_lot)  # Small balance: use minimum
            elif balance < 1000:
                lots = min(raw_lots, 0.05)  # Micro-account: limit to 0.05
            elif balance < 10000:
                lots = min(raw_lots, 0.1)  # Small account: limit to 0.1
            else:
                lots = min(raw_lots, self.max_lot)  # Large account: full range
            
            # Apply constraints
            lots = max(self.min_lot, min(lots, self.max_lot))
            
            # Round to nearest 0.01
            lots = round(lots, 2)
            
            return lots
        
        except Exception as e:
            LOG.warning(f"[RiskEngine] Lot calculation failed: {e}")
            return self.min_lot

# ============================================================
# v19.0: EQUITY CURVE SHIELD - HEALTH CHECK & RECOVERY
# ============================================================

class EquityCurveShield:
    """
    Monitors account equity health using rolling 20-snapshot MA.
    If current balance < MA, activates recovery mode (0.1% risk).
    """
    def __init__(self):
        self.name = "EquityCurveShield"
        self.equity_snapshots = []  # Store last 20 balance snapshots
        self.max_snapshots = 20
        self.recovery_mode = False
        
    def add_snapshot(self, balance: float) -> None:
        """Add a balance snapshot to the rolling window."""
        self.equity_snapshots.append(balance)
        if len(self.equity_snapshots) > self.max_snapshots:
            self.equity_snapshots.pop(0)
    
    def get_equity_ma(self) -> float:
        """Get 20-snapshot moving average of balance."""
        if not self.equity_snapshots:
            return 0.0
        return sum(self.equity_snapshots) / len(self.equity_snapshots)
    
    def check_equity_health(self, current_balance: float) -> dict:
        """
        Check if equity is healthy. If not, trigger recovery mode.
        
        Returns:
            {
                'healthy': bool,
                'recovery_mode': bool,
                'current': float,
                'ma_20': float,
                'drawdown_pct': float,
                'min_risk_pct': float
            }
        """
        # Add current balance to snapshots
        self.add_snapshot(current_balance)
        
        # Calculate 20-period MA
        ma_20 = self.get_equity_ma()
        
        # Determine health status
        if ma_20 == 0:
            return {
                'healthy': True,
                'recovery_mode': False,
                'current': current_balance,
                'ma_20': 0.0,
                'drawdown_pct': 0.0,
                'min_risk_pct': 1.0  # Normal risk
            }
        
        # Check if current < MA (equity declining)
        is_healthy = current_balance >= ma_20
        drawdown_pct = ((ma_20 - current_balance) / ma_20 * 100) if is_healthy == False else 0.0
        
        # Recovery mode: 0.1% risk if below MA, normal 1.0% if above
        min_risk_pct = 0.1 if not is_healthy else 1.0
        self.recovery_mode = not is_healthy
        
        return {
            'healthy': is_healthy,
            'recovery_mode': not is_healthy,
            'current': current_balance,
            'ma_20': ma_20,
            'drawdown_pct': drawdown_pct,
            'min_risk_pct': min_risk_pct
        }

