# SENTINEL v17.0: SWING-SENTINEL - MACRO TREND & STRATEGY ISOLATION
# ============================================================

# Magic Numbers for Strategy Isolation
MAGIC_INTRADAY = 111222
MAGIC_SWING = 999888

class MacroTrendSentinel:
    """
    v17.0: Multi-Timeframe Trend Analysis
    
    Detects trend alignment across Daily, Weekly, and Monthly charts.
    Provides multipliers for signal strength:
    - 1.0x: Aligned with D1 only
    - 1.25x: Aligned with D1 + W1
    - 1.5x: Aligned with D1 + W1 + MN1 (Golden Swing)
    """
    def __init__(self):
        self.ema_period = 200
        self.hh_lookback = 20  # Bars for Higher High detection
        self.ll_lookback = 20  # Bars for Lower Low detection
        self.alignment_cache = {}
        LOG.info("[v17.0] MacroTrendSentinel initialized")
    
    def detect_market_structure(self, df: pd.DataFrame) -> dict:
        """
        Detect Higher Highs/Lower Lows for market structure
        Returns: {trend: 'UPTREND'/'DOWNTREND'/'RANGING', hh_level, ll_level}
        """
        if df is None or df.empty or len(df) < self.hh_lookback + 5:
            return {'trend': 'UNKNOWN', 'hh_level': 0, 'll_level': 0}
        
        try:
            highs = df['high'].values
            lows = df['low'].values
            
            # Get recent high and low
            recent_high = highs[-1]
            recent_low = lows[-1]
            
            # Get previous pivot levels
            prev_highs = highs[-(self.hh_lookback+5):-1]
            prev_lows = lows[-(self.hh_lookback+5):-1]
            
            recent_hh = recent_high > prev_highs.max()
            recent_ll = recent_low < prev_lows.min()
            
            if recent_hh and not recent_ll:
                return {'trend': 'UPTREND', 'hh_level': recent_high, 'll_level': prev_lows.min()}
            elif recent_ll and not recent_hh:
                return {'trend': 'DOWNTREND', 'hh_level': prev_highs.max(), 'll_level': recent_low}
            else:
                return {'trend': 'RANGING', 'hh_level': prev_highs.max(), 'll_level': prev_lows.min()}
        
        except Exception as e:
            LOG.debug(f"[MacroTrend] Market structure detection failed: {e}")
            return {'trend': 'UNKNOWN', 'hh_level': 0, 'll_level': 0}
    
    def get_ema_bias(self, df: pd.DataFrame) -> str:
        """
        Determine bias (BULLISH/BEARISH/NEUTRAL) based on EMA200
        Returns: 'BULLISH', 'BEARISH', or 'NEUTRAL'
        """
        if df is None or df.empty or len(df) < self.ema_period:
            return 'NEUTRAL'
        
        try:
            df_copy = df.copy()
            df_copy['ema200'] = df_copy['close'].ewm(span=self.ema_period, adjust=False).mean()
            
            current_close = df_copy['close'].iloc[-1]
            ema200 = df_copy['ema200'].iloc[-1]
            
            if current_close > ema200:
                return 'BULLISH'
            elif current_close < ema200:
                return 'BEARISH'
            else:
                return 'NEUTRAL'
        
        except Exception as e:
            LOG.debug(f"[MacroTrend] EMA bias calculation failed: {e}")
            return 'NEUTRAL'
    
    def get_mtf_bias(self, d1_df: pd.DataFrame, w1_df: pd.DataFrame, mn1_df: pd.DataFrame) -> dict:
        """
        Get multi-timeframe bias and alignment multiplier
        
        Returns:
        {
            'alignment_level': 1.0 | 1.25 | 1.5,
            'alignment_label': 'D1_Only' | 'D1_W1' | 'Golden_Swing',
            'd1_bias': 'BULLISH'/'BEARISH'/'NEUTRAL',
            'w1_bias': 'BULLISH'/'BEARISH'/'NEUTRAL',
            'mn1_bias': 'BULLISH'/'BEARISH'/'NEUTRAL',
            'd1_structure': {...},
            'w1_structure': {...}
        }
        """
        try:
            d1_bias = self.get_ema_bias(d1_df)
            w1_bias = self.get_ema_bias(w1_df)
            mn1_bias = self.get_ema_bias(mn1_df) if mn1_df is not None else 'NEUTRAL'
            
            d1_structure = self.detect_market_structure(d1_df)
            w1_structure = self.detect_market_structure(w1_df)
            
            # Determine alignment
            alignment_level = 1.0
            alignment_label = 'D1_Only'
            
            if d1_bias != 'NEUTRAL' and w1_bias != 'NEUTRAL' and d1_bias == w1_bias:
                alignment_level = 1.25
                alignment_label = 'D1_W1'
                
                if mn1_bias != 'NEUTRAL' and mn1_bias == d1_bias:
                    alignment_level = 1.5
                    alignment_label = 'Golden_Swing'
            
            result = {
                'alignment_level': alignment_level,
                'alignment_label': alignment_label,
                'd1_bias': d1_bias,
                'w1_bias': w1_bias,
                'mn1_bias': mn1_bias,
                'd1_structure': d1_structure,
                'w1_structure': w1_structure,
                'golden_swing': alignment_level == 1.5
            }
            
            LOG.info(f"[MacroTrend] MTF Alignment: {alignment_label} ({alignment_level}x) - D1:{d1_bias} W1:{w1_bias} MN1:{mn1_bias}")
            return result
        
        except Exception as e:
            LOG.error(f"[MacroTrend] MTF bias calculation failed: {e}")
            return {
                'alignment_level': 1.0,
                'alignment_label': 'D1_Only',
                'd1_bias': 'NEUTRAL',
                'w1_bias': 'NEUTRAL',
                'mn1_bias': 'NEUTRAL',
                'd1_structure': {'trend': 'UNKNOWN'},
                'w1_structure': {'trend': 'UNKNOWN'},
                'golden_swing': False
            }


class ExecutionReconciler:
    """
    v17.0: Reconcile Strategy Intent with CPI-2 Pressure
    
    Adjusts execution behavior based on pressure alignment:
    - Aligned pressure: +3.0 score bonus
    - Conflicting pressure: -4.0 score penalty, downgrade to LIMIT
    """
    def __init__(self, pressure_tracker):
        self.pressure_tracker = pressure_tracker
        self.aligned_bonus = 3.0
        self.conflict_penalty = -4.0
        LOG.info("[v17.0] ExecutionReconciler initialized")
    
    def reconcile(self, signal_data: dict, strategy_intent: str = 'market') -> dict:
        """
        Reconcile signal with pressure and strategy intent
        
        Args:
            signal_data: {dir, score, entry, sl, tp, ...}
            strategy_intent: 'market' or 'limit'
        
        Returns:
            {
                'score_adjustment': float,
                'final_score': float,
                'execution_type': 'MARKET' or 'LIMIT',
                'limit_price': float,
                'pressure_aligned': bool,
                'rationale': str
            }
        """
        try:
            direction = signal_data.get('dir', 'BUY')
            base_score = signal_data.get('score', 10)
            pressure_aligned = False
            score_adjustment = 0
            execution_type = strategy_intent.upper()
            limit_price = signal_data.get('entry', 0)
            rationale = ""
            
            # Check pressure alignment
            if direction == 'BUY':
                pressure_aligned = self.pressure_tracker.is_buy_valid(signal_data.get('atr', 15))
            else:
                pressure_aligned = self.pressure_tracker.is_sell_valid(signal_data.get('atr', 15))
            
            # Apply scoring adjustments
            if pressure_aligned:
                score_adjustment = self.aligned_bonus
                rationale = "Pressure aligned with signal direction (+3.0)"
            else:
                score_adjustment = self.conflict_penalty
                rationale = "Pressure conflicts with signal direction (-4.0)"
                
                # Downgrade to LIMIT if market order and pressure conflicting
                if strategy_intent.lower() == 'market':
                    execution_type = 'LIMIT'
                    # Set limit at order block or 50% FVG retracement
                    if direction == 'BUY':
                        limit_price = signal_data.get('sl', signal_data.get('entry', 0)) * 1.02
                    else:
                        limit_price = signal_data.get('tp', signal_data.get('entry', 0)) * 0.98
                    rationale += " → Downgraded to LIMIT order"
            
            final_score = base_score + score_adjustment
            
            return {
                'score_adjustment': score_adjustment,
                'final_score': final_score,
                'execution_type': execution_type,
                'limit_price': limit_price,
                'pressure_aligned': pressure_aligned,
                'rationale': rationale
            }
        
        except Exception as e:
            LOG.error(f"[ExecutionReconciler] Reconciliation failed: {e}")
            return {
                'score_adjustment': 0,
                'final_score': signal_data.get('score', 10),
                'execution_type': strategy_intent.upper(),
                'limit_price': signal_data.get('entry', 0),
                'pressure_aligned': False,
                'rationale': f"Error: {str(e)[:50]}"
            }


class StudyPackageGenerator:
    """
    v17.0: Generate 3-Chart Study Package for Manual Confirmation
    
    Creates a Telegram media group with:
    1. M15 Execution Chart - Entry/SL/TP with order type indicator
    2. D1/W1 Macro Context - EMA200 and long-term trends
    3. Momentum Panel - RSI, ATR, and Pressure Gauge
    """
    def __init__(self):
        self.charter_enabled = False
        try:
            import plotly.graph_objects as go
            self.go = go
            self.charter_enabled = True
            LOG.info("[v17.0] StudyPackageGenerator initialized with Plotly")
        except ImportError:
            LOG.warning("[v17.0] StudyPackageGenerator: Plotly not available - falling back to text")
            self.go = None
    
    def generate_study_package(self, signal_data: dict, dfs: dict, mtf_bias: dict) -> dict:
        """
        v19.0: Generate 3 professional PNG charts
        
        Chart 1: M15 Execution (Z-Score + VWAP)
        Chart 2: H1 Institutional Map (FVG Boxes)
        Chart 3: Health Dashboard (Equity Curve vs MA + Sentiment Gauge)
        
        Returns:
        {
            'chart_a': bytes (PNG),
            'chart_b': bytes (PNG),
            'chart_c': bytes (PNG),
            'captions': [str, str, str]
        }
        """
        try:
            # Get M15 and H1 data
            m15_df = dfs.get('M15')
            h1_df = dfs.get('H1')
            
            charts = {}
            
            # Chart 1: M15 Execution with Z-Score + VWAP
            if m15_df is not None and not m15_df.empty:
                charts['chart_a'] = self._generate_m15_zscore_chart(m15_df, signal_data)
            else:
                charts['chart_a'] = None
            
            # Chart 2: H1 Institutional Map with FVG Boxes
            if h1_df is not None and not h1_df.empty:
                charts['chart_b'] = self._generate_h1_fvg_chart(h1_df)
            else:
                charts['chart_b'] = None
            
            # Chart 3: Health Dashboard
            charts['chart_c'] = self._generate_health_dashboard(signal_data, mtf_bias)
            
            captions = [
                f"📊 M15 Execution: Z-Score + VWAP | {signal_data.get('dir', 'N/A')} @ {signal_data.get('entry', 0):.2f}",
                f"📈 H1 Institutional: FVG Liquidity Zones",
                f"📉 Health Dashboard: Equity MA + Sentiment Gauge"
            ]
            
            return {'charts': charts, 'captions': captions}
        
        except Exception as e:
            LOG.error(f"[v19.0 StudyPackage] Generation failed: {e}")
            import traceback
            LOG.debug(traceback.format_exc())
            return {'charts': {'chart_a': None, 'chart_b': None, 'chart_c': None}, 'captions': []}
    
    def _generate_m15_zscore_chart(self, m15_df: pd.DataFrame, signal_data: dict) -> bytes:
        """
        Chart 1: M15 Execution with Z-Score calculation and VWAP
        """
        if not self.charter_enabled or m15_df is None or m15_df.empty:
            return None
        
        try:
            if not PLOTLY_OK:
                LOG.warning("[Chart1] Plotly not available")
                return None
            
            import plotly.graph_objects as go
            from plotly.subplots import make_subplots
            
            # Create subplots: OHLC + Z-Score
            fig = make_subplots(
                rows=2, cols=1,
                row_heights=[0.7, 0.3],
                shared_xaxes=True,
                specs=[[{"secondary_y": True}], [{"secondary_y": False}]]
            )
            
            # OHLC Candlesticks
            fig.add_trace(
                go.Candlestick(
                    x=m15_df.index,
                    open=m15_df['open'],
                    high=m15_df['high'],
                    low=m15_df['low'],
                    close=m15_df['close'],
                    name='M15 Price'
                ),
                row=1, col=1, secondary_y=False
            )
            
            # VWAP (if available)
            if 'vwap' in m15_df.columns:
                fig.add_trace(
                    go.Scatter(
                        x=m15_df.index,
                        y=m15_df['vwap'],
                        name='VWAP',
                        line=dict(color='purple', width=2)
                    ),
                    row=1, col=1, secondary_y=False
                )
            
            # ATR Bands
            if 'atr' in m15_df.columns:
                atr_upper = m15_df['close'] + m15_df['atr']
                atr_lower = m15_df['close'] - m15_df['atr']
                fig.add_trace(
                    go.Scatter(
                        x=m15_df.index, y=atr_upper,
                        fill=None, mode='lines',
                        name='ATR Upper', line=dict(width=0),
                        showlegend=False
                    ),
                    row=1, col=1, secondary_y=False
                )
                fig.add_trace(
                    go.Scatter(
                        x=m15_df.index, y=atr_lower,
                        fill='tonexty', mode='lines',
                        name='ATR Band', line=dict(width=0),
                        fillcolor='rgba(0,100,200,0.2)'
                    ),
                    row=1, col=1, secondary_y=False
                )
            
            # Z-Score (Row 2)
            if 'vwap' in m15_df.columns:
                std_20 = m15_df['close'].rolling(20).std()
                z_score = (m15_df['close'] - m15_df['vwap']) / std_20
                
                fig.add_trace(
                    go.Scatter(
                        x=m15_df.index,
                        y=z_score,
                        name='Z-Score',
                        line=dict(color='blue', width=2)
                    ),
                    row=2, col=1, secondary_y=False
                )
                
                # Z-Score thresholds
                fig.add_hline(y=2.5, line_dash="dash", line_color="red", row=2, col=1)
                fig.add_hline(y=-2.5, line_dash="dash", line_color="green", row=2, col=1)
                fig.add_hline(y=0, line_dash="solid", line_color="gray", row=2, col=1)
            
            # Entry/SL/TP markers
            if signal_data.get('entry'):
                fig.add_hline(y=signal_data.get('entry'), line_dash="solid", line_color="orange", 
                             annotation_text=f"Entry: {signal_data.get('entry'):.2f}", row=1, col=1)
            if signal_data.get('sl'):
                fig.add_hline(y=signal_data.get('sl'), line_dash="solid", line_color="red",
                             annotation_text=f"SL: {signal_data.get('sl'):.2f}", row=1, col=1)
            if signal_data.get('tp'):
                fig.add_hline(y=signal_data.get('tp'), line_dash="solid", line_color="green",
                             annotation_text=f"TP: {signal_data.get('tp'):.2f}", row=1, col=1)
            
            fig.update_layout(
                title="Chart 1: M15 Execution (Z-Score + VWAP)",
                height=600,
                template="plotly_dark",
                hovermode="x unified"
            )
            
            # Export to PNG
            if self.kaleido_available:
                return self.pio.to_image(fig, format='png', width=1200, height=600)
            else:
                LOG.warning("[Chart1] Kaleido not available, returning HTML")
                return fig.to_html().encode('utf-8')
        
        except Exception as e:
            LOG.warning(f"[Chart1] M15 Z-Score chart failed: {e}")
            return None
    
    def _generate_h1_fvg_chart(self, h1_df: pd.DataFrame) -> bytes:
        """
        Chart 2: H1 Institutional Map with FVG boxes
        """
        if not self.charter_enabled or h1_df is None or h1_df.empty:
            return None
        
        try:
            if not PLOTLY_OK:
                LOG.warning("[Chart2] Plotly not available")
                return None
            
            import plotly.graph_objects as go
            
            fig = go.Figure()
            
            # OHLC Candlesticks
            fig.add_trace(
                go.Candlestick(
                    x=h1_df.index,
                    open=h1_df['open'],
                    high=h1_df['high'],
                    low=h1_df['low'],
                    close=h1_df['close'],
                    name='H1 Price'
                )
            )
            
            # FVG Detection and visualization
            if 'high' in h1_df.columns and 'low' in h1_df.columns:
                high = h1_df['high'].values
                low = h1_df['low'].values
                
                # Scan for Bullish FVGs (Low[i] > High[i-2])
                for i in range(2, len(h1_df)):
                    if low[i] > high[i-2]:
                        # Bullish FVG - draw green box
                        fig.add_shape(
                            type="rect",
                            x0=h1_df.index[i-2], y0=high[i-2],
                            x1=h1_df.index[i], y1=low[i],
                            fillcolor="green", opacity=0.2,
                            line=dict(color="green", width=2)
                        )
                    
                    # Bearish FVG (High[i] < Low[i-2])
                    elif high[i] < low[i-2]:
                        # Bearish FVG - draw red box
                        fig.add_shape(
                            type="rect",
                            x0=h1_df.index[i-2], y0=low[i-2],
                            x1=h1_df.index[i], y1=high[i],
                            fillcolor="red", opacity=0.2,
                            line=dict(color="red", width=2)
                        )
            
            fig.update_layout(
                title="Chart 2: H1 Institutional Map (FVG Liquidity Zones)",
                height=600,
                template="plotly_dark",
                hovermode="x unified",
                xaxis_rangeslider_visible=False
            )
            
            # Export to PNG
            if self.kaleido_available:
                return self.pio.to_image(fig, format='png', width=1200, height=600)
            else:
                LOG.warning("[Chart2] Kaleido not available, returning HTML")
                return fig.to_html().encode('utf-8')
        
        except Exception as e:
            LOG.warning(f"[Chart2] H1 FVG chart failed: {e}")
            return None
    
