class NewsEventFilter:
    """Prevents trading during major news events."""
    
    def __init__(self):
        self.major_news = [
            'NFP', 'FOMC', 'ECB', 'BOE', 'BOJ', 'RBA',
            'Fed Decision', 'Interest Rate', 'CPI', 'Inflation',
            'Employment Report', 'GDP', 'PMI'
        ]
        self.next_event_time = None
        self.pause_minutes_before = 30
    
    def is_trading_paused(self, current_time=None):
        """Check if trading should be paused due to upcoming news."""
        try:
            if current_time is None:
                current_time = datetime.now(timezone.utc)
            
            # In production, this would check an economic calendar API
            # For now, we'll implement a simple time-based check
            # (can be enhanced with alphacast, tradingeconomics, or forex factory API)
            
            # Hardcoded pause times for major events (example)
            now = current_time.replace(second=0, microsecond=0)
            hour, minute = now.hour, now.minute
            day_of_week = now.weekday()  # 0=Mon, 4=Fri
            
            # NFP: Usually Friday 13:30 UTC (pause 13:00-14:00)
            if day_of_week == 4:  # Friday
                if 13 <= hour < 14:
                    return {'paused': True, 'reason': 'NFP window', 'duration_min': 60}
            
            # FOMC: Usually Wednesday 18:00 UTC (pause 17:30-19:00)
            if day_of_week == 2:  # Wednesday
                if 17 <= hour < 19:
                    return {'paused': True, 'reason': 'FOMC window', 'duration_min': 90}
            
            # ECB: Usually Thursday 13:45 UTC (pause 13:15-14:30)
            if day_of_week == 3:  # Thursday
                if 13 <= hour < 15:
                    return {'paused': True, 'reason': 'ECB window', 'duration_min': 75}
            
            return {'paused': False, 'reason': 'No major news', 'duration_min': 0}
        except Exception as e:
            LOG.warning(f"[NewsFilter] Check failed: {e}")
            return {'paused': False, 'reason': 'Error in check', 'duration_min': 0}

NEWS_FILTER = NewsEventFilter()

