class AdvancedChartGenerator:
    def __init__(self, mode='dark'):
        self.mode = mode

    def _style(self, mode):
        if mode == 'light':
            return mpf.make_mpf_style(base_mpf_style='yahoo')
        return mpf.make_mpf_style(base_mpf_style='nightclouds')

    def _prepare_df(self, df):
        if df is None or df.empty:
            return None
        d = df.copy()
        if 'tick_volume' in d.columns and 'volume' not in d.columns:
            d = d.rename(columns={'tick_volume': 'volume'})
        if 'volume' not in d.columns:
            d['volume'] = 0
        if not isinstance(d.index, pd.DatetimeIndex):
            if 'time' in d.columns:
                d.index = pd.to_datetime(d['time'], unit='s', utc=True)
            else:
                d.index = pd.to_datetime(d.index, utc=True)
        d.index.name = 'Date'
        return d

    def _trend_mask(self, d):
        if d is None or len(d) < 30:
            return None
        ema_fast = d['close'].ewm(span=9, adjust=False).mean()
        ema_slow = d['close'].ewm(span=21, adjust=False).mean()
        return ema_fast > ema_slow

    def _support_resistance_levels(self, d, window=5, max_levels=6):
        if d is None or len(d) < window * 3:
            return []
        highs = d['high']
        lows = d['low']
        piv_high = highs[(highs.shift(window) < highs) & (highs.shift(-window) < highs)]
        piv_low = lows[(lows.shift(window) > lows) & (lows.shift(-window) > lows)]
        levels = []
        for price in pd.concat([piv_high, piv_low]).dropna():
            bucket = round(price * 2) / 2
            levels.append(bucket)
        strength = {}
        for lvl in levels:
            strength[lvl] = strength.get(lvl, 0) + 1
        ranked = sorted(strength.items(), key=lambda x: x[1], reverse=True)
        return ranked[:max_levels]

    def _volume_profile(self, d, bins=24, value_area=0.7):
        if d is None or d.empty:
            return None
        prices = d['close'].values
        volume = d['volume'].values if 'volume' in d.columns else np.ones_like(prices)
        hist, edges = np.histogram(prices, bins=bins, weights=volume)
        if hist.sum() == 0:
            return None
        centers = (edges[:-1] + edges[1:]) / 2
        poc_idx = int(np.argmax(hist))
        total = hist.sum()
        sorted_idx = np.argsort(hist)[::-1]
        cum = 0
        included = []
        for idx in sorted_idx:
            cum += hist[idx]
            included.append(idx)
            if cum >= total * value_area:
                break
        va_low = centers[min(included)]
        va_high = centers[max(included)]
        return {
            'hist': hist,
            'centers': centers,
            'poc': centers[poc_idx],
            'va_low': va_low,
            'va_high': va_high
        }

    def _fib_levels(self, d, lookback=120):
        if d is None or len(d) < lookback:
            return []
        recent = d.tail(lookback)
        high = recent['high'].max()
        low = recent['low'].min()
        if high == low:
            return []
        levels = [0.236, 0.382, 0.5, 0.618, 0.786]
        return [high - (high - low) * lvl for lvl in levels]

    def _annotate_patterns(self, ax, d):
        if d is None or d.empty:
            return
        patterns = CANDLESTICK.detect(d) if 'CANDLESTICK' in globals() else []
        harmonic = HARMONIC.detect(d) if 'HARMONIC' in globals() else None
        y = d['high'].iloc[-1]
        if harmonic:
            ax.text(0.01, 0.95, f"{harmonic['pattern']} {harmonic['type']}",
                    transform=ax.transAxes, fontsize=8, color='gold')
        if patterns:
            top = patterns[0]
            ax.text(0.01, 0.90, top['type'], transform=ax.transAxes, fontsize=8, color='cyan')

    def _strategy_overlays(self, d, strategy):
        overlays = []
        if d is None or d.empty:
            return overlays
        strat = (strategy or "").lower()
        if "mean" in strat:
            if 'bb_upper' in d.columns and 'bb_lower' in d.columns:
                overlays.append(mpf.make_addplot(d['bb_upper'], color='#9ca3af', linestyle='--', width=0.8))
                overlays.append(mpf.make_addplot(d['bb_lower'], color='#9ca3af', linestyle='--', width=0.8))
        elif "breakout" in strat:
            lookback = min(len(d), 20)
            high_level = d['high'].iloc[-lookback:].max()
            low_level = d['low'].iloc[-lookback:].min()
            overlays.append(mpf.make_addplot(pd.Series(high_level, index=d.index), color='#fbbf24', width=0.8))
            overlays.append(mpf.make_addplot(pd.Series(low_level, index=d.index), color='#fbbf24', width=0.8))
        else:
            if 'ema9' in d.columns and 'ema21' in d.columns:
                overlays.append(mpf.make_addplot(d['ema9'], color='#60a5fa', width=1.0))
                overlays.append(mpf.make_addplot(d['ema21'], color='#f59e0b', width=1.0))
        return overlays

    def generate(self, data, sig=None, mode=None):
        if not MPF_OK:
            return None

        try:
            if isinstance(data, pd.DataFrame):
                data = {CFG["timeframes"][0]: data}

            sig_tf = sig.get('tf') if sig else None
            tf = sig_tf or (CFG.get("zen_chart_tf", CFG["timeframes"][0]) if CFG.get("zen_chart_tf") in data else None) or next((tf for tf in CFG["timeframes"] if tf in data), None)
            if not tf:
                return None
            tfs = [tf]

            mode = mode or self.mode
            style = self._style(mode)

            show_vp = False
            fig = plt.figure(figsize=(10, 5.5))
            gs = fig.add_gridspec(nrows=1, ncols=1, hspace=0.15)

            sig_tf = sig.get('tf') if sig else None
            for idx, tf in enumerate(tfs):
                ax = fig.add_subplot(gs[idx, 0] if show_vp else gs[idx, 0])
                tf_df = self._prepare_df(data[tf])
                if tf_df is None or tf_df.empty:
                    continue

                d = add_indicators(tf_df)
                if d is None or d.empty:
                    continue
                apply_overlays = (sig_tf is None and idx == 0) or (sig_tf == tf)
                overlays = []
                if apply_overlays and CFG.get("chart_strategy_overlays", True):
                    overlays.extend(self._strategy_overlays(d, sig.get('strategy') if sig else None))

                # Plot candlesticks using matplotlib directly (more reliable than mpf.plot with ax)
                ax.set_facecolor('#111111' if mode == 'dark' else '#f2f2f2')
                
                # Draw candlesticks
                for i, (idx_val, row) in enumerate(d.iterrows()):
                    open_p, close_p = row['open'], row['close']
                    high_p, low_p = row['high'], row['low']
                    
                    color = '#2dd4bf' if close_p >= open_p else '#ef4444'
                    
                    # Draw wick
                    ax.plot([i, i], [low_p, high_p], color=color, linewidth=0.8)
                    
                    # Draw body
                    body_height = abs(close_p - open_p)
                    body_bottom = min(open_p, close_p)
                    ax.add_patch(plt.Rectangle((i - 0.3, body_bottom), 0.6, body_height, 
                                              facecolor=color, edgecolor=color, linewidth=1.0))
                
                # Add overlays (strategy lines like EMA)
                if overlays:
                    for overlay in overlays:
                        if isinstance(overlay, dict) and 'data' in overlay:
                            ax.plot(overlay['data'], color=overlay.get('color', '#60a5fa'), 
                                   linewidth=overlay.get('width', 1.0))
                
                # Trend shading
                trend = self._trend_mask(d) if CFG.get("chart_show_trend_shading", False) else None
                if trend is not None:
                    for i in range(1, len(d)):
                        if trend.iloc[i]:
                            ax.axvspan(i - 0.5, i + 0.5, color='#1b4332', alpha=0.08)
                        else:
                            ax.axvspan(i - 0.5, i + 0.5, color='#5a1a1a', alpha=0.06)

                # Support/Resistance levels
                if CFG.get("chart_show_sr", False):
                    sr_levels = self._support_resistance_levels(d)
                    for lvl, strength in sr_levels:
                        ax.axhline(lvl, color='white' if mode == 'dark' else 'black', 
                                  linewidth=0.6 + 0.2 * strength, alpha=0.5)

                # Fibonacci levels
                if apply_overlays and CFG.get("chart_show_fibs", False):
                    fibs = self._fib_levels(d)
                    for lvl in fibs:
                        ax.axhline(lvl, color='#b08968', linestyle='--', linewidth=0.8, alpha=0.8)

                # Signal levels (Entry, SL, TP)
                if apply_overlays and sig:
                    entry = sig.get('entry')
                    sl = sig.get('sl')
                    tp = sig.get('tp')
                    if entry and sl:
                        ax.axhspan(min(entry, sl), max(entry, sl), color='#991b1b', alpha=0.15)
                    if entry and tp:
                        ax.axhspan(min(entry, tp), max(entry, tp), color='#065f46', alpha=0.12)
                    if entry:
                        ax.axhline(entry, color='#4cc9f0', linewidth=1.2, label='Entry')
                    if sl:
                        ax.axhline(sl, color='#f94144', linestyle='--', linewidth=1.0, label='SL')
                    if tp:
                        ax.axhline(tp, color='#90be6d', linestyle='--', linewidth=1.0, label='TP')

                # Patterns
                if apply_overlays and CFG.get("chart_show_patterns", False):
                    try:
                        self._annotate_patterns(ax, d)
                    except:
                        pass

                ax.set_title(f"{CFG['symbol']} {tf}", fontsize=9)
                ax.set_xlim(0, len(d))
                ax.set_ylim(d['low'].min() * 0.99, d['high'].max() * 1.01)
                ax.grid(True, alpha=0.2)


            buf = io.BytesIO()
            fig.savefig(buf, format='png', dpi=150, bbox_inches='tight')
            plt.close(fig)
            buf.seek(0)
            return buf.read()
        
        except ValueError as e:
            LOG.debug(f"[CHART] Chart generation error: {e}")
            plt.close('all')
            return None
        except Exception as e:
            LOG.debug(f"[CHART] Generation failed: {type(e).__name__}: {e}")
            plt.close('all')
            return None

