class MultiTimeframeSignalAggregator:
    """Combine signals from multiple timeframes with intelligent weighting"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.timeframes = ['5m', '15m', '1h', '4h', '1d']
        self.signal_cache = {}  # {timeframe: signal}
        self.weights = {'5m': 0.15, '15m': 0.20, '1h': 0.25, '4h': 0.20, '1d': 0.20}
        self.lock = threading.Lock()
    
    def add_signal(self, timeframe: str, signal: Dict) -> None:
        """Add signal from specific timeframe"""
        try:
            with self.lock:
                if timeframe in self.timeframes:
                    self.signal_cache[timeframe] = {
                        'value': float(signal.get('value', 0)),
                        'confidence': float(signal.get('confidence', 0.5)),
                        'strength': float(signal.get('strength', 0)),
                        'timestamp': datetime.now()
                    }
        except Exception as e:
            LOG.warning(f"[MTF] Add signal failed: {e}")
    
    def aggregate_signals(self) -> Dict:
        """Combine all timeframe signals into weighted aggregate"""
        try:
            with self.lock:
                if len(self.signal_cache) == 0:
                    return {'aggregated_signal': 0, 'consensus': 0, 'alignment': 0, 'valid': False}
                
                weighted_sum = 0.0
                weighted_confidence = 0.0
                alignment_score = 0.0
                signal_count = len(self.signal_cache)
                
                for tf, signal in self.signal_cache.items():
                    weight = self.weights.get(tf, 0.15)
                    weighted_sum += signal['value'] * weight
                    weighted_confidence += signal['confidence'] * weight
                
                # Alignment: how many signals agree on direction
                bullish_count = sum(1 for s in self.signal_cache.values() if s['value'] > 0)
                bearish_count = sum(1 for s in self.signal_cache.values() if s['value'] < 0)
                alignment_score = max(bullish_count, bearish_count) / max(1, signal_count)
                
                # Consensus score (0-100)
                consensus = abs(weighted_sum) * 100 if signal_count >= 3 else 0
                
                result = {
                    'aggregated_signal': float(weighted_sum),
                    'confidence': float(weighted_confidence),
                    'consensus': float(min(100, consensus)),
                    'alignment': float(alignment_score),
                    'signal_count': signal_count,
                    'bullish_count': bullish_count,
                    'bearish_count': bearish_count,
                    'valid': signal_count >= 3,
                    'timestamp': datetime.now()
                }
                
                LOG.info(f"[MTF] Agg: {result['aggregated_signal']:.2f}, Consensus: {result['consensus']:.0f}%")
                return result
        except Exception as e:
            LOG.warning(f"[MTF] Aggregation failed: {e}")
            return {'aggregated_signal': 0, 'consensus': 0, 'alignment': 0, 'valid': False}
    
    def get_signal_alignment(self) -> str:
        """Get signal alignment: STRONG_BULLISH, BULLISH, NEUTRAL, BEARISH, STRONG_BEARISH"""
        try:
            result = self.aggregate_signals()
            if not result['valid']:
                return 'INSUFFICIENT_DATA'
            
            consensus = result['consensus']
            alignment = result['alignment']
            
            if consensus > 70 and alignment > 0.7:
                return 'STRONG_BULLISH' if result['aggregated_signal'] > 0 else 'STRONG_BEARISH'
            elif consensus > 50 and alignment > 0.6:
                return 'BULLISH' if result['aggregated_signal'] > 0 else 'BEARISH'
            else:
                return 'NEUTRAL'
        except Exception as e:
            LOG.warning(f"[MTF] Alignment detection failed: {e}")
            return 'ERROR'


class CandlestickPatternDetector:
    """Recognize 20+ candlestick patterns for signal confirmation"""
    
    def __init__(self):
        self.patterns_found = deque(maxlen=100)
        self.lock = threading.Lock()
    
    def detect_patterns(self, df: pd.DataFrame, lookback: int = 5) -> Dict:
        """Detect candlestick patterns in recent candles"""
        try:
            if df is None or df.empty or len(df) < lookback:
                return {'patterns': [], 'strongest': None, 'confidence': 0}
            
            patterns = []
            recent = df.iloc[-lookback:].reset_index(drop=True)
            
            with self.lock:
                # Single candle patterns
                for idx in range(len(recent) - 1, max(0, len(recent) - 3), -1):
                    candle = recent.iloc[idx]
                    if idx > 0:
                        prev_candle = recent.iloc[idx - 1]
                    
                    # Doji
                    if self._is_doji(candle):
                        patterns.append({'name': 'DOJI', 'confidence': 0.7, 'signal': 'REVERSAL'})
                    
                    # Hammer
                    if self._is_hammer(candle):
                        patterns.append({'name': 'HAMMER', 'confidence': 0.75, 'signal': 'BULLISH'})
                    
                    # Shooting Star
                    if self._is_shooting_star(candle):
                        patterns.append({'name': 'SHOOTING_STAR', 'confidence': 0.75, 'signal': 'BEARISH'})
                
                # Two-candle patterns
                if len(recent) >= 2:
                    curr = recent.iloc[-1]
                    prev = recent.iloc[-2]
                    
                    # Engulfing
                    if self._is_engulfing(prev, curr):
                        direction = 'BULLISH' if curr['close'] > curr['open'] else 'BEARISH'
                        patterns.append({'name': 'ENGULFING', 'confidence': 0.80, 'signal': direction})
                    
                    # Piercing Line
                    if self._is_piercing_line(prev, curr):
                        patterns.append({'name': 'PIERCING_LINE', 'confidence': 0.75, 'signal': 'BULLISH'})
                    
                    # Cloud Cover
                    if self._is_cloud_cover(prev, curr):
                        patterns.append({'name': 'CLOUD_COVER', 'confidence': 0.75, 'signal': 'BEARISH'})
                    
                    # Harami
                    if self._is_harami(prev, curr):
                        direction = 'BULLISH' if curr['close'] > curr['open'] else 'BEARISH'
                        patterns.append({'name': 'HARAMI', 'confidence': 0.70, 'signal': direction})
                    
                    # Kicker
                    if self._is_kicker(prev, curr):
                        direction = 'BULLISH' if curr['close'] > curr['open'] else 'BEARISH'
                        patterns.append({'name': 'KICKER', 'confidence': 0.80, 'signal': direction})
                    
                    # Inside Bar
                    if self._is_inside_bar(prev, curr):
                        patterns.append({'name': 'INSIDE_BAR', 'confidence': 0.65, 'signal': 'NEUTRAL'})
                    
                    # Outside Bar
                    if self._is_outside_bar(prev, curr):
                        direction = 'BULLISH' if curr['close'] > curr['open'] else 'BEARISH'
                        patterns.append({'name': 'OUTSIDE_BAR', 'confidence': 0.75, 'signal': direction})
                
                # Three-candle patterns
                if len(recent) >= 3:
                    # Morning Star / Evening Star
                    c1, c2, c3 = recent.iloc[-3], recent.iloc[-2], recent.iloc[-1]
                    
                    if self._is_morning_star(c1, c2, c3):
                        patterns.append({'name': 'MORNING_STAR', 'confidence': 0.80, 'signal': 'BULLISH'})
                    
                    if self._is_evening_star(c1, c2, c3):
                        patterns.append({'name': 'EVENING_STAR', 'confidence': 0.80, 'signal': 'BEARISH'})
                    
                    # Three White Soldiers / Three Black Crows
                    if self._is_three_white_soldiers(c1, c2, c3):
                        patterns.append({'name': 'THREE_WHITE_SOLDIERS', 'confidence': 0.85, 'signal': 'BULLISH'})
                    
                    if self._is_three_black_crows(c1, c2, c3):
                        patterns.append({'name': 'THREE_BLACK_CROWS', 'confidence': 0.85, 'signal': 'BEARISH'})
                
                strongest = max(patterns, key=lambda x: x['confidence']) if patterns else None
                
                self.patterns_found.append({
                    'timestamp': datetime.now(),
                    'patterns': patterns,
                    'count': len(patterns)
                })
                
                LOG.info(f"[PATTERNS] Found {len(patterns)} patterns. Strongest: {strongest['name'] if strongest else 'None'}")
                
                return {
                    'patterns': patterns,
                    'strongest': strongest,
                    'confidence': strongest['confidence'] if strongest else 0,
                    'count': len(patterns)
                }
        except Exception as e:
            LOG.warning(f"[PATTERNS] Detection failed: {e}")
            return {'patterns': [], 'strongest': None, 'confidence': 0}
    
    def _is_doji(self, candle) -> bool:
        """Check if candle is a doji (open ~= close)"""
        body = abs(candle['close'] - candle['open'])
        total = candle['high'] - candle['low']
        return body < (total * 0.1) and total > 0
    
    def _is_hammer(self, candle) -> bool:
        """Check for hammer pattern (small body, long lower wick)"""
        body = abs(candle['close'] - candle['open'])
        total = candle['high'] - candle['low']
        lower_wick = min(candle['open'], candle['close']) - candle['low']
        return lower_wick > (body * 2) and body > 0 and lower_wick > (total * 0.5)
    
    def _is_shooting_star(self, candle) -> bool:
        """Check for shooting star (small body, long upper wick)"""
        body = abs(candle['close'] - candle['open'])
        total = candle['high'] - candle['low']
        upper_wick = candle['high'] - max(candle['open'], candle['close'])
        return upper_wick > (body * 2) and body > 0 and upper_wick > (total * 0.5)
    
    def _is_engulfing(self, prev, curr) -> bool:
        """Check for engulfing pattern"""
        prev_range = abs(prev['close'] - prev['open'])
        curr_range = abs(curr['close'] - curr['open'])
        curr_high = max(curr['close'], curr['open'])
        curr_low = min(curr['close'], curr['open'])
        prev_high = max(prev['close'], prev['open'])
        prev_low = min(prev['close'], prev['open'])
        return curr_range > prev_range and curr_high > prev_high and curr_low < prev_low
    
    def _is_piercing_line(self, prev, curr) -> bool:
        """Check for piercing line (bearish to bullish confirmation)"""
        if prev['close'] >= prev['open']:  # Must be bearish candle first
            return False
        curr_open = curr['open']
        prev_middle = (prev['close'] + prev['open']) / 2
        return curr_open < prev['close'] and curr['close'] > prev_middle and curr['close'] < prev['open']
    
    def _is_cloud_cover(self, prev, curr) -> bool:
        """Check for cloud cover (bullish to bearish)"""
        if prev['close'] <= prev['open']:  # Must be bullish first
            return False
        prev_middle = (prev['close'] + prev['open']) / 2
        return curr['open'] > prev['close'] and curr['close'] < prev_middle and curr['close'] > prev['open']
    
    def _is_morning_star(self, c1, c2, c3) -> bool:
        """Morning star: bearish, small body, bullish closing above middle"""
        if c1['close'] >= c1['open']:
            return False  # Must start bearish
        mid_c1 = (c1['close'] + c1['open']) / 2
        return c2['high'] - c2['low'] < (c1['high'] - c1['low']) * 0.5 and c3['close'] > mid_c1
    
    def _is_evening_star(self, c1, c2, c3) -> bool:
        """Evening star: bullish, small body, bearish closing below middle"""
        if c1['close'] <= c1['open']:
            return False  # Must start bullish
        mid_c1 = (c1['close'] + c1['open']) / 2
        return c2['high'] - c2['low'] < (c1['high'] - c1['low']) * 0.5 and c3['close'] < mid_c1
    
    def _is_harami(self, prev, curr) -> bool:
        """Harami: Previous candle completely contains current candle body"""
        prev_high = max(prev['open'], prev['close'])
        prev_low = min(prev['open'], prev['close'])
        curr_high = max(curr['open'], curr['close'])
        curr_low = min(curr['open'], curr['close'])
        
        # Current candle is inside previous candle
        is_inside = curr_high < prev_high and curr_low > prev_low
        # Opposite direction
        opposite_dir = (prev['close'] > prev['open']) != (curr['close'] > curr['open'])
        
        return is_inside and opposite_dir
    
    def _is_kicker(self, prev, curr) -> bool:
        """Kicker: Gap with opposite direction (bullish or bearish)"""
        gap_size = abs(curr['open'] - prev['close'])
        prev_range = abs(prev['close'] - prev['open'])
        
        # Gap must be significant and directions opposite
        gap_significant = gap_size > prev_range * 0.5
        opposite = (prev['close'] > prev['open']) != (curr['close'] > curr['open'])
        
        return gap_significant and opposite
    
    def _is_three_white_soldiers(self, c1, c2, c3) -> bool:
        """Three White Soldiers: Three consecutive bullish candles with higher closes"""
        is_bullish = (c1['close'] > c1['open']) and (c2['close'] > c2['open']) and (c3['close'] > c3['open'])
        ascending = (c1['close'] < c2['close']) and (c2['close'] < c3['close'])
        return is_bullish and ascending
    
    def _is_three_black_crows(self, c1, c2, c3) -> bool:
        """Three Black Crows: Three consecutive bearish candles with lower closes"""
        is_bearish = (c1['close'] < c1['open']) and (c2['close'] < c2['open']) and (c3['close'] < c3['open'])
        descending = (c1['close'] > c2['close']) and (c2['close'] > c3['close'])
        return is_bearish and descending
    
    def _is_inside_bar(self, prev, curr) -> bool:
        """Inside Bar: Current bar has smaller range than previous bar"""
        prev_range = prev['high'] - prev['low']
        curr_range = curr['high'] - curr['low']
        
        inside_range = curr['high'] < prev['high'] and curr['low'] > prev['low']
        return inside_range and curr_range < prev_range
    
    def _is_outside_bar(self, prev, curr) -> bool:
        """Outside Bar / Break Out: Current bar completely encompasses previous bar"""
        return curr['high'] > prev['high'] and curr['low'] < prev['low']


class AdvancedOscillatorsCalculator:
    """Calculate 7 advanced oscillators for signal confirmation"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.cache = {}
        self.lock = threading.Lock()
    
    def calculate_all(self, df: pd.DataFrame) -> Dict:
        """Calculate all advanced oscillators"""
        try:
            with self.lock:
                results = {}
                
                if df is None or df.empty:
                    return results
                
                # 1. Stochastic RSI
                results['stoch_rsi'] = self._stochastic_rsi(df)
                
                # 2. Williams %R
                results['williams_r'] = self._williams_percent_r(df)
                
                # 3. CCI (Commodity Channel Index)
                results['cci'] = self._cci(df)
                
                # 4. DeMarker
                results['demarker'] = self._demarker(df)
                
                # 5. Ultimate Oscillator
                results['ultimate_osc'] = self._ultimate_oscillator(df)
                
                # 6. Accumulation/Distribution
                results['ad_line'] = self._accumulation_distribution(df)
                
                # 7. Money Flow Index
                results['mfi'] = self._money_flow_index(df)
                
                LOG.info(f"[OSCILLATORS] Calculated 7 indicators")
                return results
        except Exception as e:
            LOG.warning(f"[OSCILLATORS] Calculation failed: {e}")
            return {}
    
    def _stochastic_rsi(self, df: pd.DataFrame, period: int = 14) -> Dict:
        """Stochastic RSI combines RSI with Stochastic oscillator"""
        if len(df) < period:
            return {}
        try:
            rsi = 100 - (100 / (1 + (df['close'].diff().clip(lower=0).rolling(period).mean() / 
                                       df['close'].diff().clip(upper=0).rolling(period).mean().abs())))
            rsi_min = rsi.rolling(period).min()
            rsi_max = rsi.rolling(period).max()
            stoch_rsi = (rsi - rsi_min) / (rsi_max - rsi_min) * 100
            return {'value': float(stoch_rsi.iloc[-1]), 'signal': 'OVERBOUGHT' if stoch_rsi.iloc[-1] > 80 else 'OVERSOLD' if stoch_rsi.iloc[-1] < 20 else 'NEUTRAL'}
        except:
            return {}
    
    def _williams_percent_r(self, df: pd.DataFrame, period: int = 14) -> Dict:
        """Williams %R for overbought/oversold detection"""
        if len(df) < period:
            return {}
        try:
            highest = df['high'].rolling(period).max()
            lowest = df['low'].rolling(period).min()
            wr = ((highest - df['close']) / (highest - lowest)) * -100
            return {'value': float(wr.iloc[-1]), 'signal': 'OVERBOUGHT' if wr.iloc[-1] < -80 else 'OVERSOLD' if wr.iloc[-1] > -20 else 'NEUTRAL'}
        except:
            return {}
    
    def _cci(self, df: pd.DataFrame, period: int = 20) -> Dict:
        """Commodity Channel Index for cycle detection"""
        if len(df) < period:
            return {}
        try:
            tp = (df['high'] + df['low'] + df['close']) / 3
            sma = tp.rolling(period).mean()
            mad = tp.rolling(period).apply(lambda x: abs(x - x.mean()).mean())
            cci = (tp - sma) / (0.015 * mad)
            return {'value': float(cci.iloc[-1]), 'signal': 'OVERBOUGHT' if cci.iloc[-1] > 100 else 'OVERSOLD' if cci.iloc[-1] < -100 else 'NEUTRAL'}
        except:
            return {}
    
    def _demarker(self, df: pd.DataFrame, period: int = 14) -> Dict:
        """DeMarker for exhaustion signals"""
        if len(df) < period:
            return {}
        try:
            dem_high = np.where(df['high'] > df['high'].shift(1), df['high'] - df['high'].shift(1), 0)
            dem_low = np.where(df['low'] < df['low'].shift(1), df['low'].shift(1) - df['low'], 0)
            dem = dem_high.sum() / (dem_high.sum() + dem_low.sum()) if (dem_high.sum() + dem_low.sum()) > 0 else 0.5
            return {'value': float(dem * 100), 'signal': 'OVERBOUGHT' if dem > 0.7 else 'OVERSOLD' if dem < 0.3 else 'NEUTRAL'}
        except:
            return {}
    
    def _ultimate_oscillator(self, df: pd.DataFrame) -> Dict:
        """Ultimate Oscillator for multi-timeframe momentum"""
        if len(df) < 28:
            return {}
        try:
            bp = df['close'] - np.minimum(df['low'], df['close'].shift(1))
            tr = np.maximum(df['high'], df['close'].shift(1)) - np.minimum(df['low'], df['close'].shift(1))
            uo = 100 * ((4 * bp.rolling(7).sum() / tr.rolling(7).sum()) + 
                        (2 * bp.rolling(14).sum() / tr.rolling(14).sum()) + 
                        (bp.rolling(28).sum() / tr.rolling(28).sum())) / 7
            return {'value': float(uo.iloc[-1]), 'signal': 'OVERBOUGHT' if uo.iloc[-1] > 70 else 'OVERSOLD' if uo.iloc[-1] < 30 else 'NEUTRAL'}
        except:
            return {}
    
    def _accumulation_distribution(self, df: pd.DataFrame) -> Dict:
        """Accumulation/Distribution for volume-price relationship"""
        if len(df) < 2:
            return {}
        try:
            clv = ((df['close'] - df['low']) - (df['high'] - df['close'])) / (df['high'] - df['low'])
            ad = (clv * df['volume']).cumsum()
            return {'value': float(ad.iloc[-1]), 'trend': 'ACCUMULATING' if ad.iloc[-1] > ad.iloc[-2] else 'DISTRIBUTING'}
        except:
            return {}
    
    def _money_flow_index(self, df: pd.DataFrame, period: int = 14) -> Dict:
        """Money Flow Index for volume-weighted momentum"""
        if len(df) < period:
            return {}
        try:
            tp = (df['high'] + df['low'] + df['close']) / 3
            raw_mf = tp * df['volume']
            pos_mf = np.where(tp > tp.shift(1), raw_mf, 0).rolling(period).sum()
            neg_mf = np.where(tp < tp.shift(1), raw_mf, 0).rolling(period).sum()
            mfr = pos_mf / neg_mf if neg_mf.iloc[-1] > 0 else 1
            mfi = 100 - (100 / (1 + mfr))
            return {'value': float(mfi.iloc[-1]), 'signal': 'OVERBOUGHT' if mfi.iloc[-1] > 80 else 'OVERSOLD' if mfi.iloc[-1] < 20 else 'NEUTRAL'}
        except:
            return {}


class DynamicPositionSizer:
    """Bayesian Kelly criterion for real-time position sizing"""
    
    def __init__(self, store=None, config: Dict = None):
        self.store = store
        self.cfg = config or {}
        self.lock = threading.Lock()
        self.win_probability = 0.55  # Prior: 55% win rate
        self.trades_seen = 0
    
    def update_win_probability(self, wins: int, losses: int) -> float:
        """Update win probability using Bayesian approach"""
        try:
            with self.lock:
                total = wins + losses
                if total > 0:
                    # Bayesian update with prior (0.55 default)
                    prior_wins = int(20 * 0.55)  # 20 trades prior
                    prior_losses = int(20 * 0.45)
                    self.win_probability = (wins + prior_wins) / (total + prior_wins + prior_losses)
                    self.trades_seen = total
                return self.win_probability
        except Exception as e:
            LOG.warning(f"[DYNO_SIZE] Win prob update failed: {e}")
            return 0.55
    
    def calculate_optimal_size(self, account_balance: float, win_prob: float = None, 
                               avg_win: float = 1.5, avg_loss: float = 1.0) -> Dict:
        """Calculate position size using Kelly Criterion with Bayesian probability"""
        try:
            with self.lock:
                if win_prob is None:
                    win_prob = self.win_probability
                
                win_prob = max(0.3, min(0.7, win_prob))  # Constrain to 30-70%
                
                # Kelly formula: f = (bp - q) / b
                # b = ratio of win to loss, p = win prob, q = loss prob
                b = avg_win / avg_loss if avg_loss > 0 else 1.5
                q = 1 - win_prob
                
                kelly_f = (b * win_prob - q) / b if b > 0 else 0.02
                
                # Fractional Kelly (safer): use 25-50% of Kelly
                fractional_kelly = kelly_f * 0.4  # 40% of Kelly
                
                # Convert to position size
                risk_per_trade = account_balance * fractional_kelly
                position_size = risk_per_trade / avg_loss if avg_loss > 0 else account_balance * 0.02
                
                # Cap at reasonable limits
                position_size = max(0.01, min(position_size, account_balance * 0.1))
                
                LOG.info(f"[DYNO_SIZE] WinProb={win_prob:.1%}, Size=${position_size:.2f}")
                
                return {
                    'position_size': float(position_size),
                    'kelly_f': float(kelly_f),
                    'fractional_kelly': float(fractional_kelly),
                    'win_probability': float(win_prob),
                    'risk_per_trade': float(risk_per_trade)
                }
        except Exception as e:
            LOG.warning(f"[DYNO_SIZE] Calculation failed: {e}")
            return {'position_size': account_balance * 0.02, 'kelly_f': 0.02}


class MLSignalValidator:
    """ML-based signal validation using XGBoost"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.model = None
        self.feature_names = [
            'rsi', 'macd', 'bb_position', 'trend_strength', 'volatility',
            'volume_ratio', 'candle_body_ratio', 'recent_trades_wr'
        ]
        self.lock = threading.Lock()
        self.signal_count = 0
        self.validated_count = 0
        self._initialize_model()
    
    def _initialize_model(self):
        """Initialize placeholder XGBoost model"""
        try:
            try:
                import xgboost as xgb
                self.model = xgb.XGBClassifier(n_estimators=100, max_depth=6, learning_rate=0.1)
                self.has_xgb = True
            except ImportError:
                LOG.warning("[ML_VALIDATOR] XGBoost not installed, using simple threshold model")
                self.has_xgb = False
                self.model = None
        except Exception as e:
            LOG.warning(f"[ML_VALIDATOR] Model init failed: {e}")
    
    def validate_signal(self, signal: Dict, features: Dict) -> Dict:
        """Validate signal and return confidence"""
        try:
            with self.lock:
                self.signal_count += 1
                
                # Extract features
                feature_vector = self._extract_features(features)
                
                if self.has_xgb and self.model is not None:
                    # Use ML model if available
                    try:
                        confidence = float(self.model.predict_proba([feature_vector])[0][1])
                    except:
                        confidence = self._simple_validation(features)
                else:
                    # Fallback to simple validation
                    confidence = self._simple_validation(features)
                
                is_valid = confidence > 0.55  # Threshold for acceptance
                
                if is_valid:
                    self.validated_count += 1
                
                LOG.info(f"[ML_VALIDATOR] Signal validation: {confidence:.2%}, Valid={is_valid}")
                
                return {
                    'is_valid': is_valid,
                    'confidence': float(confidence),
                    'validation_count': self.validated_count,
                    'total_signals': self.signal_count,
                    'acceptance_rate': self.validated_count / max(1, self.signal_count)
                }
        except Exception as e:
            LOG.warning(f"[ML_VALIDATOR] Validation failed: {e}")
            return {'is_valid': True, 'confidence': 0.5}  # Default to accept
    
    def _extract_features(self, feature_dict: Dict) -> List:
        """Extract features for model"""
        try:
            return [
                feature_dict.get('rsi', 50) / 100,
                feature_dict.get('macd', 0),
                feature_dict.get('bb_position', 0.5),
                feature_dict.get('trend_strength', 0.5),
                feature_dict.get('volatility', 0.5),
                feature_dict.get('volume_ratio', 1.0),
                feature_dict.get('candle_body_ratio', 0.5),
                feature_dict.get('recent_trades_wr', 0.5)
            ]
        except:
            return [0.5] * len(self.feature_names)
    
    def _simple_validation(self, features: Dict) -> float:
        """Simple validation without ML model"""
        score = 0.0
        
        # RSI confirmation
        rsi = features.get('rsi', 50)
        if rsi < 30 or rsi > 70:
            score += 0.15
        
        # MACD confirmation
        if features.get('macd', 0) != 0:
            score += 0.15
        
        # Bollinger Bands
        bb_pos = features.get('bb_position', 0.5)
        if bb_pos < 0.1 or bb_pos > 0.9:
            score += 0.15
        
        # Trend strength
        trend = features.get('trend_strength', 0)
        if trend > 0.6:
            score += 0.20
        
        # Volatility (lower is better for entry)
        vol = features.get('volatility', 0.5)
        if vol < 0.7:
            score += 0.10
        
        # Volume confirmation
        vol_ratio = features.get('volume_ratio', 1.0)
        if vol_ratio > 1.0:
            score += 0.10
        
        # Recent win rate
        wr = features.get('recent_trades_wr', 0.5)
        if wr > 0.5:
            score += 0.15
        
        return min(1.0, score)


