class VolatilityRegimeDetector:
    """Detect and adapt strategies to volatility regimes"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.regimes = {
            'LOW': {'min': 0, 'max': 7, 'strategies': ['SCALP', 'GRID'], 'risk_mult': 0.8},
            'NORMAL': {'min': 7, 'max': 12, 'strategies': ['TREND', 'BREAKOUT'], 'risk_mult': 1.0},
            'HIGH': {'min': 12, 'max': 20, 'strategies': ['BREAKOUT', 'MEAN_REV'], 'risk_mult': 0.7},
            'EXTREME': {'min': 20, 'max': 100, 'strategies': ['HEDGE', 'SAFE'], 'risk_mult': 0.5}
        }
        self.current_regime = 'NORMAL'
        self.lock = threading.Lock()
    
    def detect_regime(self, df: pd.DataFrame, period: int = 20) -> Dict:
        """Detect current volatility regime"""
        try:
            if df is None or df.empty or len(df) < period:
                return {'regime': 'NORMAL', 'volatility': 10, 'current_regime': self.current_regime}
            
            # Calculate ATR-based volatility
            high_low = df['high'].iloc[-period:] - df['low'].iloc[-period:]
            high_close = abs(df['high'].iloc[-period:] - df['close'].iloc[-period:].shift())
            low_close = abs(df['low'].iloc[-period:] - df['close'].iloc[-period:].shift())
            
            tr = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
            atr = tr.mean()
            
            # Normalize by recent price
            volatility_pct = (atr / df['close'].iloc[-1]) * 100 if df['close'].iloc[-1] > 0 else 10
            
            with self.lock:
                # Determine regime
                for regime_name, regime_data in self.regimes.items():
                    if regime_data['min'] <= volatility_pct < regime_data['max']:
                        self.current_regime = regime_name
                        break
            
            LOG.info(f"[VOL_REGIME] {self.current_regime} (ATR={atr:.2f}, Vol={volatility_pct:.1f}%)")
            
            return {
                'regime': self.current_regime,
                'volatility': float(volatility_pct),
                'atr': float(atr),
                'recommended_strategies': self.regimes[self.current_regime]['strategies'],
                'risk_multiplier': self.regimes[self.current_regime]['risk_mult']
            }
        except Exception as e:
            LOG.warning(f"[VOL_REGIME] Detection failed: {e}")
            return {'regime': 'NORMAL', 'volatility': 10}


class SentimentAnalyzer:
    """Analyze sentiment from news and social media for gold market"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.sentiment_cache = deque(maxlen=1000)
        self.lock = threading.Lock()
        self.events = []
    
    def analyze_sentiment(self, text: str, source: str = 'generic') -> float:
        """Analyze sentiment (-1 to +1 scale)"""
        try:
            # Simple keyword-based sentiment (fallback without NLP library)
            bullish_keywords = ['gold', 'surge', 'bullish', 'strength', 'climb', 'gain', 'up', 'higher', 'buying']
            bearish_keywords = ['crash', 'decline', 'bearish', 'weakness', 'fall', 'loss', 'down', 'lower', 'selling']
            
            text_lower = text.lower()
            bullish_count = sum(text_lower.count(word) for word in bullish_keywords)
            bearish_count = sum(text_lower.count(word) for word in bearish_keywords)
            
            total = bullish_count + bearish_count
            if total == 0:
                sentiment = 0.0
            else:
                sentiment = (bullish_count - bearish_count) / total
            
            with self.lock:
                self.sentiment_cache.append({
                    'sentiment': sentiment,
                    'source': source,
                    'timestamp': datetime.now(),
                    'text_sample': text[:100]
                })
            
            return float(sentiment)
        except Exception as e:
            LOG.warning(f"[SENTIMENT] Analysis failed: {e}")
            return 0.0
    
    def get_sentiment_summary(self) -> Dict:
        """Get current sentiment summary"""
        try:
            with self.lock:
                if not self.sentiment_cache:
                    return {'avg_sentiment': 0, 'count': 0, 'trend': 'NEUTRAL'}
                
                sentiments = [s['sentiment'] for s in list(self.sentiment_cache)[-20:]]
                avg_sentiment = sum(sentiments) / len(sentiments)
                
                trend = 'BULLISH' if avg_sentiment > 0.3 else 'BEARISH' if avg_sentiment < -0.3 else 'NEUTRAL'
                
                return {
                    'avg_sentiment': float(avg_sentiment),
                    'count': len(self.sentiment_cache),
                    'trend': trend,
                    'confidence': float(abs(avg_sentiment))
                }
        except Exception as e:
            LOG.warning(f"[SENTIMENT] Summary failed: {e}")
            return {'avg_sentiment': 0, 'count': 0}


class OrderFlowImbalanceAnalyzer:
    """Analyze order flow imbalance and large trader movements"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.order_flow_history = deque(maxlen=500)
        self.lock = threading.Lock()
    
    def analyze_order_flow(self, buy_volume: float, sell_volume: float, 
                          large_buy: float = 0, large_sell: float = 0) -> Dict:
        """Analyze order flow imbalance"""
        try:
            total_volume = buy_volume + sell_volume
            if total_volume == 0:
                return {'imbalance': 0, 'pressure': 'NEUTRAL'}
            
            # Order imbalance ratio
            imbalance = (buy_volume - sell_volume) / total_volume
            
            # Large trader detection
            large_ratio = (large_buy + large_sell) / total_volume if total_volume > 0 else 0
            
            # Pressure calculation
            pressure = 'BULLISH' if imbalance > 0.1 else 'BEARISH' if imbalance < -0.1 else 'NEUTRAL'
            
            with self.lock:
                self.order_flow_history.append({
                    'timestamp': datetime.now(),
                    'imbalance': imbalance,
                    'buy_volume': buy_volume,
                    'sell_volume': sell_volume,
                    'large_trader_activity': large_ratio
                })
            
            LOG.info(f"[ORDER_FLOW] Imbalance={imbalance:.2%}, Pressure={pressure}")
            
            return {
                'imbalance': float(imbalance),
                'pressure': pressure,
                'buy_volume': float(buy_volume),
                'sell_volume': float(sell_volume),
                'large_trader_activity': float(large_ratio)
            }
        except Exception as e:
            LOG.warning(f"[ORDER_FLOW] Analysis failed: {e}")
            return {'imbalance': 0, 'pressure': 'NEUTRAL'}


class CorrelationForecaster:
    """Forecast correlations between XAUUSD and other pairs"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.correlations = {}
        self.lock = threading.Lock()
    
    def forecast_correlation(self, symbol1_returns: pd.Series, symbol2_returns: pd.Series,
                            horizon: int = 5) -> Dict:
        """Forecast future correlation"""
        try:
            if len(symbol1_returns) < 20 or len(symbol2_returns) < 20:
                return {'forecast': 0.0, 'confidence': 0.0}
            
            # Current correlation
            current_corr = symbol1_returns.corr(symbol2_returns)
            
            # Rolling correlation (trend)
            window = min(20, len(symbol1_returns) - 1)
            rolling_corr = symbol1_returns.rolling(window).corr(symbol2_returns)
            
            # Simple forecast: weighted average of recent correlations
            recent_corr = rolling_corr.iloc[-5:].mean()
            forecast = (current_corr * 0.4) + (recent_corr * 0.6)
            
            # Confidence based on stability
            corr_std = rolling_corr.iloc[-10:].std()
            confidence = max(0, 1.0 - corr_std)
            
            LOG.info(f"[CORR_FORECAST] Current={current_corr:.2f}, Forecast={forecast:.2f}")
            
            return {
                'current_correlation': float(current_corr),
                'forecasted_correlation': float(forecast),
                'confidence': float(confidence),
                'trend': 'INCREASING' if forecast > current_corr else 'DECREASING' if forecast < current_corr else 'STABLE'
            }
        except Exception as e:
            LOG.warning(f"[CORR_FORECAST] Failed: {e}")
            return {'forecast': 0.0, 'confidence': 0.0}


class SRIntelligentDetector:
    """ML-powered Support/Resistance detection"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.levels = []
        self.lock = threading.Lock()
    
    def detect_sr_levels(self, df: pd.DataFrame, lookback: int = 100) -> Dict:
        """Detect support and resistance levels"""
        try:
            if df is None or df.empty or len(df) < lookback:
                return {'support': [], 'resistance': []}
            
            recent_price = df['close'].iloc[-1]
            data = df.iloc[-lookback:]
            
            # Find local extrema
            support_levels = []
            resistance_levels = []
            
            for i in range(1, len(data) - 1):
                # Local minimum (support)
                if data.iloc[i]['low'] < data.iloc[i-1]['low'] and data.iloc[i]['low'] < data.iloc[i+1]['low']:
                    support_levels.append({
                        'level': float(data.iloc[i]['low']),
                        'strength': 0.5,
                        'touches': 1,
                        'distance': abs(recent_price - data.iloc[i]['low'])
                    })
                
                # Local maximum (resistance)
                if data.iloc[i]['high'] > data.iloc[i-1]['high'] and data.iloc[i]['high'] > data.iloc[i+1]['high']:
                    resistance_levels.append({
                        'level': float(data.iloc[i]['high']),
                        'strength': 0.5,
                        'touches': 1,
                        'distance': abs(recent_price - data.iloc[i]['high'])
                    })
            
            # Add psychological levels (round numbers)
            base = int(recent_price / 100) * 100
            for offset in [50, 100, 150, 200, 250]:
                support_levels.append({'level': float(base + offset), 'strength': 0.3, 'type': 'PSYCHOLOGICAL'})
                resistance_levels.append({'level': float(base + offset + 100), 'strength': 0.3, 'type': 'PSYCHOLOGICAL'})
            
            with self.lock:
                # Sort by proximity to current price
                support_levels = sorted(support_levels, key=lambda x: x['distance'] if 'distance' in x else 999)[:5]
                resistance_levels = sorted(resistance_levels, key=lambda x: x['distance'] if 'distance' in x else 999)[:5]
                
                self.levels = {'support': support_levels, 'resistance': resistance_levels}
            
            LOG.info(f"[SR_DETECT] Found {len(support_levels)} support, {len(resistance_levels)} resistance levels")
            
            return self.levels
        except Exception as e:
            LOG.warning(f"[SR_DETECT] Detection failed: {e}")
            return {'support': [], 'resistance': []}


